static int app_content_resource_id_ok(const char *id)
{
    size_t n;

    if (!id || !(n = strlen(id)) || n > 95)
        return 0;
    for (size_t i = 0; i < n; i++) {
        unsigned char c = (unsigned char)id[i];

        if (!isalnum(c) && c != '-' && c != '_' && c != '.')
            return 0;
    }
    return 1;
}

