static int webd_system_db_open(enum jmx_system_db_kind kind,
                               sqlite3 **out,
                               char *path, size_t path_len,
                               enum jmx_system_db_source *source,
                               char *error, size_t error_len)
{
    enum jmx_system_db_source resolved_source = JMX_SYSTEM_DB_SOURCE_NONE;
    sqlite3 *db = NULL;

    if (!out || !path || path_len == 0 || !error || error_len == 0)
        return -1;
    *out = NULL;
    path[0] = '\0';
    error[0] = '\0';
    if (source)
        *source = JMX_SYSTEM_DB_SOURCE_NONE;
    if (jmx_system_db_resolve(kind, path, path_len, &resolved_source,
                              error, error_len) != 0)
        return -1;
    if (source)
        *source = resolved_source;
    if (sqlite3_open_v2(path, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK || !db) {
        if (db)
            sqlite3_close(db);
        snprintf(error, error_len, "%s", "database_open_failed");
        return -1;
    }
    *out = db;
    return 0;
}

static void webd_system_db_diagnostic_add(struct json_object *resp,
                                          const char *path,
                                          enum jmx_system_db_source source,
                                          const char *error)
{
    if (!resp)
        return;
    json_object_object_add(resp, "db_path", json_object_new_string(path ? path : ""));
    json_object_object_add(resp, "db_source",
                           json_object_new_string(jmx_system_db_source_name(source)));
    json_object_object_add(resp, "source_error",
                           json_object_new_string(error ? error : ""));
}
