static struct json_object *webd_auth_failures_json(void)
{
    sqlite3_stmt *st;
    struct json_object *data = json_object_new_object();
    struct json_object *arr = json_object_new_array();
    int rc;

    st = config_prepare("SELECT scope,auth_key,fail_count,first_failed_at,last_failed_at,locked_until,banned,ban_reason FROM web_auth_failures ORDER BY updated_at DESC LIMIT 200");
    if (!st) {
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("auth_failures_query_failed"));
        json_object_object_add(data, "failures", arr);
        return data;
    }
    while ((rc = sqlite3_step(st)) == SQLITE_ROW) {
        struct json_object *o = json_object_new_object();
        json_object_object_add(o, "scope", json_object_new_string((const char *)sqlite3_column_text(st, 0)));
        json_object_object_add(o, "key", json_object_new_string((const char *)sqlite3_column_text(st, 1)));
        json_object_object_add(o, "fail_count", json_object_new_int(sqlite3_column_int(st, 2)));
        json_object_object_add(o, "first_failed_at", json_object_new_int64(sqlite3_column_int64(st, 3)));
        json_object_object_add(o, "last_failed_at", json_object_new_int64(sqlite3_column_int64(st, 4)));
        json_object_object_add(o, "locked_until", json_object_new_int64(sqlite3_column_int64(st, 5)));
        json_object_object_add(o, "banned", json_object_new_boolean(sqlite3_column_int(st, 6)));
        json_object_object_add(o, "ban_reason", json_object_new_string((const char *)sqlite3_column_text(st, 7)));
        json_object_array_add(arr, o);
    }
    sqlite3_finalize(st);
    if (rc != SQLITE_DONE) {
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("auth_failures_query_failed"));
        json_object_object_add(data, "failures", arr);
        return data;
    }
    json_object_object_add(data, "ok", json_object_new_boolean(1));
    json_object_object_add(data, "failures", arr);
    return data;
}

static struct json_object *webd_auth_failures_clear(struct json_object *body)
{
    const char *scope = app_nc_json_str(body, "scope", "");
    const char *key = app_nc_json_str(body, "key", "");
    struct json_object *data = json_object_new_object();
    sqlite3_stmt *st;
    int rc = SQLITE_OK;

    if (scope[0] && key[0]) {
        st = config_prepare("DELETE FROM web_auth_failures WHERE scope=?1 AND auth_key=?2");
        if (!st) {
            json_object_object_add(data, "ok", json_object_new_boolean(0));
            json_object_object_add(data, "error", json_object_new_string("auth_failures_clear_failed"));
            return data;
        }
        sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(st, 2, key, -1, SQLITE_TRANSIENT);
        rc = sqlite3_step(st);
        sqlite3_finalize(st);
    } else {
        rc = config_db_exec_checked("DELETE FROM web_auth_failures") == 0 ? SQLITE_DONE : SQLITE_ERROR;
    }
    if (rc != SQLITE_DONE && rc != SQLITE_OK) {
        json_object_object_add(data, "ok", json_object_new_boolean(0));
        json_object_object_add(data, "error", json_object_new_string("auth_failures_clear_failed"));
        return data;
    }
    json_object_object_add(data, "ok", json_object_new_boolean(1));
    return data;
}

static void webd_auth_key(const char *prefix, const char *value, char *out, size_t out_len)
{
    if (!out || out_len == 0)
        return;
    snprintf(out, out_len, "%s:%s", prefix ? prefix : "", value ? value : "");
}

static int webd_auth_failure_state(const char *scope, const char *key,
                                   int64_t *locked_until, int *banned)
{
    sqlite3_stmt *st;
    int found = 0;
    int rc;

    if (locked_until) *locked_until = 0;
    if (banned) *banned = 0;
    if (!scope || !key || !key[0])
        return 0;
    st = config_prepare("SELECT locked_until,banned FROM web_auth_failures WHERE scope=?1 AND auth_key=?2");
    if (!st) return -1;
    sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, key, -1, SQLITE_TRANSIENT);
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW) {
        if (locked_until) *locked_until = sqlite3_column_int64(st, 0);
        if (banned) *banned = sqlite3_column_int(st, 1);
        found = 1;
    } else if (rc != SQLITE_DONE) {
        found = -1;
    }
    sqlite3_finalize(st);
    return found;
}

static struct json_object *webd_login_block_response(const char *error, int64_t locked_until, int banned)
{
    struct json_object *data = json_object_new_object();
    int64_t now = now_s();

    json_object_object_add(data, "ok", json_object_new_boolean(0));
    json_object_object_add(data, "error", json_object_new_string(error ? error : "login_locked"));
    json_object_object_add(data, "locked_until", json_object_new_int64(locked_until));
    json_object_object_add(data, "retry_after", json_object_new_int64(locked_until > now ? locked_until - now : 0));
    json_object_object_add(data, "banned", json_object_new_boolean(banned));
    return data;
}

static int webd_auth_precheck(const char *username, const char *ip, struct json_object **err_out)
{
    struct webd_auth_settings s;
    int64_t now = now_s(), locked = 0;
    int banned = 0;
    char user_key[96];
    char ip_key[96];

    if (err_out) *err_out = NULL;
    if (webd_auth_settings_load(&s) != 0) {
        if (err_out) {
            struct json_object *data = json_object_new_object();
            json_object_object_add(data, "ok", json_object_new_boolean(0));
            json_object_object_add(data, "error", json_object_new_string("auth_settings_unavailable"));
            *err_out = data;
        }
        return -1;
    }
    if (!s.brute_enabled)
        return 0;
    if (username && username[0]) {
        int state_rc;

        webd_auth_key("user", username, user_key, sizeof(user_key));
        state_rc = webd_auth_failure_state("user", user_key, &locked, &banned);
        if (state_rc < 0) {
            if (err_out) {
                struct json_object *data = json_object_new_object();
                json_object_object_add(data, "ok", json_object_new_boolean(0));
                json_object_object_add(data, "error", json_object_new_string("auth_state_unavailable"));
                *err_out = data;
            }
            return -1;
        }
        if (state_rc && (banned || locked > now)) {
            if (err_out) *err_out = webd_login_block_response(banned ? "user_banned" : "user_locked", locked, banned);
            return -1;
        }
    }
    if (ip && ip[0]) {
        int state_rc;

        webd_auth_key("ip", ip, ip_key, sizeof(ip_key));
        state_rc = webd_auth_failure_state("ip", ip_key, &locked, &banned);
        if (state_rc < 0) {
            if (err_out) {
                struct json_object *data = json_object_new_object();
                json_object_object_add(data, "ok", json_object_new_boolean(0));
                json_object_object_add(data, "error", json_object_new_string("auth_state_unavailable"));
                *err_out = data;
            }
            return -1;
        }
        if (state_rc && (banned || locked > now)) {
            if (err_out) *err_out = webd_login_block_response(banned ? "ip_banned" : "ip_locked", locked, banned);
            return -1;
        }
    }
    return 0;
}

static void webd_auth_clear_failure(const char *scope, const char *key)
{
    sqlite3_stmt *st;

    if (!scope || !key || !key[0])
        return;
    st = config_prepare("DELETE FROM web_auth_failures WHERE scope=?1 AND auth_key=?2");
    if (!st) return;
    sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, key, -1, SQLITE_TRANSIENT);
    sqlite3_step(st);
    sqlite3_finalize(st);
}

static void webd_auth_clear_success(const char *username, const char *ip)
{
    char key[96];

    if (username && username[0]) {
        webd_auth_key("user", username, key, sizeof(key));
        webd_auth_clear_failure("user", key);
    }
    if (ip && ip[0]) {
        webd_auth_key("ip", ip, key, sizeof(key));
        webd_auth_clear_failure("ip", key);
    }
}

static struct json_object *webd_auth_record_unavailable_response(void)
{
    struct json_object *data = json_object_new_object();

    json_object_object_add(data, "ok", json_object_new_boolean(0));
    json_object_object_add(data, "error", json_object_new_string("auth_failure_record_unavailable"));
    json_object_object_add(data, "message", json_object_new_string("authentication failure state could not be updated"));
    return data;
}

static int webd_auth_record_failure_one(const char *scope, const char *key,
                                        int window_s, int max_failures,
                                        int lock_s, int ban_enabled, int ban_s,
                                        const char *reason)
{
    sqlite3_stmt *st;
    int64_t now = now_s(), first = now, locked_until = 0;
    int count = 0, banned = 0;
    int rc;

    if (!scope || !key || !key[0])
        return 0;
    st = config_prepare("SELECT fail_count,first_failed_at,banned FROM web_auth_failures WHERE scope=?1 AND auth_key=?2");
    if (!st)
        return -1;
    sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, key, -1, SQLITE_TRANSIENT);
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW) {
        count = sqlite3_column_int(st, 0);
        first = sqlite3_column_int64(st, 1);
        banned = sqlite3_column_int(st, 2);
    } else if (rc != SQLITE_DONE) {
        sqlite3_finalize(st);
        return -1;
    }
    sqlite3_finalize(st);
    if (window_s <= 0 || now - first > window_s) {
        first = now;
        count = 0;
    }
    count++;
    if (!banned && max_failures > 0 && count >= max_failures) {
        locked_until = ban_enabled && ban_s == 0 ? 0 : now + (ban_enabled && ban_s > 0 ? ban_s : lock_s);
        if (ban_enabled && ban_s == 0)
            banned = 1;
        else if (lock_s > 0 && locked_until == 0)
            locked_until = now + lock_s;
    }
    st = config_prepare(
        "INSERT INTO web_auth_failures(scope,auth_key,fail_count,first_failed_at,last_failed_at,locked_until,banned,ban_reason,updated_at) "
        "VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?5) "
        "ON CONFLICT(scope,auth_key) DO UPDATE SET fail_count=excluded.fail_count,first_failed_at=excluded.first_failed_at,"
        "last_failed_at=excluded.last_failed_at,locked_until=excluded.locked_until,banned=excluded.banned,"
        "ban_reason=excluded.ban_reason,updated_at=excluded.updated_at");
    if (!st)
        return -1;
    sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, key, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 3, count);
    sqlite3_bind_int64(st, 4, first);
    sqlite3_bind_int64(st, 5, now);
    sqlite3_bind_int64(st, 6, locked_until);
    sqlite3_bind_int(st, 7, banned);
    sqlite3_bind_text(st, 8, reason ? reason : "auth_failed", -1, SQLITE_TRANSIENT);
    rc = sqlite3_step(st);
    sqlite3_finalize(st);
    return rc == SQLITE_DONE ? 0 : -1;
}

static int webd_auth_record_failure(const char *username, const char *ip, const char *reason)
{
    struct webd_auth_settings s;
    char key[96];
    int rc = 0;

    if (webd_auth_settings_load(&s) != 0)
        return -1;
    if (!s.brute_enabled)
        return 0;
    if (username && username[0]) {
        webd_auth_key("user", username, key, sizeof(key));
        if (webd_auth_record_failure_one("user", key, s.fail_window_s, s.max_failures,
                                         s.lock_s, 0, 0, reason) != 0)
            rc = -1;
    }
    if (ip && ip[0]) {
        webd_auth_key("ip", ip, key, sizeof(key));
        if (webd_auth_record_failure_one("ip", key, s.ip_fail_window_s, s.ip_max_failures,
                                         s.lock_s, s.ip_ban_enabled, s.ip_ban_s, reason) != 0)
            rc = -1;
    }
    return rc;
}

static int webd_user_count(void)
{
    sqlite3_stmt *st = config_prepare("SELECT COUNT(*) FROM web_users");
    int n = -1;

    if (!st) return -1;
    if (sqlite3_step(st) == SQLITE_ROW)
        n = sqlite3_column_int(st, 0);
    sqlite3_finalize(st);
    return n;
}

static int webd_default_first_run_login(const char *username, const char *password)
{
    return username && password && !strcmp(username, "root") && !strcmp(password, "password");
}

static void webd_init_token_issue(char *out, size_t out_len)
{
    if (!out || out_len == 0)
        return;
    gen_random_hex(g_webd_init_token, WEBD_INIT_TOKEN_LEN);
    g_webd_init_token_expires_at = now_s() + WEBD_INIT_TOKEN_TTL_S;
    snprintf(out, out_len, "%s", g_webd_init_token);
}

static int webd_init_token_verify(const char *token, int consume)
{
    if (!token || !token[0] || !g_webd_init_token[0])
        return 0;
    if (g_webd_init_token_expires_at <= now_s()) {
        g_webd_init_token[0] = '\0';
        g_webd_init_token_expires_at = 0;
        return 0;
    }
    if (strcmp(token, g_webd_init_token))
        return 0;
    if (consume) {
        g_webd_init_token[0] = '\0';
        g_webd_init_token_expires_at = 0;
    }
    return 1;
}

static int webd_setup_session_clear(void)
{
    sqlite3_stmt *st = app_prepare("DELETE FROM setup_sessions WHERE id=1");
    int rc;

    if (!st)
        return -1;
    rc = app_step_done(st);
    sqlite3_finalize(st);
    return rc;
}

static int webd_setup_session_active(void)
{
    sqlite3_stmt *st = app_prepare(
        "SELECT expires_at FROM setup_sessions WHERE id=1");
    sqlite3_int64 now = now_s();
    int step_rc;
    int active = 0;

    if (!st)
        return -1;
    step_rc = sqlite3_step(st);
    if (step_rc == SQLITE_ROW)
        active = sqlite3_column_int64(st, 0) > now;
    else if (step_rc != SQLITE_DONE)
        active = -1;
    sqlite3_finalize(st);
    if (active == 0 && webd_setup_session_clear() != 0)
        return -1;
    return active;
}

static int webd_setup_session_claim(const char *client_ip,
                                    char *token, size_t token_len,
                                    int *already_active)
{
    char generated[WEBD_SETUP_SESSION_TOKEN_LEN + 1];
    char token_hash[65];
    sqlite3_stmt *st = NULL;
    sqlite3_int64 now = now_s();
    int rc = -1;

    if (already_active)
        *already_active = 0;
    if (!token || token_len <= WEBD_SETUP_SESSION_TOKEN_LEN ||
        !client_ip || !client_ip[0] || !g_app_db)
        return -1;
    gen_random_hex(generated, WEBD_SETUP_SESSION_TOKEN_LEN);
    if (webd_token_sha256(generated, token_hash) != 0) {
        OPENSSL_cleanse(generated, sizeof(generated));
        return -1;
    }
    if (sqlite3_exec(g_app_db, "BEGIN IMMEDIATE", NULL, NULL, NULL) != SQLITE_OK)
        goto done;
    st = app_prepare(
        "SELECT 1 FROM setup_sessions WHERE id=1 AND expires_at>?1");
    if (!st)
        goto rollback;
    sqlite3_bind_int64(st, 1, now);
    {
        int step_rc = sqlite3_step(st);

        if (step_rc != SQLITE_ROW && step_rc != SQLITE_DONE)
            goto rollback;
        if (step_rc == SQLITE_ROW) {
            if (already_active)
                *already_active = 1;
            sqlite3_finalize(st);
            st = NULL;
            goto rollback;
        }
    }
    sqlite3_finalize(st);
    st = app_prepare(
        "INSERT INTO setup_sessions(id,token_hash,client_ip,created_at,expires_at,last_seen_at) "
        "VALUES(1,?1,?2,?3,?4,?3) "
        "ON CONFLICT(id) DO UPDATE SET token_hash=excluded.token_hash,"
        "client_ip=excluded.client_ip,created_at=excluded.created_at,"
        "expires_at=excluded.expires_at,last_seen_at=excluded.last_seen_at");
    if (!st)
        goto rollback;
    sqlite3_bind_text(st, 1, token_hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, client_ip, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 3, now);
    sqlite3_bind_int64(st, 4, now + WEBD_SETUP_SESSION_TTL_S);
    if (app_step_done(st) != 0)
        goto rollback;
    sqlite3_finalize(st);
    st = NULL;
    if (sqlite3_exec(g_app_db, "COMMIT", NULL, NULL, NULL) != SQLITE_OK)
        goto rollback_after_commit;
    snprintf(token, token_len, "%s", generated);
    rc = 0;
    goto done;

rollback:
    if (st)
        sqlite3_finalize(st);
    sqlite3_exec(g_app_db, "ROLLBACK", NULL, NULL, NULL);
    goto done;
rollback_after_commit:
    sqlite3_exec(g_app_db, "ROLLBACK", NULL, NULL, NULL);
done:
    OPENSSL_cleanse(token_hash, sizeof(token_hash));
    OPENSSL_cleanse(generated, sizeof(generated));
    return rc;
}

static int webd_setup_session_verify(const char *token,
                                     const char *client_ip, int touch)
{
    char supplied_hash[65];
    char stored_hash[65] = "";
    char stored_ip[64] = "";
    sqlite3_stmt *st;
    sqlite3_int64 now = now_s();
    int step_rc;
    int valid = 0;

    if (!token || !token[0] || !client_ip || !client_ip[0] ||
        webd_token_sha256(token, supplied_hash) != 0)
        return 0;
    st = app_prepare(
        "SELECT token_hash,client_ip FROM setup_sessions "
        "WHERE id=1 AND expires_at>?1");
    if (!st) {
        OPENSSL_cleanse(supplied_hash, sizeof(supplied_hash));
        return -1;
    }
    sqlite3_bind_int64(st, 1, now);
    step_rc = sqlite3_step(st);
    if (step_rc == SQLITE_ROW) {
        snprintf(stored_hash, sizeof(stored_hash), "%s",
            sqlite3_column_text(st, 0) ?
            (const char *)sqlite3_column_text(st, 0) : "");
        snprintf(stored_ip, sizeof(stored_ip), "%s",
            sqlite3_column_text(st, 1) ?
            (const char *)sqlite3_column_text(st, 1) : "");
    }
    sqlite3_finalize(st);
    if (step_rc != SQLITE_ROW && step_rc != SQLITE_DONE) {
        OPENSSL_cleanse(supplied_hash, sizeof(supplied_hash));
        return -1;
    }
    valid = stored_hash[0] && !strcmp(client_ip, stored_ip) &&
            ct_str_equal(supplied_hash, stored_hash);
    OPENSSL_cleanse(supplied_hash, sizeof(supplied_hash));
    OPENSSL_cleanse(stored_hash, sizeof(stored_hash));
    OPENSSL_cleanse(stored_ip, sizeof(stored_ip));
    if (valid && touch) {
        st = app_prepare(
            "UPDATE setup_sessions SET expires_at=?1,last_seen_at=?2 "
            "WHERE id=1 AND expires_at>?2");
        if (!st)
            return -1;
        sqlite3_bind_int64(st, 1, now + WEBD_SETUP_SESSION_TTL_S);
        sqlite3_bind_int64(st, 2, now);
        if (app_step_done(st) != 0) {
            sqlite3_finalize(st);
            return -1;
        }
        valid = sqlite3_changes(g_app_db) > 0;
        sqlite3_finalize(st);
    }
    return valid;
}

static int webd_setup_session_actor(const char *token,
                                    const char *client_ip,
                                    char *out, size_t out_len)
{
    char token_hash[65];

    if (!out || out_len == 0)
        return 0;
    if (webd_setup_session_verify(token, client_ip, 0) != 1 ||
        webd_token_sha256(token, token_hash) != 0) {
        out[0] = '\0';
        return 0;
    }
    snprintf(out, out_len, "setup:%.32s", token_hash);
    OPENSSL_cleanse(token_hash, sizeof(token_hash));
    return 1;
}

static int webd_setup_owner_username(char *out, size_t out_len)
{
    sqlite3_stmt *st;
    int step_rc;

    if (!out || out_len == 0)
        return -1;
    out[0] = '\0';
    st = config_prepare(
        "SELECT username FROM web_users "
        "WHERE status='enabled' AND role IN ('owner','admin') "
        "ORDER BY created_at ASC,username ASC LIMIT 1");
    if (!st)
        return -1;
    step_rc = sqlite3_step(st);
    if (step_rc == SQLITE_ROW) {
        snprintf(out, out_len, "%s", sqlite3_column_text(st, 0) ?
            (const char *)sqlite3_column_text(st, 0) : "");
    }
    sqlite3_finalize(st);
    if (step_rc != SQLITE_ROW && step_rc != SQLITE_DONE)
        return -1;
    return out[0] ? 1 : 0;
}

static int webd_setup_twofa_challenge_store(const char *token,
                                            const char *client_ip,
                                            const char *username,
                                            const char *secret)
{
    char token_hash[65];
    char secret_hash[65];
    sqlite3_stmt *st;
    sqlite3_int64 now = now_s();
    int rc = -1;

    if (!username || !username[0] || !webd_totp_secret_ok(secret) ||
        webd_token_sha256(token, token_hash) != 0 ||
        webd_token_sha256(secret, secret_hash) != 0)
        return -1;
    st = app_prepare(
        "UPDATE setup_sessions SET twofa_username=?1,twofa_secret_hash=?2,"
        "twofa_prepared_at=?3 WHERE id=1 AND token_hash=?4 AND client_ip=?5 "
        "AND expires_at>?3");
    if (!st)
        goto done;
    sqlite3_bind_text(st, 1, username, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, secret_hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 3, now);
    sqlite3_bind_text(st, 4, token_hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 5, client_ip ? client_ip : "", -1,
                      SQLITE_TRANSIENT);
    if (app_step_done(st) == 0 && sqlite3_changes(g_app_db) == 1)
        rc = 0;
    sqlite3_finalize(st);
done:
    OPENSSL_cleanse(token_hash, sizeof(token_hash));
    OPENSSL_cleanse(secret_hash, sizeof(secret_hash));
    return rc;
}

static int webd_setup_twofa_challenge_verify(const char *token,
                                             const char *client_ip,
                                             const char *username,
                                             const char *secret)
{
    char token_hash[65];
    char secret_hash[65];
    char stored_username[65] = "";
    char stored_secret_hash[65] = "";
    sqlite3_stmt *st;
    sqlite3_int64 now = now_s();
    int step_rc;
    int valid = 0;

    if (!username || !username[0] || !webd_totp_secret_ok(secret) ||
        webd_token_sha256(token, token_hash) != 0 ||
        webd_token_sha256(secret, secret_hash) != 0)
        return 0;
    st = app_prepare(
        "SELECT twofa_username,twofa_secret_hash FROM setup_sessions "
        "WHERE id=1 AND token_hash=?1 AND client_ip=?2 AND expires_at>?3 "
        "AND twofa_prepared_at>0");
    if (!st) {
        valid = -1;
        goto done;
    }
    sqlite3_bind_text(st, 1, token_hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, client_ip ? client_ip : "", -1,
                      SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 3, now);
    step_rc = sqlite3_step(st);
    if (step_rc == SQLITE_ROW) {
        snprintf(stored_username, sizeof(stored_username), "%s",
            sqlite3_column_text(st, 0) ?
            (const char *)sqlite3_column_text(st, 0) : "");
        snprintf(stored_secret_hash, sizeof(stored_secret_hash), "%s",
            sqlite3_column_text(st, 1) ?
            (const char *)sqlite3_column_text(st, 1) : "");
        valid = !strcmp(username, stored_username) &&
                ct_str_equal(secret_hash, stored_secret_hash);
    } else if (step_rc != SQLITE_DONE) {
        valid = -1;
    }
    sqlite3_finalize(st);
done:
    OPENSSL_cleanse(token_hash, sizeof(token_hash));
    OPENSSL_cleanse(secret_hash, sizeof(secret_hash));
    OPENSSL_cleanse(stored_username, sizeof(stored_username));
    OPENSSL_cleanse(stored_secret_hash, sizeof(stored_secret_hash));
    return valid;
}

static int webd_setup_twofa_challenge_clear(const char *token,
                                            const char *client_ip)
{
    char token_hash[65];
    sqlite3_stmt *st;
    int rc = -1;

    if (webd_token_sha256(token, token_hash) != 0)
        return -1;
    st = app_prepare(
        "UPDATE setup_sessions SET twofa_username='',twofa_secret_hash='',"
        "twofa_prepared_at=0 WHERE id=1 AND token_hash=?1 AND client_ip=?2");
    if (st) {
        sqlite3_bind_text(st, 1, token_hash, -1, SQLITE_TRANSIENT);
        sqlite3_bind_text(st, 2, client_ip ? client_ip : "", -1,
                          SQLITE_TRANSIENT);
        if (app_step_done(st) == 0 && sqlite3_changes(g_app_db) == 1)
            rc = 0;
        sqlite3_finalize(st);
    }
    OPENSSL_cleanse(token_hash, sizeof(token_hash));
    return rc;
}

static void webd_setup_session_cookie(char *out, size_t out_len,
                                      const char *token, int clear)
{
    if (!out || out_len == 0)
        return;
    snprintf(out, out_len,
             WEBD_SETUP_SESSION_COOKIE "=%s; Path=/; Max-Age=%d; "
             "HttpOnly; SameSite=Strict\r\n",
             clear ? "" : (token ? token : ""),
             clear ? 0 : WEBD_SETUP_SESSION_TTL_S);
}

static int webd_user_create(const char *username, const char *password, const char *role)
{
    char hash[160];
    sqlite3_stmt *st;
    int64_t ts = now_s();
    int rc;

    if (!webd_username_ok(username) || !password || strlen(password) < 8)
        return -1;
    if (!webd_role_ok(role))
        role = "admin";
    if (webd_password_hash(password, hash, sizeof(hash)) != 0)
        return -1;
    st = config_prepare(
        "INSERT INTO web_users(username,password_hash,status,role,permissions_json,created_at,updated_at,last_login_at) "
        "VALUES(?1,?2,'enabled',?3,'[]',?4,?4,0)");
    if (!st) return -1;
    sqlite3_bind_text(st, 1, username, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 3, role, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 4, ts);
    rc = sqlite3_step(st) == SQLITE_DONE ? 0 : -1;
    sqlite3_finalize(st);
    return rc;
}

static int webd_user_authenticate(const char *username, const char *password,
                                  char *role, size_t role_len, int *state)
{
    sqlite3_stmt *st;
    const char *hash;
    const char *status;
    const char *role_s;
    int ok;
    int row_state = WEBD_AUTH_DB_INVALID;

    if (state)
        *state = WEBD_AUTH_DB_INVALID;
    if (!webd_username_ok(username) || !password || !role || role_len == 0)
        return 0;
    role[0] = '\0';
    st = config_prepare("SELECT password_hash,status,role FROM web_users WHERE username=?1");
    if (!st) {
        if (state) *state = WEBD_AUTH_DB_FAILED;
        return 0;
    }
    sqlite3_bind_text(st, 1, username, -1, SQLITE_TRANSIENT);
    if (!webd_sqlite_step_row(st, &row_state)) {
        sqlite3_finalize(st);
        if (row_state == WEBD_AUTH_DB_FAILED && state)
            *state = WEBD_AUTH_DB_FAILED;
        return 0;
    }
    hash = (const char *)sqlite3_column_text(st, 0);
    status = (const char *)sqlite3_column_text(st, 1);
    role_s = (const char *)sqlite3_column_text(st, 2);
    ok = status && !strcmp(status, "enabled") && webd_password_verify(password, hash);
    if (ok)
        snprintf(role, role_len, "%s", role_s && role_s[0] ? role_s : "admin");
    sqlite3_finalize(st);
    if (state)
        *state = ok ? WEBD_AUTH_DB_OK : WEBD_AUTH_DB_INVALID;
    return ok;
}

static int webd_user_get_role(const char *username, char *role, size_t role_len)
{
    sqlite3_stmt *st;
    const char *role_s;
    const char *status;
    int ok = 0;

    if (!webd_username_ok(username) || !role || role_len == 0)
        return 0;
    role[0] = '\0';
    st = config_prepare("SELECT role,status FROM web_users WHERE username=?1");
    if (!st) return 0;
    sqlite3_bind_text(st, 1, username, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) == SQLITE_ROW) {
        role_s = (const char *)sqlite3_column_text(st, 0);
        status = (const char *)sqlite3_column_text(st, 1);
        if (status && !strcmp(status, "enabled")) {
            snprintf(role, role_len, "%s", role_s && role_s[0] ? role_s : "admin");
            ok = 1;
        }
    }
    sqlite3_finalize(st);
    return ok;
}

static void webd_user_touch_login(const char *username)
{
    sqlite3_stmt *st = config_prepare("UPDATE web_users SET last_login_at=?1,updated_at=?1 WHERE username=?2");

    if (!st) return;
    sqlite3_bind_int64(st, 1, now_s());
    sqlite3_bind_text(st, 2, username ? username : "", -1, SQLITE_TRANSIENT);
    sqlite3_step(st);
    sqlite3_finalize(st);
}

static void webd_identity(char *out, size_t out_len, const char *username)
{
    if (!out || out_len == 0)
        return;
    snprintf(out, out_len, "web:%s", username ? username : "");
}

static int webd_identity_is_user(const char *identity)
{
    return identity && !strncmp(identity, "web:", 4) && identity[4];
}

static const char *webd_identity_username(const char *identity)
{
    return webd_identity_is_user(identity) ? identity + 4 : "";
}

static struct json_object *jmx_web_login_ex(struct json_object *req, const char *client_ip, int *http_status)
{
    const char *username = app_nc_json_str(req, "username", "");
    const char *password = app_nc_json_str(req, "password", "");
    const char *code = app_nc_json_str(req, "code", app_nc_json_str(req, "otp", app_nc_json_str(req, "totp", "")));
    int64_t ts = now_s();
    char role[32] = "admin";
    char access_tok[TOKEN_LEN + 1], refresh_tok[TOKEN_LEN + 1];
    char session_id[TOKEN_LEN + 1];
    char setup_token[WEBD_INIT_TOKEN_LEN + 1];
    struct json_object *resp;
    struct json_object *blocked = NULL;
    struct webd_twofa_state twofa;
    int64_t matched_counter = -1;
    int twofa_state = WEBD_AUTH_DB_INVALID;
    int user_auth_state = WEBD_AUTH_DB_INVALID;
    int users;

    if (http_status) *http_status = 401;

    if (webd_auth_precheck(username, client_ip, &blocked) != 0) {
        if (http_status) *http_status = 429;
        return blocked;
    }

    users = webd_user_count();
    if (users == 0) {
        if (!webd_default_first_run_login(username, password)) {
            if (webd_auth_record_failure(username, client_ip, "first_run_default_failed") != 0) {
                if (http_status) *http_status = 500;
                return webd_auth_record_unavailable_response();
            }
            return NULL;
        }
        setup_token[0] = '\0';
        webd_init_token_issue(setup_token, sizeof(setup_token));
        webd_auth_clear_success(username, client_ip);
        resp = json_object_new_object();
        json_object_object_add(resp, "ok", json_object_new_boolean(1));
        json_object_object_add(resp, "initialized", json_object_new_boolean(0));
        json_object_object_add(resp, "requires_initial_setup", json_object_new_boolean(1));
        json_object_object_add(resp, "setup_token", json_object_new_string(setup_token));
        json_object_object_add(resp, "setup_token_expires_in", json_object_new_int(WEBD_INIT_TOKEN_TTL_S));
        json_object_object_add(resp, "auth_type", json_object_new_string("first_run_default"));
        json_object_object_add(resp, "username", json_object_new_string("root"));
        json_object_object_add(resp, "message", json_object_new_string("default credentials accepted; create the first web administrator"));
        if (http_status) *http_status = 200;
        return resp;
    }
    if (users < 0) {
        (void)webd_auth_record_failure(username, client_ip, "config_db_unavailable");
        resp = json_object_new_object();
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "error", json_object_new_string("config_db_unavailable"));
        json_object_object_add(resp, "message", json_object_new_string("web user state is unavailable"));
        if (http_status) *http_status = 500;
        return resp;
    }

    if (!webd_user_authenticate(username, password, role, sizeof(role), &user_auth_state)) {
        if (user_auth_state == WEBD_AUTH_DB_FAILED) {
            resp = json_object_new_object();
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "error", json_object_new_string("user_auth_state_unavailable"));
            json_object_object_add(resp, "message", json_object_new_string("web user authentication state is unavailable"));
            if (http_status) *http_status = 500;
            return resp;
        }
        if (webd_auth_record_failure(username, client_ip, "password_failed") != 0) {
            if (http_status) *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return NULL;
    }

    memset(&twofa, 0, sizeof(twofa));
    twofa.last_counter = -1;
    if (!webd_user_twofa_get_ex(username, &twofa, &twofa_state)) {
        if (twofa_state == WEBD_AUTH_DB_FAILED) {
            resp = json_object_new_object();
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "error", json_object_new_string("twofa_state_unavailable"));
            json_object_object_add(resp, "message", json_object_new_string("2FA state is unavailable"));
            if (http_status) *http_status = 500;
            return resp;
        }
        if (webd_auth_record_failure(username, client_ip, "user_state_missing_after_password") != 0) {
            if (http_status) *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return NULL;
    }
    if (twofa.enabled) {
        if (!code[0]) {
            resp = json_object_new_object();
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "error", json_object_new_string("twofa_required"));
            json_object_object_add(resp, "requires_2fa", json_object_new_boolean(1));
            json_object_object_add(resp, "method", json_object_new_string("totp"));
            json_object_object_add(resp, "username", json_object_new_string(username));
            if (http_status) *http_status = 401;
            return resp;
        }
        if (!webd_totp_verify_secret(twofa.secret, code, twofa.step_s, twofa.digits,
                                    twofa.window, twofa.last_counter, &matched_counter)) {
            if (webd_auth_record_failure(username, client_ip, "twofa_failed") != 0) {
                if (http_status) *http_status = 500;
                return webd_auth_record_unavailable_response();
            }
            resp = json_object_new_object();
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "error", json_object_new_string("invalid_2fa_code"));
            json_object_object_add(resp, "requires_2fa", json_object_new_boolean(1));
            if (http_status) *http_status = 401;
            return resp;
        }
    }

    if (matched_counter >= 0 && webd_user_twofa_touch_counter(username, matched_counter) != 0) {
        resp = json_object_new_object();
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "error", json_object_new_string("twofa_counter_update_failed"));
        if (http_status) *http_status = 500;
        return resp;
    }

    gen_random_hex(access_tok, TOKEN_LEN);
    gen_random_hex(refresh_tok, TOKEN_LEN);
    gen_random_hex(session_id, TOKEN_LEN);
    if (webd_session_idle_login_insert(
            g_app_db, access_tok, ts + ACCESS_TTL_S,
            refresh_tok, ts + REFRESH_TTL_S, username, session_id, ts) !=
        WEBD_SESSION_IDLE_OK)
        return NULL;

    webd_user_touch_login(username);
    webd_auth_clear_success(username, client_ip);
    resp = json_object_new_object();
    json_object_object_add(resp, "access_token", json_object_new_string(access_tok));
    json_object_object_add(resp, "refresh_token", json_object_new_string(refresh_tok));
    json_object_object_add(resp, "expires_in", json_object_new_int(ACCESS_TTL_S));
    json_object_object_add(resp, "username", json_object_new_string(username));
    json_object_object_add(resp, "role", json_object_new_string(role));
    json_object_object_add(resp, "auth_type", json_object_new_string("web_user"));
    json_object_object_add(resp, "twofa_verified", json_object_new_boolean(twofa.enabled));
    if (http_status) *http_status = 200;
    return resp;
}

static void gen_pair_code(char *out)
{
    FILE *fp = fopen("/dev/urandom", "r");
    int i;
    for (i = 0; i < PAIR_CODE_LEN; i++) {
        int c = fp ? fgetc(fp) : (rand() % 10);
        out[i] = '0' + (c % 10);
    }
    if (fp) fclose(fp);
    out[PAIR_CODE_LEN] = '\0';
}

static int app_pair_device_id_ok(const char *device_id)
{
    size_t i, len;

    if (!device_id || !device_id[0])
        return 0;
    len = strlen(device_id);
    if (len > PAIR_DEVICE_ID_MAX)
        return 0;
    for (i = 0; i < len; i++) {
        unsigned char c = (unsigned char)device_id[i];

        if (!(isalnum(c) || c == '-' || c == '_' || c == '.' || c == ':'))
            return 0;
    }
    return 1;
}

static int app_pair_cleanup_expired(void)
{
    return app_db_exec_checked(
        "UPDATE app_devices SET approval_state='expired',pair_code_hash='' "
        "WHERE paired_at=0 AND pair_expires_at>0 AND pair_expires_at<strftime('%s','now') "
        "AND approval_state IN ('pending','approved')");
}

static int app_pair_pending_count_except(const char *device_id)
{
    sqlite3_stmt *st = app_prepare(
        "SELECT COUNT(*) FROM app_devices WHERE enabled=1 AND paired_at=0 "
        "AND pair_expires_at>0 AND pair_expires_at>=strftime('%s','now') "
        "AND approval_state IN ('pending','approved') "
        "AND id<>?1");
    int n = -1;
    int rc;

    if (!st)
        return -1;
    sqlite3_bind_text(st, 1, device_id ? device_id : "", -1, SQLITE_TRANSIENT);
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW)
        n = sqlite3_column_int(st, 0);
    sqlite3_finalize(st);
    return n;
}

static int app_pair_existing_device_count(int *count_out)
{
    sqlite3_stmt *st;
    int rc;

    if (count_out)
        *count_out = 0;
    st = app_prepare("SELECT COUNT(*) FROM app_devices WHERE paired_at>0");
    if (!st)
        return -1;
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW) {
        if (count_out)
            *count_out = sqlite3_column_int(st, 0);
        sqlite3_finalize(st);
        return 0;
    }
    sqlite3_finalize(st);
    return -1;
}

static int app_pair_web_owner_count(int *count_out)
{
    sqlite3_stmt *st;
    int rc;

    if (count_out)
        *count_out = 0;
    st = config_prepare(
        "SELECT COUNT(*) FROM web_users WHERE status='enabled' AND role='owner'");
    if (!st)
        return -1;
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW) {
        if (count_out)
            *count_out = sqlite3_column_int(st, 0);
        sqlite3_finalize(st);
        return 0;
    }
    sqlite3_finalize(st);
    return -1;
}

/* ══════════════════════════════════════════════════════════════════════
 * Auth / Pairing
 * ══════════════════════════════════════════════════════════════════════ */

static struct json_object *jmx_app_pair_error(const char *error, const char *message);

/*
 * Attaches the relay identity block the App needs to reach this router through
 * the cloud relay (GAP-RL-01):
 *
 *   "relay": {"router_id": "...", "router_public_key": "<base64 32B X25519>"}
 *
 * Sourced from dreamingos-cloud over ubus rather than generated here, because
 * that daemon owns the key material and router_id must come from the router
 * itself; if the relay could assign it, a relay operator could point a stored
 * App profile at a different router.
 *
 * Absence is not an error. When the component is not installed or not enabled,
 * the block is simply omitted and the App stays local-only, which is what makes
 * a phased rollout safe. A short timeout keeps a stalled component from
 * delaying the login path.
 */
static void app_attach_relay_identity(struct json_object *resp)
{
    struct json_object *reply;
    struct json_object *data = NULL;
    struct json_object *ok = NULL;
    struct json_object *router_id = NULL;
    struct json_object *public_key = NULL;
    struct json_object *relay;

    if (!resp)
        return;
    reply = app_ubus_invoke_object_timeout("dreamingos.cloud", "identity",
                                          NULL, 1000);
    if (!reply)
        return;
    if (!json_object_object_get_ex(reply, "ok", &ok) || !ok ||
        !json_object_get_boolean(ok) ||
        !json_object_object_get_ex(reply, "data", &data) || !data ||
        !json_object_object_get_ex(data, "router_id", &router_id) ||
        !json_object_object_get_ex(data, "router_public_key", &public_key) ||
        !router_id || !public_key ||
        !json_object_is_type(router_id, json_type_string) ||
        !json_object_is_type(public_key, json_type_string)) {
        json_object_put(reply);
        return;
    }

    relay = json_object_new_object();
    if (!relay) {
        json_object_put(reply);
        return;
    }
    json_object_object_add(relay, "router_id",
                           json_object_new_string(json_object_get_string(router_id)));
    json_object_object_add(relay, "router_public_key",
                           json_object_new_string(json_object_get_string(public_key)));
    json_object_object_add(resp, "relay", relay);
    json_object_put(reply);
}

static struct json_object *jmx_app_pair_init_ex(struct json_object *req,
                                                const char *client_ip,
                                                int *http_status)
{
    const char *device_id = app_nc_json_str(req, "app_device_id", "");
    const char *device_name = app_nc_json_str(req, "app_device_name", "");
    const char *platform = app_nc_json_str(req, "platform", "");
    const char *pubkey = app_nc_json_str(req, "public_key", "");
    struct json_object *blocked = NULL;
    char code[PAIR_CODE_LEN + 1];
    char code_hash[160];
    char status_token[TOKEN_LEN + 1];
    char status_token_hash[65];
    sqlite3_stmt *st;
    int pending;
    int device_count;
    int web_owner_count;

    if (http_status)
        *http_status = 400;
    if (!app_pair_device_id_ok(device_id))
        return jmx_app_pair_error("invalid_pair_device_id", "app_device_id is missing or unsafe");
    if (webd_auth_precheck("", client_ip, &blocked) != 0) {
        if (http_status)
            *http_status = 429;
        return blocked ? blocked : jmx_app_pair_error("pair_init_locked", "pair initialization is temporarily locked");
    }

    if (app_pair_cleanup_expired() != 0) {
        if (http_status)
            *http_status = 500;
        return jmx_app_pair_error("pair_cleanup_failed", "expired pair cleanup failed");
    }
    pending = app_pair_pending_count_except(device_id);
    if (pending < 0) {
        if (http_status)
            *http_status = 500;
        return jmx_app_pair_error("pair_pending_query_failed", "pending pair state is unavailable");
    }
    if (pending >= PAIR_PENDING_MAX) {
        if (webd_auth_record_failure("", client_ip, "pair_pending_limit") != 0) {
            if (http_status)
                *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return jmx_app_pair_error("too_many_pending_pairs", "too many pending pair requests");
    }

    int64_t ts = now_s();
    /* Determine role: first device becomes owner, rest are operator */
    const char *default_role = "operator";
    if (app_pair_existing_device_count(&device_count) != 0 ||
        app_pair_web_owner_count(&web_owner_count) != 0) {
        if (http_status)
            *http_status = 500;
        return jmx_app_pair_error("pair_device_count_failed", "paired device state is unavailable");
    }
    if (device_count == 0 && pending == 0 && web_owner_count == 0)
        default_role = "owner";

    gen_pair_code(code);
    if (webd_password_hash(code, code_hash, sizeof(code_hash)) != 0)
        return NULL;
    gen_random_hex(status_token, TOKEN_LEN);
    if (webd_token_sha256(status_token, status_token_hash) != 0)
        return NULL;

    st = app_prepare(
        "INSERT INTO app_devices(id,name,platform,public_key,pair_code_hash,paired_at,pair_expires_at,last_seen,role,approval_state,approved_at,approved_by,status_token_hash) "
        "VALUES(?1,?2,?3,?4,?5,0,?6,?7,?8,'pending',0,'',?9) "
        "ON CONFLICT(id) DO UPDATE SET name=excluded.name,platform=excluded.platform,"
        "public_key=excluded.public_key,pair_code_hash=excluded.pair_code_hash,"
        "paired_at=0,pair_expires_at=excluded.pair_expires_at,"
        "last_seen=excluded.last_seen,role=excluded.role,approval_state='pending',"
        "approved_at=0,approved_by='',status_token_hash=excluded.status_token_hash "
        "WHERE app_devices.paired_at=0");
    if (!st) return NULL;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, device_name, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 3, platform, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 4, pubkey, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 5, code_hash, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 6, ts + PAIR_TTL_S);
    sqlite3_bind_int64(st, 7, ts);
    sqlite3_bind_text(st, 8, default_role, -1, SQLITE_STATIC);
    sqlite3_bind_text(st, 9, status_token_hash, -1, SQLITE_TRANSIENT);
    if (app_step_done(st) != 0 || sqlite3_changes(g_app_db) <= 0) { sqlite3_finalize(st); return NULL; }
    sqlite3_finalize(st);

    struct json_object *resp = json_object_new_object();
    json_object_object_add(resp, "pair_id", json_object_new_string(device_id));
    json_object_object_add(resp, "code", json_object_new_string(code));
    json_object_object_add(resp, "status_token", json_object_new_string(status_token));
    json_object_object_add(resp, "state", json_object_new_string("pending_approval"));
    json_object_object_add(resp, "expires_in", json_object_new_int(PAIR_TTL_S));
    json_object_object_add(resp, "expires_at", json_object_new_int64(ts + PAIR_TTL_S));
    json_object_object_add(resp, "requires_local_confirm", json_object_new_boolean(1));
    if (http_status)
        *http_status = 200;
    return resp;
}

struct json_object *jmx_app_pair_init(struct json_object *req)
{
    return jmx_app_pair_init_ex(req, NULL, NULL);
}

static struct json_object *jmx_app_pair_error(const char *error, const char *message)
{
    struct json_object *resp = json_object_new_object();

    json_object_object_add(resp, "ok", json_object_new_boolean(0));
    json_object_object_add(resp, "error", json_object_new_string(error ? error : "pair_failed"));
    if (message && message[0])
        json_object_object_add(resp, "message", json_object_new_string(message));
    return resp;
}

static struct json_object *jmx_app_pair_confirm_ex(struct json_object *req,
                                                   const char *client_ip,
                                                   int *http_status)
{
    const char *device_id = app_nc_json_str(req, "app_device_id", "");
    const char *code = app_nc_json_str(req, "code", "");
    struct json_object *blocked = NULL;
    char stored_hash[160] = "";
    char approval_state[32] = "";
    int64_t ts = now_s();
    sqlite3_stmt *st;
    int rc;

    if (http_status)
        *http_status = 400;
    if (!app_pair_device_id_ok(device_id))
        return jmx_app_pair_error("invalid_pair_device_id", "app_device_id is missing or unsafe");
    if (!code[0])
        return jmx_app_pair_error("missing_pair_confirm", "app_device_id and code are required");
    if (webd_auth_precheck("", client_ip, &blocked) != 0) {
        if (http_status)
            *http_status = 429;
        return blocked ? blocked : jmx_app_pair_error("pair_confirm_locked", "pair confirmation is temporarily locked");
    }

    st = app_prepare(
        "SELECT pair_code_hash,approval_state FROM app_devices "
        "WHERE id=?1 AND enabled=1 AND paired_at=0 AND pair_expires_at>0 AND pair_expires_at>=?2");
    if (!st)
        return NULL;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, ts);
    rc = sqlite3_step(st);
    if (rc == SQLITE_ROW) {
        const char *hash = (const char *)sqlite3_column_text(st, 0);

        snprintf(stored_hash, sizeof(stored_hash), "%s", hash ? hash : "");
        snprintf(approval_state, sizeof(approval_state), "%s",
                 sqlite3_column_text(st, 1) ?
                 (const char *)sqlite3_column_text(st, 1) : "");
    } else if (rc != SQLITE_DONE) {
        sqlite3_finalize(st);
        if (http_status)
            *http_status = 500;
        return jmx_app_pair_error("pair_code_query_failed", "pair code state is unavailable");
    }
    sqlite3_finalize(st);
    if (!stored_hash[0] || !webd_password_verify(code, stored_hash)) {
        if (webd_auth_record_failure("", client_ip, "pair_confirm_failed") != 0) {
            if (http_status)
                *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return jmx_app_pair_error("invalid_pair_code", "pair code is invalid or expired");
    }
    if (strcmp(approval_state, "approved")) {
        if (http_status)
            *http_status = 409;
        return jmx_app_pair_error("pair_approval_required",
                                  "an authenticated owner must approve this pair request first");
    }

    st = app_prepare(
        "UPDATE app_devices SET paired_at=?1,pair_expires_at=0,pair_code_hash='',"
        "status_token_hash='',last_seen=?1 "
        "WHERE id=?2 AND enabled=1 AND paired_at=0 AND pair_code_hash=?3 "
        "AND approval_state='approved' AND approved_at>0 "
        "AND pair_expires_at>0 AND pair_expires_at>=?1");
    if (!st) return NULL;
    sqlite3_bind_int64(st, 1, ts);
    sqlite3_bind_text(st, 2, device_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 3, stored_hash, -1, SQLITE_TRANSIENT);
    if (app_step_done(st) != 0 || sqlite3_changes(g_app_db) <= 0) { sqlite3_finalize(st); return NULL; }
    sqlite3_finalize(st);

    /* Generate tokens */
    char access_tok[TOKEN_LEN + 1], refresh_tok[TOKEN_LEN + 1];
    gen_random_hex(access_tok, TOKEN_LEN);
    gen_random_hex(refresh_tok, TOKEN_LEN);

    if (app_insert_token(access_tok, device_id, "access", ts, ts + ACCESS_TTL_S) != 0 ||
        app_insert_token(refresh_tok, device_id, "refresh", ts, ts + REFRESH_TTL_S) != 0)
        return NULL;

    struct json_object *resp = json_object_new_object();
    webd_auth_clear_success("", client_ip);
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    json_object_object_add(resp, "access_token", json_object_new_string(access_tok));
    json_object_object_add(resp, "refresh_token", json_object_new_string(refresh_tok));
    json_object_object_add(resp, "expires_in", json_object_new_int(ACCESS_TTL_S));
    json_object_object_add(resp, "device_id", json_object_new_string(device_id));
    app_attach_relay_identity(resp);
    if (http_status)
        *http_status = 200;
    return resp;
}

struct json_object *jmx_app_pair_confirm(struct json_object *req)
{
    return jmx_app_pair_confirm_ex(req, NULL, NULL);
}

struct json_object *jmx_app_pair_cancel(struct json_object *req)
{
    const char *device_id = app_nc_json_str(req, "app_device_id", app_nc_json_str(req, "pair_id", ""));
    int canceled = 0;
    int rc;
    sqlite3_stmt *st;

    if (!app_pair_device_id_ok(device_id))
        return jmx_app_pair_error("invalid_pair_device_id", "app_device_id is missing or unsafe");
    st = app_prepare(
        "UPDATE app_devices SET approval_state='canceled',pair_code_hash='' "
        "WHERE id=?1 AND paired_at=0 AND approval_state IN ('pending','approved') "
        "AND NOT EXISTS (SELECT 1 FROM auth_tokens WHERE device_id=?1 "
        "AND revoked=0 AND expires_at>?2)");
    if (!st)
        return jmx_app_pair_error("pair_cancel_failed", "pair cancel state is unavailable");
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, now_s());
    rc = sqlite3_step(st);
    if (rc == SQLITE_DONE) {
        canceled = sqlite3_changes(g_app_db) > 0;
    } else {
        sqlite3_finalize(st);
        return jmx_app_pair_error("pair_cancel_failed", "pair cancel state update failed");
    }
    sqlite3_finalize(st);
    struct json_object *resp = json_object_new_object();
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    json_object_object_add(resp, "canceled", json_object_new_boolean(canceled));
    json_object_object_add(resp, "app_device_id", json_object_new_string(device_id));
    if (!canceled)
        json_object_object_add(resp, "reason", json_object_new_string("not_found_or_already_bound"));
    return resp;
}

static struct json_object *jmx_app_login_ex(struct json_object *req,
                                            const char *client_ip,
                                            int *http_status)
{
    const char *device_id = app_nc_json_str(req, "app_device_id", "");
    const char *refresh_token = app_nc_json_str(req, "refresh_token", "");
    struct json_object *blocked = NULL;
    int64_t ts = now_s();
    sqlite3_stmt *st;
    int rc;

    if (http_status)
        *http_status = 401;
    if (!app_pair_device_id_ok(device_id) || !refresh_token[0]) {
        if (webd_auth_record_failure("", client_ip, "app_login_missing_refresh") != 0) {
            if (http_status)
                *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return jmx_app_pair_error("refresh_token_required", "paired app login requires a valid refresh_token");
    }
    if (webd_auth_precheck("", client_ip, &blocked) != 0) {
        if (http_status)
            *http_status = 429;
        return blocked ? blocked : jmx_app_pair_error("app_login_locked", "app login is temporarily locked");
    }

    st = app_prepare(
        "SELECT 1 FROM auth_tokens t JOIN app_devices d ON d.id=t.device_id "
        "WHERE t.token=?1 AND t.device_id=?2 AND t.type='refresh' "
        "AND t.revoked=0 AND t.expires_at>?3 AND d.enabled=1 AND d.paired_at>0");
    if (!st) return NULL;
    sqlite3_bind_text(st, 1, refresh_token, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, device_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 3, ts);
    rc = sqlite3_step(st);
    if (rc != SQLITE_ROW) {
        sqlite3_finalize(st);
        if (rc != SQLITE_DONE) {
            if (http_status)
                *http_status = 500;
            return jmx_app_pair_error("app_login_query_failed", "paired app login state is unavailable");
        }
        if (webd_auth_record_failure("", client_ip, "app_login_invalid_refresh") != 0) {
            if (http_status)
                *http_status = 500;
            return webd_auth_record_unavailable_response();
        }
        return jmx_app_pair_error("invalid_refresh_token", "refresh_token is invalid for this app_device_id");
    }
    sqlite3_finalize(st);

    char access_tok[TOKEN_LEN + 1], refresh_tok[TOKEN_LEN + 1];
    gen_random_hex(access_tok, TOKEN_LEN);
    gen_random_hex(refresh_tok, TOKEN_LEN);

    /* Revoke old tokens for this device */
    st = app_prepare("UPDATE auth_tokens SET revoked=1 WHERE device_id=?1");
    if (!st) return NULL;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    if (app_step_done(st) != 0) { sqlite3_finalize(st); return NULL; }
    sqlite3_finalize(st);

    if (app_insert_token(access_tok, device_id, "access", ts, ts + ACCESS_TTL_S) != 0 ||
        app_insert_token(refresh_tok, device_id, "refresh", ts, ts + REFRESH_TTL_S) != 0)
        return NULL;

    st = app_prepare("UPDATE app_devices SET last_seen=?1 WHERE id=?2");
    if (st) { sqlite3_bind_int64(st, 1, ts); sqlite3_bind_text(st, 2, device_id, -1, SQLITE_TRANSIENT); sqlite3_step(st); sqlite3_finalize(st); }

    struct json_object *resp = json_object_new_object();
    webd_auth_clear_success("", client_ip);
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    json_object_object_add(resp, "access_token", json_object_new_string(access_tok));
    json_object_object_add(resp, "refresh_token", json_object_new_string(refresh_tok));
    json_object_object_add(resp, "expires_in", json_object_new_int(ACCESS_TTL_S));
    json_object_object_add(resp, "device_id", json_object_new_string(device_id));
    app_attach_relay_identity(resp);
    if (http_status)
        *http_status = 200;
    return resp;
}

struct json_object *jmx_app_login(struct json_object *req)
{
    return jmx_app_login_ex(req, NULL, NULL);
}

static struct json_object *jmx_app_refresh_ex(struct json_object *req, int *http_status,
                                             const char **error_code)
{
    const char *refresh_token = app_nc_json_str(req, "refresh_token", "");
    int row_state = WEBD_AUTH_DB_INVALID;

    if (http_status)
        *http_status = 401;
    if (error_code)
        *error_code = "invalid_refresh_token";
    if (!refresh_token[0]) return NULL;

    int64_t ts = now_s();
    sqlite3_stmt *st = app_prepare(
        "SELECT t.device_id FROM auth_tokens t "
        "JOIN app_devices d ON d.id=t.device_id "
        "WHERE t.token=?1 AND t.type='refresh' "
        "AND t.revoked=0 AND t.expires_at>?2 AND d.enabled=1 AND d.paired_at>0");
    if (!st) {
        if (http_status) *http_status = 500;
        if (error_code) *error_code = "refresh_query_failed";
        return NULL;
    }
    sqlite3_bind_text(st, 1, refresh_token, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, ts);
    if (!webd_sqlite_step_row(st, &row_state)) {
        sqlite3_finalize(st);
        if (row_state == WEBD_AUTH_DB_FAILED) {
            if (http_status) *http_status = 500;
            if (error_code) *error_code = "refresh_query_failed";
            return NULL;
        }
        struct webd_session_idle_info idle_info;
        char access_tok[TOKEN_LEN + 1];
        char role[32] = "admin";
        int idle_rc;

        gen_random_hex(access_tok, TOKEN_LEN);
        idle_rc = webd_session_idle_refresh_issue(
            g_config_db, g_app_db, refresh_token, access_tok,
            ts + ACCESS_TTL_S, ts, &idle_info);
        if (idle_rc != WEBD_SESSION_IDLE_OK) {
            if (http_status)
                *http_status = idle_rc == WEBD_SESSION_IDLE_DB_ERROR ? 500 : 401;
            if (error_code)
                *error_code = webd_session_idle_error(idle_rc);
            return NULL;
        }
        if (!webd_user_get_role(idle_info.username, role, sizeof(role))) {
            if (http_status) *http_status = 500;
            if (error_code) *error_code = "refresh_session_user_unavailable";
            return NULL;
        }
        struct json_object *web = json_object_new_object();
        json_object_object_add(web, "access_token", json_object_new_string(access_tok));
        json_object_object_add(web, "expires_in", json_object_new_int(ACCESS_TTL_S));
        json_object_object_add(web, "username", json_object_new_string(idle_info.username));
        json_object_object_add(web, "role", json_object_new_string(role));
        json_object_object_add(web, "auth_type", json_object_new_string("web_user"));
        if (http_status) *http_status = 200;
        if (error_code) *error_code = NULL;
        return web;
    }
    const unsigned char *device_txt = sqlite3_column_text(st, 0);
    if (!device_txt) {
        sqlite3_finalize(st);
        if (http_status) *http_status = 500;
        if (error_code) *error_code = "refresh_session_corrupt";
        return NULL;
    }
    char *device_id = strdup((const char *)device_txt);
    sqlite3_finalize(st);
    if (!device_id) {
        if (http_status) *http_status = 500;
        if (error_code) *error_code = "refresh_session_unavailable";
        return NULL;
    }

    char access_tok[TOKEN_LEN + 1];
    gen_random_hex(access_tok, TOKEN_LEN);

    if (app_insert_token(access_tok, device_id, "access", ts, ts + ACCESS_TTL_S) != 0) {
        free(device_id);
        if (http_status) *http_status = 500;
        if (error_code) *error_code = "refresh_session_create_failed";
        return NULL;
    }

    struct json_object *resp = json_object_new_object();
    json_object_object_add(resp, "access_token", json_object_new_string(access_tok));
    json_object_object_add(resp, "expires_in", json_object_new_int(ACCESS_TTL_S));
    free(device_id);
    if (http_status) *http_status = 200;
    if (error_code) *error_code = NULL;
    return resp;
}

struct json_object *jmx_app_refresh(struct json_object *req)
{
    return jmx_app_refresh_ex(req, NULL, NULL);
}

static struct json_object *jmx_app_logout_ex(struct json_object *req, int *http_status)
{
    const char *tokens[3];
    int i;
    int failed = 0;

    tokens[0] = app_nc_json_str(req, "access_token", "");
    tokens[1] = app_nc_json_str(req, "refresh_token", "");
    tokens[2] = app_nc_json_str(req, "token", "");
    if (http_status)
        *http_status = 200;
    if (!tokens[0][0] && !tokens[1][0] && !tokens[2][0])
        return NULL;
    for (i = 0; i < 3; i++) {
        sqlite3_stmt *st;

        if (!tokens[i][0])
            continue;
        st = app_prepare("UPDATE auth_tokens SET revoked=1 WHERE token=?1");
        if (st) {
            sqlite3_bind_text(st, 1, tokens[i], -1, SQLITE_TRANSIENT);
            if (app_step_done(st) != 0)
                failed = 1;
            sqlite3_finalize(st);
        } else {
            failed = 1;
        }
        st = app_prepare("UPDATE web_sessions SET revoked=1 WHERE token=?1");
        if (st) {
            sqlite3_bind_text(st, 1, tokens[i], -1, SQLITE_TRANSIENT);
            if (app_step_done(st) != 0)
                failed = 1;
            sqlite3_finalize(st);
        } else {
            failed = 1;
        }
    }
    if (failed) {
        if (http_status)
            *http_status = 500;
        return jmx_app_pair_error("logout_revoke_failed", "logout token revoke state is unavailable");
    }
    struct json_object *resp = json_object_new_object();
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    return resp;
}

struct json_object *jmx_app_logout(struct json_object *req)
{
    return jmx_app_logout_ex(req, NULL);
}

static struct json_object *jmx_app_session_ex(const char *token, int *state)
{
    int row_state = WEBD_AUTH_DB_INVALID;

    if (state)
        *state = WEBD_AUTH_DB_INVALID;
    if (!token || !token[0]) return NULL;
    int64_t ts = now_s();
    sqlite3_stmt *st = app_prepare(
        "SELECT t.device_id,d.name,d.platform,d.role FROM auth_tokens t "
        "JOIN app_devices d ON d.id=t.device_id "
        "WHERE t.token=?1 AND t.type='access' AND t.revoked=0 AND t.expires_at>?2 "
        "AND d.enabled=1 AND d.paired_at>0");
    if (!st) {
        if (state) *state = WEBD_AUTH_DB_FAILED;
        return NULL;
    }
    sqlite3_bind_text(st, 1, token, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, ts);
    if (!webd_sqlite_step_row(st, &row_state)) {
        struct webd_session_idle_info idle_info;
        int idle_rc;

        sqlite3_finalize(st);
        if (row_state == WEBD_AUTH_DB_FAILED) {
            if (state) *state = WEBD_AUTH_DB_FAILED;
            return NULL;
        }
        idle_rc = webd_session_idle_access_check(
            g_config_db, g_app_db, token, ts, 1, &idle_info);
        if (idle_rc != WEBD_SESSION_IDLE_OK) {
            if (state)
                *state = idle_rc == WEBD_SESSION_IDLE_TIMEOUT ?
                         WEBD_AUTH_DB_IDLE_TIMEOUT :
                         idle_rc == WEBD_SESSION_IDLE_DB_ERROR ?
                         WEBD_AUTH_DB_FAILED : WEBD_AUTH_DB_INVALID;
            return NULL;
        }

        char role[32] = "admin";
        if (!webd_user_get_role(idle_info.username, role, sizeof(role)))
            return NULL;
        struct json_object *web = json_object_new_object();
        json_object_object_add(web, "device_id", json_object_new_string(idle_info.username));
        json_object_object_add(web, "username", json_object_new_string(idle_info.username));
        json_object_object_add(web, "device_name", json_object_new_string(idle_info.username));
        json_object_object_add(web, "platform", json_object_new_string("web"));
        json_object_object_add(web, "role", json_object_new_string(role));
        json_object_object_add(web, "auth_type", json_object_new_string("web_user"));
        json_object_object_add(web, "valid", json_object_new_boolean(1));
        json_object_object_add(web, "web_login_timeout_min",
                               json_object_new_int(idle_info.timeout_min));
        json_object_object_add(web, "idle_deadline_at",
                               json_object_new_int64(idle_info.idle_deadline_at));
        if (state) *state = WEBD_AUTH_DB_OK;
        return web;
    }

    struct json_object *resp = json_object_new_object();
    json_object_object_add(resp, "device_id", json_object_new_string((const char *)sqlite3_column_text(st, 0)));
    json_object_object_add(resp, "device_name", json_object_new_string((const char *)sqlite3_column_text(st, 1)));
    json_object_object_add(resp, "platform", json_object_new_string((const char *)sqlite3_column_text(st, 2)));
    json_object_object_add(resp, "role", json_object_new_string((const char *)sqlite3_column_text(st, 3)));
    json_object_object_add(resp, "valid", json_object_new_boolean(1));
    sqlite3_finalize(st);
    if (state) *state = WEBD_AUTH_DB_OK;
    return resp;
}

struct json_object *jmx_app_session(const char *token)
{
    return jmx_app_session_ex(token, NULL);
}

static char *jmx_app_validate_token_mode(const char *token, int *state,
                                         int record_activity)
{
    int row_state = WEBD_AUTH_DB_INVALID;

    if (state)
        *state = WEBD_AUTH_DB_INVALID;
    if (!token || !token[0]) return NULL;
    int64_t ts = now_s();
    sqlite3_stmt *st = app_prepare(
        "SELECT t.device_id FROM auth_tokens t "
        "JOIN app_devices d ON d.id=t.device_id "
        "WHERE t.token=?1 AND t.type='access' "
        "AND t.revoked=0 AND t.expires_at>?2 AND d.enabled=1 AND d.paired_at>0");
    if (!st) {
        if (state) *state = WEBD_AUTH_DB_FAILED;
        return NULL;
    }
    sqlite3_bind_text(st, 1, token, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, ts);
    char *dev = NULL;
    if (webd_sqlite_step_row(st, &row_state)) {
        const char *s = (const char *)sqlite3_column_text(st, 0);
        if (s) dev = strdup(s);
    } else if (row_state == WEBD_AUTH_DB_FAILED) {
        if (state) *state = WEBD_AUTH_DB_FAILED;
        sqlite3_finalize(st);
        return NULL;
    }
    sqlite3_finalize(st);
    if (dev) {
        if (state) *state = WEBD_AUTH_DB_OK;
        return dev;
    }

    {
        struct webd_session_idle_info idle_info;
        int idle_rc = webd_session_idle_access_check(
            g_config_db, g_app_db, token, ts, record_activity, &idle_info);

        if (idle_rc == WEBD_SESSION_IDLE_OK) {
            char role[32];

            if (webd_user_get_role(idle_info.username, role, sizeof(role))) {
                size_t n = strlen(idle_info.username) + 5;
                dev = (char *)malloc(n);
                if (dev)
                    webd_identity(dev, n, idle_info.username);
            }
        } else if (state) {
            *state = idle_rc == WEBD_SESSION_IDLE_TIMEOUT ?
                     WEBD_AUTH_DB_IDLE_TIMEOUT :
                     idle_rc == WEBD_SESSION_IDLE_DB_ERROR ?
                     WEBD_AUTH_DB_FAILED : WEBD_AUTH_DB_INVALID;
        }
    }
    if (dev && state)
        *state = WEBD_AUTH_DB_OK;
    return dev;
}

static char *jmx_app_validate_token_ex(const char *token, int *state)
{
    return jmx_app_validate_token_mode(token, state, 1);
}

char *jmx_app_validate_token(const char *token)
{
    return jmx_app_validate_token_ex(token, NULL);
}

/*
 * Decodes a base64 value that must yield exactly `expected` bytes.
 *
 * Self-contained rather than reusing webd_base64_decode_strict() because that
 * helper is defined much further down this file and the project builds with
 * -Werror=implicit-function-declaration; a forward declaration for one small
 * fixed-size decode is more indirection than the check is worth.
 */
static int webd_app_base64_decode_exact(const char *encoded, unsigned char *out,
                                        size_t expected)
{
    unsigned char buffer[64];
    size_t length, padding = 0;
    int decoded_length;

    if (!encoded || !out || !expected)
        return -1;
    length = strlen(encoded);
    /* EVP_DecodeBlock writes in 3-byte groups, so the scratch buffer has to
     * hold the rounded-up size rather than exactly `expected`. */
    if (!length || (length % 4) != 0 || length / 4 * 3 > sizeof(buffer))
        return -1;
    if (encoded[length - 1] == '=')
        padding++;
    if (length > 1 && encoded[length - 2] == '=')
        padding++;

    decoded_length = EVP_DecodeBlock(buffer, (const unsigned char *)encoded,
                                     (int)length);
    if (decoded_length <= 0 || (size_t)decoded_length < padding)
        return -1;
    if ((size_t)decoded_length - padding != expected)
        return -1;
    memcpy(out, buffer, expected);
    OPENSSL_cleanse(buffer, sizeof(buffer));
    return 0;
}

/*
 * Fingerprint of an App's registered key material (GAP-RL-02).
 *
 * SHA256 of the raw 32-byte X25519 agreement key, first 8 bytes, uppercase hex
 * grouped in fours: A1B2-C3D4-E5F6-0718. The App computes the same value, so a
 * user can compare the two by eye and notice a substituted key.
 *
 * Returns 0 on success. Anything that is not the expected JSON shape yields a
 * failure rather than a partial value, so the caller reports null plus a reason
 * instead of showing a fingerprint that means nothing.
 */
static int webd_app_device_key_fingerprint(const char *stored, char *out,
                                           size_t out_size)
{
    static const char hex[] = "0123456789ABCDEF";
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_length = 0;
    unsigned char raw[32];
    struct json_object *root;
    struct json_object *value = NULL;
    const char *encoded;
    size_t i, o = 0;
    int rc = -1;

    if (!stored || !stored[0] || !out || out_size < 20)
        return -1;
    root = json_tokener_parse(stored);
    if (!root || !json_object_is_type(root, json_type_object))
        goto done;
    if (!json_object_object_get_ex(root, "kex_pub", &value) || !value ||
        !json_object_is_type(value, json_type_string))
        goto done;
    encoded = json_object_get_string(value);
    if (webd_app_base64_decode_exact(encoded, raw, sizeof(raw)) != 0)
        goto done;
    /* EVP rather than the SHA256() shortcut so this file needs no extra
     * OpenSSL header beyond the evp.h it already includes. */
    if (EVP_Digest(raw, sizeof(raw), digest, &digest_length, EVP_sha256(),
                   NULL) != 1 || digest_length < 8)
        goto done;
    for (i = 0; i < 8; i++) {
        if (i && i % 2 == 0)
            out[o++] = '-';
        out[o++] = hex[(digest[i] >> 4) & 0x0f];
        out[o++] = hex[digest[i] & 0x0f];
    }
    out[o] = '\0';
    rc = 0;
done:
    if (root)
        json_object_put(root);
    OPENSSL_cleanse(raw, sizeof(raw));
    return rc;
}

struct json_object *jmx_app_devices_list(void)
{
    struct json_object *arr = json_object_new_array();
    sqlite3_stmt *st = app_prepare(
        "SELECT id,name,platform,paired_at,last_seen,role,enabled,pair_expires_at,"
        "approval_state,approved_at,approved_by,public_key,last_remote_seen,last_access_path "
        "FROM app_devices WHERE paired_at>0 OR pair_expires_at=0 OR pair_expires_at>=strftime('%s','now') "
        "ORDER BY last_seen DESC");
    if (st) {
        while (sqlite3_step(st) == SQLITE_ROW) {
            struct json_object *o = json_object_new_object();
            const char *stored_key = (const char *)sqlite3_column_text(st, 11);
            int64_t last_remote = sqlite3_column_int64(st, 12);
            const char *access_path = (const char *)sqlite3_column_text(st, 13);
            char fingerprint[24];

            json_object_object_add(o, "id", json_object_new_string((const char *)sqlite3_column_text(st, 0)));
            json_object_object_add(o, "name", json_object_new_string((const char *)sqlite3_column_text(st, 1)));
            json_object_object_add(o, "platform", json_object_new_string((const char *)sqlite3_column_text(st, 2)));
            json_object_object_add(o, "paired_at", json_object_new_int64(sqlite3_column_int64(st, 3)));
            json_object_object_add(o, "last_seen", json_object_new_int64(sqlite3_column_int64(st, 4)));
            json_object_object_add(o, "role", json_object_new_string((const char *)sqlite3_column_text(st, 5)));
            json_object_object_add(o, "enabled", json_object_new_boolean(sqlite3_column_int(st, 6)));
            json_object_object_add(o, "state", json_object_new_string(
                sqlite3_column_int64(st, 3) > 0 ? "paired" :
                ((const char *)sqlite3_column_text(st, 8) ?
                 (!strcmp((const char *)sqlite3_column_text(st, 8), "pending") ?
                  "pending_approval" :
                  (const char *)sqlite3_column_text(st, 8)) :
                 "pending_approval")));
            json_object_object_add(o, "expires_at", json_object_new_int64(sqlite3_column_int64(st, 7)));
            json_object_object_add(o, "approved_at", json_object_new_int64(sqlite3_column_int64(st, 9)));
            webd_obj_add_str(o, "approved_by", (const char *)sqlite3_column_text(st, 10));

            /* Key fingerprint, plus an explicit reason when it cannot be
             * derived; an App paired before key upload has no material here. */
            if (webd_app_device_key_fingerprint(stored_key, fingerprint,
                                                sizeof(fingerprint)) == 0) {
                json_object_object_add(o, "public_key_fingerprint",
                                       json_object_new_string(fingerprint));
            } else {
                json_object_object_add(o, "public_key_fingerprint", NULL);
                json_object_object_add(o, "public_key_fingerprint_reason",
                                       json_object_new_string(
                                           stored_key && stored_key[0] ?
                                               "key_material_unparsable" :
                                               "key_material_absent"));
            }

            /* Remote-access audit signal (GAP-RL-06). null rather than 0 so the
             * UI can distinguish "never" from "at the epoch". */
            if (last_remote > 0) {
                json_object_object_add(o, "last_remote_seen",
                                       json_object_new_int64(last_remote));
            } else {
                json_object_object_add(o, "last_remote_seen", NULL);
                json_object_object_add(o, "last_remote_seen_reason",
                                       json_object_new_string("no_remote_access_recorded"));
            }
            json_object_object_add(o, "last_access_path",
                                   access_path && access_path[0] ?
                                       json_object_new_string(access_path) :
                                       json_object_new_string("local"));
            json_object_array_add(arr, o);
        }
        sqlite3_finalize(st);
    }
    return arr;
}

static struct json_object *jmx_app_pair_status(const char *pair_id,
                                               const char *status_token,
                                               int owner_authenticated)
{
    struct json_object *resp = json_object_new_object();
    struct json_object *device = NULL;
    sqlite3_stmt *st;
    int64_t ts = now_s();
    int64_t paired_at = 0;
    int64_t expires_at = 0;
    int enabled = 0;
    int found = 0;
    const char *state = "not_found";
    char stored_status_hash[160] = "";
    char supplied_status_hash[65] = "";
    char approval_state[32] = "";

    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    json_object_object_add(resp, "pair_id", json_object_new_string(pair_id ? pair_id : ""));
    if (!app_pair_device_id_ok(pair_id)) {
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "state", json_object_new_string("invalid"));
        json_object_object_add(resp, "error", json_object_new_string("invalid_pair_device_id"));
        json_object_object_add(resp, "expires_in", json_object_new_int(0));
        return resp;
    }
    if (!owner_authenticated && (!status_token || !status_token[0])) {
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "state", json_object_new_string("unauthorized"));
        json_object_object_add(resp, "error", json_object_new_string("pair_status_token_required"));
        return resp;
    }
    st = app_prepare(
        "SELECT id,name,platform,paired_at,last_seen,role,enabled,pair_expires_at,"
        "approval_state,status_token_hash,approved_at,approved_by "
        "FROM app_devices WHERE id=?1 LIMIT 1");
    if (!st) {
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "state", json_object_new_string("unknown"));
        json_object_object_add(resp, "error", json_object_new_string("pair_status_query_failed"));
        return resp;
    }
    sqlite3_bind_text(st, 1, pair_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) == SQLITE_ROW) {
        found = 1;
        paired_at = sqlite3_column_int64(st, 3);
        expires_at = sqlite3_column_int64(st, 7);
        enabled = sqlite3_column_int(st, 6);
        snprintf(approval_state, sizeof(approval_state), "%s",
                 sqlite3_column_text(st, 8) ?
                 (const char *)sqlite3_column_text(st, 8) : "pending");
        snprintf(stored_status_hash, sizeof(stored_status_hash), "%s",
                 sqlite3_column_text(st, 9) ?
                 (const char *)sqlite3_column_text(st, 9) : "");
        if (!owner_authenticated &&
            (webd_token_sha256(status_token, supplied_status_hash) != 0 ||
             !stored_status_hash[0] ||
             !ct_str_equal(supplied_status_hash, stored_status_hash))) {
            sqlite3_finalize(st);
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "state", json_object_new_string("unauthorized"));
            json_object_object_add(resp, "error", json_object_new_string("pair_status_token_invalid"));
            return resp;
        }
        if (paired_at > 0)
            state = enabled ? "paired" : "disabled";
        else if (!strcmp(approval_state, "canceled"))
            state = "canceled";
        else if (!strcmp(approval_state, "expired") ||
                 (expires_at > 0 && expires_at < ts))
            state = "expired";
        else if (!strcmp(approval_state, "approved"))
            state = "approved";
        else if (!strcmp(approval_state, "rejected"))
            state = "rejected";
        else if (expires_at > 0 && expires_at >= ts)
            state = "pending_approval";
        else if (expires_at > 0)
            state = "expired";
        device = json_object_new_object();
        webd_obj_add_str(device, "id", (const char *)sqlite3_column_text(st, 0));
        webd_obj_add_str(device, "name", (const char *)sqlite3_column_text(st, 1));
        webd_obj_add_str(device, "platform", (const char *)sqlite3_column_text(st, 2));
        json_object_object_add(device, "paired_at", json_object_new_int64(paired_at));
        json_object_object_add(device, "last_seen", json_object_new_int64(sqlite3_column_int64(st, 4)));
        webd_obj_add_str(device, "role", (const char *)sqlite3_column_text(st, 5));
        json_object_object_add(device, "enabled", json_object_new_boolean(enabled));
        json_object_object_add(device, "expires_at", json_object_new_int64(expires_at));
        webd_obj_add_str(device, "state", state);
        json_object_object_add(device, "approved_at", json_object_new_int64(sqlite3_column_int64(st, 10)));
        if (owner_authenticated)
            webd_obj_add_str(device, "approved_by", (const char *)sqlite3_column_text(st, 11));
        json_object_object_add(resp, "device", device);
    }
    sqlite3_finalize(st);
    if (!found && !owner_authenticated) {
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "state", json_object_new_string("unauthorized"));
        json_object_object_add(resp, "error", json_object_new_string("pair_status_token_invalid"));
        return resp;
    }
    json_object_object_add(resp, "state", json_object_new_string(state));
    json_object_object_add(resp, "expires_at", json_object_new_int64(expires_at));
    json_object_object_add(resp, "expires_in", json_object_new_int64(expires_at > ts ? expires_at - ts : 0));
    return resp;
}

static struct json_object *jmx_app_pair_approve(const char *pair_id,
                                                const char *actor,
                                                int approve,
                                                int *http_status)
{
    sqlite3_stmt *st;
    int64_t ts = now_s();
    const char *state = approve ? "approved" : "rejected";

    if (http_status)
        *http_status = 400;
    if (!app_pair_device_id_ok(pair_id))
        return jmx_app_pair_error("invalid_pair_device_id",
                                  "pair_id is missing or unsafe");
    st = app_prepare(
        "UPDATE app_devices SET approval_state=?1,approved_at=?2,approved_by=?3,"
        "pair_code_hash=CASE WHEN ?4=1 THEN pair_code_hash ELSE '' END "
        "WHERE id=?5 AND paired_at=0 AND enabled=1 AND approval_state='pending' "
        "AND pair_expires_at>=?2");
    if (!st)
        return jmx_app_pair_error("pair_approval_failed",
                                  "pair approval state is unavailable");
    sqlite3_bind_text(st, 1, state, -1, SQLITE_STATIC);
    sqlite3_bind_int64(st, 2, ts);
    sqlite3_bind_text(st, 3, actor ? actor : "", -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 4, approve ? 1 : 0);
    sqlite3_bind_text(st, 5, pair_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_DONE || sqlite3_changes(g_app_db) <= 0) {
        sqlite3_finalize(st);
        if (http_status)
            *http_status = 409;
        return jmx_app_pair_error("pair_not_pending",
                                  "pair request is not pending or has expired");
    }
    sqlite3_finalize(st);
    {
        struct json_object *resp = json_object_new_object();

        json_object_object_add(resp, "ok", json_object_new_boolean(1));
        json_object_object_add(resp, "pair_id", json_object_new_string(pair_id));
        json_object_object_add(resp, "state", json_object_new_string(state));
        json_object_object_add(resp, "approved_at", json_object_new_int64(ts));
        if (http_status)
            *http_status = 200;
        return resp;
    }
}


static int jmx_app_owner_count_except(const char *id)
{
    sqlite3_stmt *st = app_prepare("SELECT COUNT(*) FROM app_devices WHERE role='owner' AND enabled=1 AND paired_at>0 AND id<>?1");
    if (!st) return -1;

    sqlite3_bind_text(st, 1, id ? id : "", -1, SQLITE_TRANSIENT);
    int count = -1;
    if (sqlite3_step(st) == SQLITE_ROW)
        count = sqlite3_column_int(st, 0);
    sqlite3_finalize(st);
    return count;
}

int jmx_app_device_delete(const char *id)
{
    if (!id || !id[0]) return -1;
    sqlite3_stmt *st = app_prepare("DELETE FROM app_devices WHERE id=?1");
    if (!st) return -1;
    sqlite3_bind_text(st, 1, id, -1, SQLITE_TRANSIENT);
    int rc = (sqlite3_step(st) == SQLITE_DONE && sqlite3_changes(g_app_db) > 0) ? 0 : -1;
    sqlite3_finalize(st);
    return rc;
}


int jmx_app_device_set_role(const char *device_id, const char *role)
{
    if (!device_id || !device_id[0] || !role || !role[0]) return -1;
    /* Validate role */
    if (strcmp(role, "owner") && strcmp(role, "admin") &&
        strcmp(role, "operator") && strcmp(role, "viewer") && strcmp(role, "ai-agent"))
        return -2;
    sqlite3_stmt *st = app_prepare("UPDATE app_devices SET role=?1 WHERE id=?2");
    if (!st) return -1;
    sqlite3_bind_text(st, 1, role, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, device_id, -1, SQLITE_TRANSIENT);
    int rc = (sqlite3_step(st) == SQLITE_DONE && sqlite3_changes(g_app_db) > 0) ? 0 : -1;
    sqlite3_finalize(st);
    return rc;
}

static int jmx_app_role_valid(const char *role)
{
    return role && role[0] &&
           (!strcmp(role, "owner") || !strcmp(role, "admin") ||
            !strcmp(role, "operator") || !strcmp(role, "viewer") ||
            !strcmp(role, "ai-agent"));
}

static int jmx_app_device_patch_atomic(const char *device_id,
                                       const char *new_role,
                                       int has_enabled,
                                       int new_enabled,
                                       jmx_role_t actor_role,
                                       const char *actor_identity,
                                       int *role_changed,
                                       int *enabled_changed)
{
    sqlite3_stmt *st = NULL;
    char old_role[32] = "";
    const char *final_role;
    int old_enabled = 0;
    int final_enabled;
    int other_owners;
    int rc = -8;

    if (role_changed)
        *role_changed = 0;
    if (enabled_changed)
        *enabled_changed = 0;
    if (!device_id || !device_id[0] ||
        (new_role && new_role[0] && !jmx_app_role_valid(new_role)))
        return (new_role && new_role[0]) ? -2 : -1;
    if (sqlite3_exec(g_app_db, "BEGIN IMMEDIATE", NULL, NULL, NULL) != SQLITE_OK)
        return -8;

    st = app_prepare("SELECT role,enabled FROM app_devices WHERE id=?1");
    if (!st)
        goto rollback;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_ROW) {
        rc = -1;
        sqlite3_finalize(st);
        st = NULL;
        goto rollback;
    }
    snprintf(old_role, sizeof(old_role), "%s",
             sqlite3_column_text(st, 0) ?
             (const char *)sqlite3_column_text(st, 0) : "operator");
    old_enabled = sqlite3_column_int(st, 1) ? 1 : 0;
    sqlite3_finalize(st);
    st = NULL;

    final_role = (new_role && new_role[0]) ? new_role : old_role;
    final_enabled = has_enabled ? (new_enabled ? 1 : 0) : old_enabled;

    if (strcmp(final_role, old_role) && actor_role != JMX_ROLE_OWNER &&
        (!strcmp(old_role, "owner") || !strcmp(final_role, "owner"))) {
        rc = -3;
        goto rollback;
    }
    if (has_enabled && final_enabled != old_enabled &&
        !strcmp(final_role, "owner") && actor_role != JMX_ROLE_OWNER) {
        rc = -5;
        goto rollback;
    }
    if (!final_enabled && old_enabled && actor_identity &&
        !strcmp(device_id, actor_identity)) {
        rc = -7;
        goto rollback;
    }

    if (old_enabled && !strcmp(old_role, "owner") &&
        (!final_enabled || strcmp(final_role, "owner")) &&
        !webd_identity_is_user(actor_identity)) {
        other_owners = jmx_app_owner_count_except(device_id);
        if (other_owners < 0)
            goto rollback;
        if (other_owners == 0) {
            rc = final_enabled ? -4 : -6;
            goto rollback;
        }
    }

    if (!strcmp(final_role, old_role) && final_enabled == old_enabled) {
        if (sqlite3_exec(g_app_db, "COMMIT", NULL, NULL, NULL) != SQLITE_OK)
            goto rollback;
        return 0;
    }

    st = app_prepare("UPDATE app_devices SET role=?1,enabled=?2 WHERE id=?3");
    if (!st)
        goto rollback;
    sqlite3_bind_text(st, 1, final_role, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 2, final_enabled);
    sqlite3_bind_text(st, 3, device_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_DONE || sqlite3_changes(g_app_db) <= 0) {
        sqlite3_finalize(st);
        st = NULL;
        goto rollback;
    }
    sqlite3_finalize(st);
    st = NULL;

    if (old_enabled && !final_enabled) {
        st = app_prepare(
            "UPDATE auth_tokens SET revoked=1 WHERE device_id=?1 AND revoked=0");
        if (!st)
            goto rollback;
        sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
        if (sqlite3_step(st) != SQLITE_DONE) {
            sqlite3_finalize(st);
            st = NULL;
            goto rollback;
        }
        sqlite3_finalize(st);
        st = NULL;
    }

    if (sqlite3_exec(g_app_db, "COMMIT", NULL, NULL, NULL) != SQLITE_OK)
        goto rollback;
    if (role_changed)
        *role_changed = strcmp(final_role, old_role) != 0;
    if (enabled_changed)
        *enabled_changed = final_enabled != old_enabled;
    return 0;

rollback:
    if (st)
        sqlite3_finalize(st);
    sqlite3_exec(g_app_db, "ROLLBACK", NULL, NULL, NULL);
    return rc;
}

static int jmx_app_device_delete_atomic(const char *device_id,
                                        jmx_role_t actor_role,
                                        const char *actor_identity)
{
    sqlite3_stmt *st = NULL;
    char old_role[32] = "";
    int old_enabled = 0;
    int other_owners;
    int rc = -8;

    if (!device_id || !device_id[0])
        return -1;
    if (sqlite3_exec(g_app_db, "BEGIN IMMEDIATE", NULL, NULL, NULL) != SQLITE_OK)
        return -8;

    st = app_prepare("SELECT role,enabled FROM app_devices WHERE id=?1");
    if (!st)
        goto rollback;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_ROW) {
        rc = -1;
        sqlite3_finalize(st);
        st = NULL;
        goto rollback;
    }
    snprintf(old_role, sizeof(old_role), "%s",
             sqlite3_column_text(st, 0) ?
             (const char *)sqlite3_column_text(st, 0) : "operator");
    old_enabled = sqlite3_column_int(st, 1) ? 1 : 0;
    sqlite3_finalize(st);
    st = NULL;

    if (actor_identity && !strcmp(device_id, actor_identity)) {
        rc = -5;
        goto rollback;
    }
    if (!strcmp(old_role, "owner") && actor_role != JMX_ROLE_OWNER) {
        rc = -3;
        goto rollback;
    }
    if (old_enabled && !strcmp(old_role, "owner") &&
        !webd_identity_is_user(actor_identity)) {
        other_owners = jmx_app_owner_count_except(device_id);
        if (other_owners < 0)
            goto rollback;
        if (other_owners == 0) {
            rc = -4;
            goto rollback;
        }
    }

    st = app_prepare("DELETE FROM app_devices WHERE id=?1");
    if (!st)
        goto rollback;
    sqlite3_bind_text(st, 1, device_id, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(st) != SQLITE_DONE || sqlite3_changes(g_app_db) <= 0) {
        sqlite3_finalize(st);
        st = NULL;
        rc = -1;
        goto rollback;
    }
    sqlite3_finalize(st);
    st = NULL;
    if (sqlite3_exec(g_app_db, "COMMIT", NULL, NULL, NULL) != SQLITE_OK)
        goto rollback;
    return 0;

rollback:
    if (st)
        sqlite3_finalize(st);
    sqlite3_exec(g_app_db, "ROLLBACK", NULL, NULL, NULL);
    return rc;
}

/* ══════════════════════════════════════════════════════════════════════
 * Config Transaction
 * ══════════════════════════════════════════════════════════════════════ */

static struct uloop_timeout g_rollback_timer;
static int g_pending_apply_id = 0;

static int jmx_config_pending_task_id(void)
{
    sqlite3_stmt *st = app_prepare(
        "SELECT id FROM config_apply_tasks WHERE state='pending' ORDER BY id DESC LIMIT 1");
    int task_id = 0;

    if (!st)
        return 0;
    if (sqlite3_step(st) == SQLITE_ROW)
        task_id = sqlite3_column_int(st, 0);
    sqlite3_finalize(st);
    return task_id;
}

static int webd_mkdir_p_simple(const char *path, mode_t mode)
{
    char tmp[256];
    char *p;

    if (!path || !path[0])
        return -1;
    snprintf(tmp, sizeof(tmp), "%s", path);
    for (p = tmp + 1; *p; p++) {
        if (*p == '/') {
            *p = '\0';
            if (mkdir(tmp, mode) != 0 && errno != EEXIST)
                return -1;
            *p = '/';
        }
    }
    if (mkdir(tmp, mode) != 0 && errno != EEXIST)
        return -1;
    return 0;
}

static int webd_copy_file_simple(const char *src, const char *dst, char *err, size_t err_len)
{
    int in = -1, out = -1;
    char buf[8192];
    ssize_t n;
    int rc = -1;

    if (err && err_len)
        err[0] = '\0';
    if (!src || !dst) {
        if (err && err_len) snprintf(err, err_len, "invalid_path");
        return -1;
    }
    in = open(src, O_RDONLY | O_CLOEXEC);
    if (in < 0) {
        if (err && err_len) snprintf(err, err_len, "open_src_failed:%s", strerror(errno));
        goto out;
    }
    out = open(dst, O_WRONLY | O_CREAT | O_TRUNC | O_CLOEXEC, 0600);
    if (out < 0) {
        if (err && err_len) snprintf(err, err_len, "open_dst_failed:%s", strerror(errno));
        goto out;
    }
    while ((n = read(in, buf, sizeof(buf))) > 0) {
        char *p = buf;
        ssize_t left = n;
        while (left > 0) {
            ssize_t w = write(out, p, (size_t)left);
            if (w < 0) {
                if (err && err_len) snprintf(err, err_len, "write_failed:%s", strerror(errno));
                goto out;
            }
            p += w;
            left -= w;
        }
    }
    if (n < 0) {
        if (err && err_len) snprintf(err, err_len, "read_failed:%s", strerror(errno));
        goto out;
    }
    if (fsync(out) != 0) {
        if (err && err_len) snprintf(err, err_len, "fsync_failed:%s", strerror(errno));
        goto out;
    }
    rc = 0;
out:
    if (out >= 0) close(out);
    if (in >= 0) close(in);
    return rc;
}

static int webd_network_config_snapshot(char *path, size_t path_len, char *err, size_t err_len)
{
    int64_t ts = now_s();

    if (path && path_len)
        path[0] = '\0';
    if (err && err_len)
        err[0] = '\0';
    if (access(WEBD_NETWORK_CONFIG_PATH, R_OK) != 0) {
        if (err && err_len) snprintf(err, err_len, "network_config_not_readable:%s", strerror(errno));
        return -1;
    }
    if (webd_mkdir_p_simple(WEBD_NETWORK_BACKUP_DIR, 0700) != 0) {
        if (err && err_len) snprintf(err, err_len, "backup_dir_failed:%s", strerror(errno));
        return -1;
    }
    snprintf(path, path_len, "%s/network.%lld.%ld.bak", WEBD_NETWORK_BACKUP_DIR,
             (long long)ts, random());
    return webd_copy_file_simple(WEBD_NETWORK_CONFIG_PATH, path, err, err_len);
}

static int webd_network_config_restore(const char *snapshot_path, char *err, size_t err_len)
{
    char pre_path[256];
    char copy_err[128] = "";

    if (err && err_len)
        err[0] = '\0';
    if (!snapshot_path || !snapshot_path[0]) {
        if (err && err_len) snprintf(err, err_len, "snapshot_path_missing");
        return -1;
    }
    if (strncmp(snapshot_path, WEBD_NETWORK_BACKUP_DIR "/", strlen(WEBD_NETWORK_BACKUP_DIR) + 1) != 0) {
        if (err && err_len) snprintf(err, err_len, "snapshot_path_outside_backup_dir");
        return -1;
    }
    if (access(snapshot_path, R_OK) != 0) {
        if (err && err_len) snprintf(err, err_len, "snapshot_not_readable:%s", strerror(errno));
        return -1;
    }
    if (webd_mkdir_p_simple(WEBD_NETWORK_BACKUP_DIR, 0700) != 0) {
        if (err && err_len) snprintf(err, err_len, "backup_dir_failed:%s", strerror(errno));
        return -1;
    }
    snprintf(pre_path, sizeof(pre_path), "%s/network.pre-rollback.%lld.%ld.bak",
             WEBD_NETWORK_BACKUP_DIR, (long long)now_s(), random());
    (void)webd_copy_file_simple(WEBD_NETWORK_CONFIG_PATH, pre_path, copy_err, sizeof(copy_err));
    if (webd_copy_file_simple(snapshot_path, WEBD_NETWORK_CONFIG_PATH, err, err_len) != 0)
        return -1;
    sync();
    return 0;
}

static int webd_open_runtime_log(const char *prefix, char *path, size_t path_len)
{
    struct stat st;
    int dirfd = -1;
    int fd = -1;
    int attempt;
    char name[128];

    if (!prefix || !prefix[0] || !path || path_len == 0)
        return -1;
    path[0] = '\0';
    if (mkdir(WEBD_RUNTIME_DIR, 0700) != 0 && errno != EEXIST)
        return -1;
    dirfd = open(WEBD_RUNTIME_DIR,
                 O_RDONLY | O_DIRECTORY | O_CLOEXEC | O_NOFOLLOW);
    if (dirfd < 0 || fstat(dirfd, &st) != 0 || !S_ISDIR(st.st_mode) ||
        st.st_uid != 0 || (st.st_mode & (S_IWGRP | S_IWOTH)) != 0)
        goto out;
    for (attempt = 0; attempt < 32; attempt++) {
        snprintf(name, sizeof(name), "%s-%ld-%lld-%08lx-%d.log",
                 prefix, (long)getpid(), (long long)now_s(),
                 (unsigned long)random(), attempt);
        fd = openat(dirfd, name,
                    O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC,
                    0600);
        if (fd >= 0) {
            if (snprintf(path, path_len, "%s/%s", WEBD_RUNTIME_DIR, name) >=
                (int)path_len) {
                close(fd);
                unlinkat(dirfd, name, 0);
                fd = -1;
            }
            break;
        }
        if (errno != EEXIST)
            break;
    }
out:
    if (dirfd >= 0)
        close(dirfd);
    return fd;
}

static int webd_network_reload_runtime(char *err, size_t err_len)
{
    pid_t pid;
    int status;
    int logfd;
    char log_path[256];
    const char *argv[] = { "/etc/init.d/network", "reload", NULL };

    if (err && err_len)
        err[0] = '\0';
    if (access(argv[0], X_OK) != 0) {
        if (err && err_len) snprintf(err, err_len, "network_init_unavailable");
        return -1;
    }
    logfd = webd_open_runtime_log("port-network-reload", log_path,
                                  sizeof(log_path));
    if (logfd < 0) {
        if (err && err_len)
            snprintf(err, err_len, "runtime_log_create_failed:%s", strerror(errno));
        return -1;
    }
    pid = fork();
    if (pid < 0) {
        close(logfd);
        if (err && err_len) snprintf(err, err_len, "fork_failed:%s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        int devnull = open("/dev/null", O_RDWR);

        if (devnull >= 0) {
            dup2(devnull, STDIN_FILENO);
            if (devnull > STDERR_FILENO)
                close(devnull);
        }
        if (logfd >= 0) {
            dup2(logfd, STDOUT_FILENO);
            dup2(logfd, STDERR_FILENO);
            if (logfd > STDERR_FILENO)
                close(logfd);
        }
        execv(argv[0], (char * const *)argv);
        _exit(127);
    }
    close(logfd);
    while (waitpid(pid, &status, 0) < 0) {
        if (errno == EINTR)
            continue;
        if (err && err_len) snprintf(err, err_len, "wait_failed:%s", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        if (err && err_len)
            snprintf(err, err_len, "network_reload_failed_rc_%d:%s",
                     WIFEXITED(status) ? WEXITSTATUS(status) : -1, log_path);
        return -1;
    }
    return 0;
}

static struct json_object *webd_network_local_reachability_probe(void)
{
    struct json_object *probe = json_object_new_object();
    int loopback_ok = 0;
    int lan_status_ok = 0;
    struct json_object *health = NULL;
    struct json_object *lan = NULL;

    json_object_object_add(probe, "source", json_object_new_string("webd_local_probe"));
    health = app_ubus_invoke_timeout("system_status", NULL, 1000);
    loopback_ok = health && app_ubus_response_ok(health);
    if (health)
        json_object_object_add(probe, "system_status", health);
    else
        json_object_object_add(probe, "system_status_available", json_object_new_boolean(0));

    lan = app_ubus_invoke_object_timeout("network.interface.lan", "status", NULL, 1000);
    if (lan) {
        lan_status_ok = app_nc_json_bool(lan, "up", 0) || app_nc_json_bool(lan, "available", 0) ||
                        app_nc_json_bool(lan, "pending", 0);
        json_object_object_add(probe, "network_interface_lan", lan);
    } else {
        json_object_object_add(probe, "network_interface_lan_available", json_object_new_boolean(0));
    }
    json_object_object_add(probe, "loopback_api_ok", json_object_new_boolean(loopback_ok));
    json_object_object_add(probe, "lan_status_ok", json_object_new_boolean(lan_status_ok));
    json_object_object_add(probe, "limited", json_object_new_boolean(1));
    json_object_object_add(probe, "reason", json_object_new_string(loopback_ok ?
                           "local_control_plane_reachable" : "local_control_plane_probe_failed"));
    return probe;
}

static struct json_object *webd_port_config_payload_from_changes(struct json_object *changes,
                                                                  int previous)
{
    struct json_object *payload = json_object_new_object();
    struct json_object *plan = webd_obj_child_obj(changes, "plan");
    struct json_object *source = previous ? webd_obj_child_obj(plan, "current_port") :
                                            webd_obj_child_obj(changes, "request");
    struct json_object *config = previous ? webd_obj_child_obj(source, "config") : NULL;
    struct json_object *value = NULL;
    const char *ifname = app_nc_json_str(changes, "ifname",
                         app_nc_json_str(plan, "ifname", ""));
    const char *profile_id;
    int native_vlan;

    if (!ifname[0]) {
        json_object_put(payload);
        return NULL;
    }
    json_object_object_add(payload, "ifname", json_object_new_string(ifname));
    if (previous) {
        profile_id = app_nc_json_str(config, "profile_id",
                     app_nc_json_str(source, "profile_id", ""));
        native_vlan = app_nc_json_int(config, "native_vlan",
                      app_nc_json_int(source, "native_vlan", 0));
        json_object_object_add(payload, "profile_id", json_object_new_string(profile_id));
        json_object_object_add(payload, "native_vlan", json_object_new_int(native_vlan));
        if ((!config || !json_object_object_get_ex(config, "tagged_vlans", &value)) &&
            source)
            json_object_object_get_ex(source, "tagged_vlans", &value);
        json_object_object_add(payload, "tagged_vlans",
                               value && json_object_is_type(value, json_type_array) ?
                               json_object_get(value) : json_object_new_array());
        return payload;
    }

    if (!source)
        return payload;
    if (app_nc_json_has(source, "profile_id") || app_nc_json_has(source, "profile"))
        json_object_object_add(payload, "profile_id", json_object_new_string(
            app_nc_json_str(source, "profile_id", app_nc_json_str(source, "profile", ""))));
    if (app_nc_json_has(source, "native_vlan") || app_nc_json_has(source, "vlan_id"))
        json_object_object_add(payload, "native_vlan", json_object_new_int(
            app_nc_json_int(source, "native_vlan", app_nc_json_int(source, "vlan_id", 0))));
    if (json_object_object_get_ex(source, "tagged_vlans", &value) && value &&
        json_object_is_type(value, json_type_array))
        json_object_object_add(payload, "tagged_vlans", json_object_get(value));
    return payload;
}

static int webd_port_config_apply_from_changes(struct json_object *changes, int previous,
                                                struct json_object **upstream_out,
                                                char *err, size_t err_len)
{
    struct json_object *payload;
    struct json_object *upstream;
    int ok;

    if (upstream_out)
        *upstream_out = NULL;
    if (err && err_len)
        err[0] = '\0';
    payload = webd_port_config_payload_from_changes(changes, previous);
    if (!payload) {
        if (err && err_len)
            snprintf(err, err_len, "port_config_payload_missing");
        return -1;
    }
    upstream = app_ubus_invoke_timeout("physical_port_config_apply", payload, 10000);
    json_object_put(payload);
    ok = app_ubus_response_ok(upstream);
    if (!ok && err && err_len)
        snprintf(err, err_len, "%s", upstream ?
                 app_nc_json_str(webd_obj_child_obj(upstream, "data"), "error",
                                 "physical_port_config_apply_failed") :
                 "physical_port_config_apply_unavailable");
    if (upstream_out)
        *upstream_out = upstream;
    else if (upstream)
        json_object_put(upstream);
    return ok ? 0 : -1;
}

static int webd_port_config_restore_task(int task_id, char *err, size_t err_len)
{
    sqlite3_stmt *st;
    struct json_object *changes = NULL;
    const char *raw = NULL;
    int rc = -1;

    if (err && err_len)
        err[0] = '\0';
    st = app_prepare("SELECT changes_json FROM config_apply_tasks WHERE id=?1");
    if (!st) {
        if (err && err_len) snprintf(err, err_len, "config_task_lookup_failed");
        return -1;
    }
    sqlite3_bind_int(st, 1, task_id);
    if (sqlite3_step(st) == SQLITE_ROW)
        raw = (const char *)sqlite3_column_text(st, 0);
    if (raw && raw[0])
        changes = json_tokener_parse(raw);
    sqlite3_finalize(st);
    if (!changes) {
        if (err && err_len) snprintf(err, err_len, "config_task_changes_invalid");
        return -1;
    }
    if (!webd_port_manager_changes_need_vlan_runtime(changes))
        rc = 0;
    else
        rc = webd_port_config_apply_from_changes(changes, 1, NULL, err, err_len);
    json_object_put(changes);
    return rc;
}

static void rollback_timeout_cb(struct uloop_timeout *t)
{
    sqlite3_stmt *st;
    char snapshot[256] = "";
    char err[160] = "";
    char config_err[160] = "";
    int restored = 0;
    int config_restored = 0;
    int task_id = g_pending_apply_id;

    (void)t;
    if (task_id <= 0)
        return;
    fprintf(stderr, "[dreamingwrt-webd] auto-rollback apply task #%d\n", task_id);

    st = app_prepare("SELECT snapshot_path FROM config_apply_tasks WHERE id=?1 AND state='pending'");
    if (st) {
        sqlite3_bind_int(st, 1, task_id);
        if (sqlite3_step(st) == SQLITE_ROW) {
            const char *s = (const char *)sqlite3_column_text(st, 0);
            if (s)
                snprintf(snapshot, sizeof(snapshot), "%s", s);
        }
        sqlite3_finalize(st);
    }
    if (snapshot[0] && webd_network_config_restore(snapshot, err, sizeof(err)) == 0)
        restored = 1;
    else if (!snapshot[0])
        snprintf(err, sizeof(err), "snapshot_path_missing");
    if (restored) {
        char reload_err[160] = "";
        if (webd_network_reload_runtime(reload_err, sizeof(reload_err)) != 0)
            snprintf(err, sizeof(err), "restored_but_reload_failed:%s", reload_err);
    }
    config_restored = webd_port_config_restore_task(task_id, config_err,
                                                     sizeof(config_err)) == 0;
    if (!config_restored && !err[0])
        snprintf(err, sizeof(err), "port_config_restore_failed:%s", config_err);
    restored = restored && config_restored;

    st = app_prepare(
        "UPDATE config_apply_tasks SET state='rolled_back',finished_at=?1,error=?2,"
        "rollback_applied=?3,rollback_error=?4 "
        "WHERE id=?5 AND state='pending'");
    if (st) {
        int64_t ts = now_s();
        sqlite3_bind_int64(st, 1, ts);
        sqlite3_bind_text(st, 2, restored ? "auto_rollback_applied" : "auto_rollback_failed", -1, SQLITE_STATIC);
        sqlite3_bind_int(st, 3, restored);
        sqlite3_bind_text(st, 4, restored ? "" : err, -1, SQLITE_TRANSIENT);
        sqlite3_bind_int(st, 5, task_id);
        sqlite3_step(st);
        sqlite3_finalize(st);
    }
    g_pending_apply_id = 0;
}

struct json_object *jmx_config_apply(struct json_object *req)
{
    const char *scope = app_nc_json_str(req, "scope", "network");
    int rollback_timeout = app_nc_json_int(req, "rollback_timeout", 90);
    int pending_id = jmx_config_pending_task_id();
    int snapshot_requested = app_nc_json_bool(req, "snapshot", 1);
    struct json_object *changes = NULL;
    char snapshot_path[256] = "";
    char snapshot_err[160] = "";
    int snapshot_ok = 0;
    int port_vlan_runtime = 0;
    struct json_object *network_tx = NULL;
    int64_t ts;
    const char *changes_str;
    sqlite3_stmt *st;
    int task_id;
    struct json_object *resp;

    json_object_object_get_ex(req, "changes", &changes);
    port_vlan_runtime = jmx_task_is_port_scope(scope) &&
                        webd_port_manager_changes_need_vlan_runtime(changes) &&
                        !app_nc_json_bool(req, "dry_run", 0);

    if (pending_id > 0) {
        resp = json_object_new_object();
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "error", json_object_new_string("transaction_pending"));
        json_object_object_add(resp, "message", json_object_new_string("A config transaction is already pending"));
        json_object_object_add(resp, "task_id", json_object_new_int(pending_id));
        return resp;
    }
    if (rollback_timeout < 10)
        rollback_timeout = 10;
    if (rollback_timeout > 3600)
        rollback_timeout = 3600;

    if (snapshot_requested && (!strcmp(scope, "network") || strstr(scope, "port") || strstr(scope, "topology"))) {
        if (webd_network_config_snapshot(snapshot_path, sizeof(snapshot_path),
                                         snapshot_err, sizeof(snapshot_err)) == 0)
            snapshot_ok = 1;
    }
    if (port_vlan_runtime && !snapshot_ok) {
        resp = json_object_new_object();
        json_object_object_add(resp, "ok", json_object_new_boolean(0));
        json_object_object_add(resp, "error", json_object_new_string("network_snapshot_required"));
        json_object_object_add(resp, "snapshot_ok", json_object_new_boolean(0));
        json_object_object_add(resp, "snapshot_error", json_object_new_string(snapshot_err));
        json_object_object_add(resp, "applied", json_object_new_boolean(0));
        json_object_object_add(resp, "capability", json_object_new_string("dsa_bridge_vlan_runtime_apply"));
        return resp;
    }
    ts = now_s();
    changes_str = changes ? json_object_to_json_string(changes) : "{}";

    st = app_prepare(
        "INSERT INTO config_apply_tasks(scope,changes_json,state,rollback_timeout,started_at,"
        "snapshot_path,snapshot_at,snapshot_ok,apply_executor,error) "
        "VALUES(?1,?2,'pending',?3,?4,?5,?6,?7,?8,?9)");
    if (!st)
        return NULL;
    sqlite3_bind_text(st, 1, scope, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 2, changes_str, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 3, rollback_timeout);
    sqlite3_bind_int64(st, 4, ts);
    sqlite3_bind_text(st, 5, snapshot_path, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 6, snapshot_ok ? ts : 0);
    sqlite3_bind_int(st, 7, snapshot_ok);
    sqlite3_bind_text(st, 8, port_vlan_runtime ?
                      "dsa_bridge_vlan_uci_reload_guarded" :
                      "snapshot_only_no_network_mutation", -1, SQLITE_STATIC);
    sqlite3_bind_text(st, 9, snapshot_ok ? "" : snapshot_err, -1, SQLITE_TRANSIENT);
    if (app_step_done(st) != 0) {
        sqlite3_finalize(st);
        return NULL;
    }
    task_id = (int)sqlite3_last_insert_rowid(g_app_db);
    sqlite3_finalize(st);

    if (port_vlan_runtime) {
        const char *tx_error;
        char restore_err[160] = "";
        char config_err[160] = "";
        struct json_object *config_upstream = NULL;
        int restored = 0;

        network_tx = webd_port_manager_apply_network_transaction(changes, snapshot_path, 0);
        if (network_tx && app_nc_json_bool(network_tx, "ok", 0) &&
            webd_port_config_apply_from_changes(changes, 0, &config_upstream,
                                                config_err, sizeof(config_err)) != 0) {
            json_object_object_add(network_tx, "port_config_persisted", json_object_new_boolean(0));
            json_object_object_add(network_tx, "port_config_error",
                                   json_object_new_string(config_err));
        }
        if (!network_tx || !app_nc_json_bool(network_tx, "ok", 0) || config_err[0]) {
            tx_error = network_tx ?
                (config_err[0] ? config_err :
                 app_nc_json_str(network_tx, "error", "port_network_transaction_failed")) :
                "port_network_transaction_failed";
            if (snapshot_ok &&
                webd_network_config_restore(snapshot_path, restore_err, sizeof(restore_err)) == 0) {
                char reload_err[160] = "";

                restored = 1;
                if (webd_network_reload_runtime(reload_err, sizeof(reload_err)) != 0) {
                    restored = 0;
                    snprintf(restore_err, sizeof(restore_err),
                             "restored_but_reload_failed:%s", reload_err);
                }
            }
            if (config_err[0]) {
                char old_config_err[160] = "";
                int old_config_ok = webd_port_config_apply_from_changes(
                    changes, 1, NULL, old_config_err, sizeof(old_config_err)) == 0;

                restored = restored && old_config_ok;
                if (!old_config_ok)
                    snprintf(restore_err, sizeof(restore_err),
                             "port_config_restore_failed:%s", old_config_err);
            }
            st = app_prepare(
                "UPDATE config_apply_tasks SET state='failed',finished_at=?1,error=?2,"
                "rollback_applied=?3,rollback_error=?4 WHERE id=?5 AND state='pending'");
            if (st) {
                sqlite3_bind_int64(st, 1, now_s());
                sqlite3_bind_text(st, 2, tx_error, -1, SQLITE_TRANSIENT);
                sqlite3_bind_int(st, 3, restored);
                sqlite3_bind_text(st, 4, restored ? "" : restore_err, -1, SQLITE_TRANSIENT);
                sqlite3_bind_int(st, 5, task_id);
                sqlite3_step(st);
                sqlite3_finalize(st);
            }
            resp = json_object_new_object();
            json_object_object_add(resp, "ok", json_object_new_boolean(0));
            json_object_object_add(resp, "error", json_object_new_string(tx_error));
            json_object_object_add(resp, "task_id", json_object_new_int(task_id));
            json_object_object_add(resp, "state", json_object_new_string("failed"));
            json_object_object_add(resp, "snapshot_ok", json_object_new_boolean(snapshot_ok));
            json_object_object_add(resp, "snapshot_path", json_object_new_string(snapshot_path));
            json_object_object_add(resp, "applied", json_object_new_boolean(0));
            json_object_object_add(resp, "rollback_applied", json_object_new_boolean(restored));
            if (!restored && restore_err[0])
                json_object_object_add(resp, "rollback_error", json_object_new_string(restore_err));
            json_object_object_add(resp, "network_transaction",
                                   network_tx ? network_tx : json_object_new_object());
            if (config_upstream)
                json_object_object_add(resp, "port_config_upstream", config_upstream);
            return resp;
        }
        json_object_object_add(network_tx, "port_config_persisted", json_object_new_boolean(1));
        if (config_upstream)
            json_object_object_add(network_tx, "port_config_upstream", config_upstream);
    }

    g_pending_apply_id = task_id;
    g_rollback_timer.cb = rollback_timeout_cb;
    uloop_timeout_set(&g_rollback_timer, rollback_timeout * 1000);

    resp = json_object_new_object();
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    json_object_object_add(resp, "task_id", json_object_new_int(task_id));
    json_object_object_add(resp, "state", json_object_new_string("pending"));
    json_object_object_add(resp, "scope", json_object_new_string(scope));
    json_object_object_add(resp, "rollback_timeout", json_object_new_int(rollback_timeout));
    json_object_object_add(resp, "confirm_before", json_object_new_int64(ts + rollback_timeout));
    json_object_object_add(resp, "require_confirm", json_object_new_boolean(1));
    json_object_object_add(resp, "requires_confirm", json_object_new_boolean(1));
    json_object_object_add(resp, "applied", json_object_new_boolean(port_vlan_runtime));
    json_object_object_add(resp, "snapshot_ok", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "snapshot_path", json_object_new_string(snapshot_path));
    json_object_object_add(resp, "rollback_available", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "rollback_executor", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "manual_rollback_supported", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "automatic_rollback", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "auto_rollback_worker", json_object_new_boolean(snapshot_ok));
    json_object_object_add(resp, "auto_rollback_worker_owner", json_object_new_string("dreamingwrt-init"));
    json_object_object_add(resp, "auto_rollback_scope", json_object_new_string("/etc/config/network snapshot restore only"));
    json_object_object_add(resp, "reachability_probe", webd_network_local_reachability_probe());
    json_object_object_add(resp, "transaction_only", json_object_new_boolean(!port_vlan_runtime));
    json_object_object_add(resp, "apply_executor", json_object_new_string(port_vlan_runtime ?
                           "dsa_bridge_vlan_uci_reload_guarded" :
                           "snapshot_only_no_network_mutation"));
    if (network_tx)
        json_object_object_add(resp, "network_transaction", network_tx);
    json_object_object_add(resp, "warning", json_object_new_string(port_vlan_runtime ?
                           "live_vlan_runtime_apply_pending_confirm_or_auto_rollback" :
                           (snapshot_ok ? "config_apply_executor_missing_snapshot_created" :
                            "config_apply_executor_missing_snapshot_failed")));
    if (!snapshot_ok && snapshot_err[0])
        json_object_object_add(resp, "snapshot_error", json_object_new_string(snapshot_err));
    return resp;
}

struct json_object *jmx_config_confirm(struct json_object *req)
{
    int task_id = app_nc_json_int(req, "task_id", 0);
    int64_t ts;
    sqlite3_stmt *st;
    int ok;
    struct json_object *resp;

    if (task_id <= 0) return NULL;

    ts = now_s();
    st = app_prepare(
        "UPDATE config_apply_tasks SET state='confirmed',confirmed_at=?1,finished_at=?1 "
        "WHERE id=?2 AND state='pending'");
    if (!st) return NULL;
    sqlite3_bind_int64(st, 1, ts);
    sqlite3_bind_int(st, 2, task_id);
    ok = (app_step_done(st) == 0 && sqlite3_changes(g_app_db) > 0);
    sqlite3_finalize(st);

    if (ok && g_pending_apply_id == task_id) {
        uloop_timeout_cancel(&g_rollback_timer);
        g_pending_apply_id = 0;
    }

    resp = json_object_new_object();
    json_object_object_add(resp, "ok", json_object_new_boolean(ok));
    json_object_object_add(resp, "task_id", json_object_new_int(task_id));
    json_object_object_add(resp, "state", json_object_new_string(ok ? "confirmed" : "unchanged"));
    json_object_object_add(resp, "applied", json_object_new_boolean(0));
    json_object_object_add(resp, "transaction_only", json_object_new_boolean(1));
    if (!ok) json_object_object_add(resp, "error", json_object_new_string("task_not_pending"));
    return resp;
}

struct json_object *jmx_config_rollback(struct json_object *req)
{
    int task_id = app_nc_json_int(req, "task_id", 0);
    char snapshot[256] = "";
    char err[160] = "";
    char config_err[160] = "";
    int restored = 0;
    int config_restored = 0;
    int row_found = 0;
    sqlite3_stmt *st;
    struct json_object *resp;

    if (task_id <= 0) return NULL;

    st = app_prepare("SELECT snapshot_path FROM config_apply_tasks WHERE id=?1 AND state='pending'");
    if (!st) return NULL;
    sqlite3_bind_int(st, 1, task_id);
    if (sqlite3_step(st) == SQLITE_ROW) {
        const char *s = (const char *)sqlite3_column_text(st, 0);
        row_found = 1;
        if (s)
            snprintf(snapshot, sizeof(snapshot), "%s", s);
    }
    sqlite3_finalize(st);

    if (row_found && snapshot[0])
        restored = (webd_network_config_restore(snapshot, err, sizeof(err)) == 0);
    else if (row_found)
        snprintf(err, sizeof(err), "snapshot_path_missing");
    else
        snprintf(err, sizeof(err), "task_not_pending");
    if (restored) {
        char reload_err[160] = "";
        if (webd_network_reload_runtime(reload_err, sizeof(reload_err)) != 0)
            snprintf(err, sizeof(err), "restored_but_reload_failed:%s", reload_err);
    }
    if (row_found)
        config_restored = webd_port_config_restore_task(task_id, config_err,
                                                        sizeof(config_err)) == 0;
    if (row_found && !config_restored && !err[0])
        snprintf(err, sizeof(err), "port_config_restore_failed:%s", config_err);
    restored = restored && config_restored;

    if (row_found) {
        int64_t ts = now_s();
        if (restored)
            st = app_prepare(
                "UPDATE config_apply_tasks SET state='rolled_back',finished_at=?1,error='',"
                "rollback_applied=1,rollback_error='' WHERE id=?2 AND state='pending'");
        else
            st = app_prepare(
                "UPDATE config_apply_tasks SET error='manual_rollback_failed',rollback_applied=0,"
                "rollback_error=?1 WHERE id=?2 AND state='pending'");
        if (st) {
            if (restored) {
                sqlite3_bind_int64(st, 1, ts);
                sqlite3_bind_int(st, 2, task_id);
            } else {
                sqlite3_bind_text(st, 1, err, -1, SQLITE_TRANSIENT);
                sqlite3_bind_int(st, 2, task_id);
            }
            sqlite3_step(st);
            sqlite3_finalize(st);
        }
    }

    if (restored && g_pending_apply_id == task_id) {
        uloop_timeout_cancel(&g_rollback_timer);
        g_pending_apply_id = 0;
    }

    resp = json_object_new_object();
    json_object_object_add(resp, "ok", json_object_new_boolean(restored));
    json_object_object_add(resp, "task_id", json_object_new_int(task_id));
    json_object_object_add(resp, "state", json_object_new_string(restored ? "rolled_back" : "unchanged"));
    json_object_object_add(resp, "snapshot_path", json_object_new_string(snapshot));
    json_object_object_add(resp, "rollback_applied", json_object_new_boolean(restored));
    json_object_object_add(resp, "rollback_executor", json_object_new_boolean(row_found && snapshot[0]));
    json_object_object_add(resp, "transaction_only", json_object_new_boolean(1));
    if (!restored)
        json_object_object_add(resp, "error", json_object_new_string(err[0] ? err : "rollback_failed"));
    return resp;
}

struct json_object *jmx_config_snapshot(struct json_object *req)
{
    return app_ubus_or_error("config_snapshot", req);
}

struct json_object *jmx_config_validate(struct json_object *req)
{
    struct json_object *resp = json_object_new_object();
    struct json_object *errors = json_object_new_array();
    struct json_object *changes = NULL;
    json_object_object_get_ex(req, "changes", &changes);
    int valid = 1;

    if (changes) {
        /* Validate WAN changes */
        struct json_object *wan_arr = NULL;
        if (json_object_object_get_ex(changes, "wan", &wan_arr) && json_object_is_type(wan_arr, json_type_array)) {
            int i, n = (int)json_object_array_length(wan_arr);
            for (i = 0; i < n; i++) {
                struct json_object *w = json_object_array_get_idx(wan_arr, i);
                const char *id = app_nc_json_str(w, "id", "");
                const char *device = app_nc_json_str(w, "device", "");
                if (!id[0]) {
                    struct json_object *e = json_object_new_object();
                    json_object_object_add(e, "field", json_object_new_string("wan.id"));
                    json_object_object_add(e, "reason", json_object_new_string("missing"));
                    json_object_object_add(e, "message", json_object_new_string("WAN id is required"));
                    json_object_array_add(errors, e);
                    valid = 0;
                }
                if (!device[0]) {
                    struct json_object *e = json_object_new_object();
                    json_object_object_add(e, "field", json_object_new_string("wan.device"));
                    json_object_object_add(e, "reason", json_object_new_string("missing"));
                    json_object_object_add(e, "message", json_object_new_string("WAN device is required"));
                    json_object_array_add(errors, e);
                    valid = 0;
                }
            }
        }

        /* Validate LAN changes */
        struct json_object *lan_arr = NULL;
        if (json_object_object_get_ex(changes, "lan", &lan_arr) && json_object_is_type(lan_arr, json_type_array)) {
            int i, n = (int)json_object_array_length(lan_arr);
            for (i = 0; i < n; i++) {
                struct json_object *l = json_object_array_get_idx(lan_arr, i);
                const char *id = app_nc_json_str(l, "id", "");
                if (!id[0]) {
                    struct json_object *e = json_object_new_object();
                    json_object_object_add(e, "field", json_object_new_string("lan.id"));
                    json_object_object_add(e, "reason", json_object_new_string("missing"));
                    json_object_object_add(e, "message", json_object_new_string("LAN id is required"));
                    json_object_array_add(errors, e);
                    valid = 0;
                }
            }
        }
    }

    json_object_object_add(resp, "valid", json_object_new_boolean(valid));
    json_object_object_add(resp, "errors", errors);
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    return resp;
}

struct json_object *jmx_config_last_apply(void)
{
    struct json_object *resp = json_object_new_object();
    sqlite3_stmt *st = app_prepare(
        "SELECT id,scope,state,rollback_timeout,started_at,confirmed_at,finished_at,error,"
        "snapshot_path,snapshot_at,snapshot_ok,rollback_applied,rollback_error,apply_executor "
        "FROM config_apply_tasks ORDER BY id DESC LIMIT 1");
    if (st && sqlite3_step(st) == SQLITE_ROW) {
        json_object_object_add(resp, "task_id", json_object_new_int(sqlite3_column_int(st, 0)));
        json_object_object_add(resp, "scope", json_object_new_string((const char *)sqlite3_column_text(st, 1)));
        json_object_object_add(resp, "state", json_object_new_string((const char *)sqlite3_column_text(st, 2)));
        json_object_object_add(resp, "rollback_timeout", json_object_new_int(sqlite3_column_int(st, 3)));
        json_object_object_add(resp, "started_at", json_object_new_int64(sqlite3_column_int64(st, 4)));
        json_object_object_add(resp, "confirmed_at", json_object_new_int64(sqlite3_column_int64(st, 5)));
        json_object_object_add(resp, "finished_at", json_object_new_int64(sqlite3_column_int64(st, 6)));
        json_object_object_add(resp, "error", json_object_new_string((const char *)sqlite3_column_text(st, 7)));
        json_object_object_add(resp, "snapshot_path", json_object_new_string((const char *)sqlite3_column_text(st, 8)));
        json_object_object_add(resp, "snapshot_at", json_object_new_int64(sqlite3_column_int64(st, 9)));
        json_object_object_add(resp, "snapshot_ok", json_object_new_boolean(sqlite3_column_int(st, 10)));
        json_object_object_add(resp, "rollback_available", json_object_new_boolean(sqlite3_column_int(st, 10)));
        json_object_object_add(resp, "rollback_applied", json_object_new_boolean(sqlite3_column_int(st, 11)));
        json_object_object_add(resp, "rollback_error", json_object_new_string((const char *)sqlite3_column_text(st, 12)));
        json_object_object_add(resp, "apply_executor", json_object_new_string((const char *)sqlite3_column_text(st, 13)));
    }
    if (st) sqlite3_finalize(st);
    json_object_object_add(resp, "ok", json_object_new_boolean(1));
    return resp;
}

