static int64_t webd_insights_ts_normalize(int64_t ts)
{
    if (ts > 100000000000LL)
        return ts / 1000;
    return ts;
}

static int webd_insights_period_seconds(const char *period)
{
    if (!period || !period[0] || !strcasecmp(period, "day") || !strcasecmp(period, "DAY"))
        return 86400;
    if (!strcasecmp(period, "hour") || !strcasecmp(period, "HOUR"))
        return 3600;
    if (!strcasecmp(period, "week") || !strcasecmp(period, "WEEK"))
        return 7 * 86400;
    if (!strcasecmp(period, "month") || !strcasecmp(period, "MONTH"))
        return 30 * 86400;
    return 86400;
}


static int webd_insights_truthy(const char *s, int def)
{
    if (!s || !s[0])
        return def;
    return !strcmp(s, "1") || !strcasecmp(s, "true") ||
           !strcasecmp(s, "yes") || !strcasecmp(s, "on");
}

static int webd_insights_dataset_is_security(const char *s)
{
    if (!s || !s[0])
        return 0;
    return !strcasecmp(s, "aegis_events") ||
           !strcasecmp(s, "aegis") ||
           !strcasecmp(s, "security") ||
           !strcasecmp(s, "cybersecure") ||
           !strcasecmp(s, "policy_events");
}

static int webd_insights_mode_is_event_lifecycle(const char *s)
{
    return s && s[0] &&
           (!strcasecmp(s, "event_lifecycle") ||
            !strcasecmp(s, "ctnetlink") ||
            !strcasecmp(s, "conntrack_event") ||
            !strcasecmp(s, "exact_lifecycle"));
}

static void webd_insights_event_lifecycle_status_init(
    struct webd_insights_event_lifecycle_status *st)
{
    struct json_object *status = NULL;
    struct json_object *fc = NULL;

    if (!st)
        return;
    memset(st, 0, sizeof(*st));
    snprintf(st->reason, sizeof(st->reason), "%s", "audit_status_unavailable");
    status = webd_insights_ubus_data_timeout("audit_status", NULL, 1200);
    fc = webd_obj_child_obj(status, "flow_event_collector");
    if (fc) {
        const char *state = app_nc_json_str(fc, "state", "");
        const char *strategy = app_nc_json_str(fc, "storage_strategy", "");

        snprintf(st->state, sizeof(st->state), "%s", state);
        snprintf(st->storage_strategy, sizeof(st->storage_strategy), "%s", strategy);
        st->db_ready = app_nc_json_bool(fc, "db_ready", 0);
        st->running = !strcasecmp(state, "running");
        st->started_at = app_nc_json_int64(fc, "started_at", 0);
        st->updated_at = app_nc_json_int64(fc, "updated_at", 0);
        st->last_event_at = app_nc_json_int64(fc, "last_event_at", 0);
        st->completed_rows = app_nc_json_int64(fc, "completed_lifecycle_rows", 0);
        st->db_writes = app_nc_json_int64(fc, "db_writes", 0);
        st->db_write_errors = app_nc_json_int64(fc, "db_write_errors", 0);
        st->supported = 1;
        st->enabled = st->running && st->db_ready &&
                      !strcasecmp(strategy, "compressed_destroy_lifecycle_only");
        snprintf(st->reason, sizeof(st->reason), "%s",
                 st->enabled ? "ctnetlink_destroy_persisted" :
                 (state && state[0] ? state : "flow_event_collector_not_running"));
    }
    if (status)
        json_object_put(status);
}

static void webd_insights_add_event_lifecycle_status(
    struct json_object *obj,
    const struct webd_insights_event_lifecycle_status *st)
{
    if (!obj || !st)
        return;
    json_object_object_add(obj, "event_lifecycle_available", json_object_new_boolean(st->enabled));
    json_object_object_add(obj, "event_lifecycle_supported", json_object_new_boolean(st->supported));
    json_object_object_add(obj, "event_lifecycle_enabled", json_object_new_boolean(st->enabled));
    json_object_object_add(obj, "event_lifecycle_db_ready", json_object_new_boolean(st->db_ready));
    json_object_object_add(obj, "event_lifecycle_collector_started_at", json_object_new_int64(st->started_at));
    json_object_object_add(obj, "event_lifecycle_observed_since", json_object_new_int64(st->started_at));
    json_object_object_add(obj, "event_lifecycle_collector_updated_at", json_object_new_int64(st->updated_at));
    json_object_object_add(obj, "event_lifecycle_last_event_at", json_object_new_int64(st->last_event_at));
    json_object_object_add(obj, "event_lifecycle_full_capture_since_boot", json_object_new_boolean(0));
    json_object_object_add(obj, "event_lifecycle_collector_window_partial", json_object_new_boolean(st->enabled));
    json_object_object_add(obj, "event_lifecycle_preexisting_flow_gap_possible", json_object_new_boolean(st->enabled));
    webd_obj_add_str(obj, "event_lifecycle_scope", st->enabled ?
                     "collector_observed_completed_destroy_flows" : "unavailable");
    webd_obj_add_str(obj, "event_lifecycle_capture_scope", st->enabled ?
                     "collector_started_at_to_now_only" : "unavailable");
    json_object_object_add(obj, "event_lifecycle_rows", json_object_new_int64(st->completed_rows));
    json_object_object_add(obj, "event_lifecycle_db_writes", json_object_new_int64(st->db_writes));
    json_object_object_add(obj, "event_lifecycle_db_write_errors", json_object_new_int64(st->db_write_errors));
    webd_obj_add_str(obj, "event_lifecycle_state", st->state);
    webd_obj_add_str(obj, "event_lifecycle_reason", st->reason);
    webd_obj_add_str(obj, "event_lifecycle_storage_strategy", st->storage_strategy);
}

static void webd_insights_risk_ctx_init(struct webd_insights_risk_ctx *ctx)
{
    sqlite3_stmt *st = NULL;
    int rc;

    if (!ctx)
        return;
    memset(ctx, 0, sizeof(*ctx));
    ctx->db_present = access(WEBD_AEGIS_DB_PATH, R_OK) == 0;
    if (!ctx->db_present) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_db_missing");
        return;
    }
    rc = sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &ctx->db, SQLITE_OPEN_READONLY, NULL);
    if (rc != SQLITE_OK || !ctx->db) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_db_open_failed:%s",
                 ctx->db ? sqlite3_errmsg(ctx->db) : "sqlite");
        if (ctx->db) {
            sqlite3_close(ctx->db);
            ctx->db = NULL;
        }
        return;
    }
    ctx->db_open = 1;
    sqlite3_busy_timeout(ctx->db, 50);
    if (sqlite3_prepare_v2(ctx->db,
            "SELECT COUNT(*) FROM aegis_reputation_items", -1, &st, NULL) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW)
        ctx->rep_count = sqlite3_column_int(st, 0);
    if (st)
        sqlite3_finalize(st);
    st = NULL;
    if (sqlite3_prepare_v2(ctx->db,
            "SELECT COUNT(*) FROM aegis_domain_categories", -1, &st, NULL) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW)
        ctx->category_count = sqlite3_column_int(st, 0);
    if (st)
        sqlite3_finalize(st);
    if (ctx->rep_count <= 0 && ctx->category_count <= 0)
        snprintf(ctx->error, sizeof(ctx->error), "aegis_db_empty");
}

static void webd_insights_risk_ctx_close(struct webd_insights_risk_ctx *ctx)
{
    if (!ctx)
        return;
    if (ctx->db) {
        sqlite3_close(ctx->db);
        ctx->db = NULL;
    }
    ctx->db_open = 0;
}

static int webd_insights_risk_available(const struct webd_insights_risk_ctx *ctx)
{
    return ctx && ctx->db_open && (ctx->rep_count > 0 || ctx->category_count > 0);
}

static int webd_insights_aegis_count_cached(const char *table)
{
    static time_t cache_ts = 0;
    static int rep_count = -1;
    static int cat_count = -1;
    time_t now = time(NULL);
    struct webd_insights_risk_ctx ctx;

    if (!table || !table[0])
        return 0;
    if (cache_ts == 0 || now - cache_ts > 30 || rep_count < 0 || cat_count < 0) {
        webd_insights_risk_ctx_init(&ctx);
        if (rep_count != ctx.rep_count || cat_count != ctx.category_count)
            webd_insights_risk_cache_clear();
        rep_count = ctx.rep_count;
        cat_count = ctx.category_count;
        cache_ts = now;
        webd_insights_risk_ctx_close(&ctx);
    }
    if (!strcmp(table, "aegis_reputation_items"))
        return rep_count > 0 ? rep_count : 0;
    if (!strcmp(table, "aegis_domain_categories"))
        return cat_count > 0 ? cat_count : 0;
    return 0;
}

static int webd_insights_sqlite_table_exists(sqlite3 *db, const char *table)
{
    sqlite3_stmt *st = NULL;
    int exists = 0;

    if (!db || !table || !table[0])
        return 0;
    if (sqlite3_prepare_v2(db,
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?1 LIMIT 1",
            -1, &st, NULL) != SQLITE_OK)
        return 0;
    sqlite3_bind_text(st, 1, table, -1, SQLITE_TRANSIENT);
    exists = sqlite3_step(st) == SQLITE_ROW;
    sqlite3_finalize(st);
    return exists;
}

static int webd_insights_aegis_events_count_cached(int *schema_present)
{
    static time_t cache_ts = 0;
    static int cached_count = -1;
    static int cached_schema = 0;
    time_t now = time(NULL);
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;

    if (cache_ts == 0 || now - cache_ts > 15 || cached_count < 0) {
        cached_count = 0;
        cached_schema = 0;
        cache_ts = now;
        if (access(WEBD_AEGIS_DB_PATH, R_OK) == 0 &&
            sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &db, SQLITE_OPEN_READONLY, NULL) == SQLITE_OK &&
            db) {
            sqlite3_busy_timeout(db, 50);
            cached_schema = webd_insights_sqlite_table_exists(db, "aegis_events");
            if (cached_schema &&
                sqlite3_prepare_v2(db, "SELECT COUNT(*) FROM aegis_events",
                                   -1, &st, NULL) == SQLITE_OK &&
                sqlite3_step(st) == SQLITE_ROW)
                cached_count = sqlite3_column_int(st, 0);
        }
        if (st)
            sqlite3_finalize(st);
        if (db)
            sqlite3_close(db);
    }
    if (schema_present)
        *schema_present = cached_schema;
    return cached_count > 0 ? cached_count : 0;
}

static int webd_insights_aegis_policy_type_counts_cached(char *scope, size_t scope_len,
                                                         struct json_object **breakdown_out,
                                                         int *dns_filter_out,
                                                         int *reputation_ip_out,
                                                         int *ids_ips_out,
                                                         int *policy_route_out,
                                                         int *other_out)
{
    static time_t cache_ts = 0;
    static int cached_schema = 0;
    static int cached_total = 0;
    static int cached_dns = 0;
    static int cached_rep = 0;
    static int cached_ids = 0;
    static int cached_route = 0;
    static int cached_other = 0;
    time_t now = time(NULL);
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;

    if (cache_ts == 0 || now - cache_ts > 15) {
        cached_schema = 0;
        cached_total = 0;
        cached_dns = 0;
        cached_rep = 0;
        cached_ids = 0;
        cached_route = 0;
        cached_other = 0;
        cache_ts = now;
        if (access(WEBD_AEGIS_DB_PATH, R_OK) == 0 &&
            sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &db, SQLITE_OPEN_READONLY, NULL) == SQLITE_OK && db) {
            sqlite3_busy_timeout(db, 50);
            cached_schema = webd_insights_sqlite_table_exists(db, "aegis_events");
            if (cached_schema &&
                sqlite3_prepare_v2(db,
                    "SELECT lower(coalesce(policy_type,'')),COUNT(*) FROM aegis_events GROUP BY lower(coalesce(policy_type,''))",
                    -1, &st, NULL) == SQLITE_OK) {
                while (sqlite3_step(st) == SQLITE_ROW) {
                    const char *type = (const char *)sqlite3_column_text(st, 0);
                    int n = sqlite3_column_int(st, 1);

                    cached_total += n;
                    if (!type || !type[0])
                        cached_other += n;
                    else if (!strcmp(type, "dns_filter"))
                        cached_dns += n;
                    else if (!strcmp(type, "reputation_ip") || strstr(type, "reputation"))
                        cached_rep += n;
                    else if (!strcmp(type, "ids_ips") || strstr(type, "suricata"))
                        cached_ids += n;
                    else if (!strcmp(type, "policy_route") || strstr(type, "route"))
                        cached_route += n;
                    else
                        cached_other += n;
                }
            }
        }
        if (st)
            sqlite3_finalize(st);
        if (db)
            sqlite3_close(db);
    }
    if (dns_filter_out)
        *dns_filter_out = cached_dns;
    if (reputation_ip_out)
        *reputation_ip_out = cached_rep;
    if (ids_ips_out)
        *ids_ips_out = cached_ids;
    if (policy_route_out)
        *policy_route_out = cached_route;
    if (other_out)
        *other_out = cached_other;
    if (scope && scope_len > 0) {
        int kinds = (cached_dns > 0) + (cached_rep > 0) + (cached_ids > 0) +
                    (cached_route > 0) + (cached_other > 0);
        const char *value = "unavailable";

        if (!cached_schema || cached_total <= 0)
            value = "unavailable";
        else if (kinds > 1)
            value = "mixed_aegis_events";
        else if (cached_dns > 0)
            value = "dns_filter";
        else if (cached_rep > 0)
            value = "reputation_ip";
        else if (cached_ids > 0)
            value = "ids_ips";
        else if (cached_route > 0)
            value = "policy_route";
        else
            value = "aegis_events";
        snprintf(scope, scope_len, "%s", value);
    }
    if (breakdown_out) {
        struct json_object *o = json_object_new_object();

        json_object_object_add(o, "dns_filter", json_object_new_int(cached_dns));
        json_object_object_add(o, "reputation_ip", json_object_new_int(cached_rep));
        json_object_object_add(o, "ids_ips", json_object_new_int(cached_ids));
        json_object_object_add(o, "policy_route", json_object_new_int(cached_route));
        json_object_object_add(o, "other", json_object_new_int(cached_other));
        json_object_object_add(o, "total", json_object_new_int(cached_total));
        json_object_object_add(o, "schema_supported", json_object_new_boolean(cached_schema));
        *breakdown_out = o;
    }
    return cached_total;
}


static const char *webd_sql_text(sqlite3_stmt *st, int col)
{
    const unsigned char *s = sqlite3_column_text(st, col);

    return s ? (const char *)s : "";
}

static void webd_insights_policy_hit_clear(struct webd_insights_policy_hit *hit,
                                           const struct webd_insights_policy_ctx *ctx,
                                           const char *reason)
{
    if (!hit)
        return;
    memset(hit, 0, sizeof(*hit));
    hit->supported = ctx && ctx->schema_supported;
    snprintf(hit->action, sizeof(hit->action), "%s", "");
    snprintf(hit->precision, sizeof(hit->precision), "%s",
             reason && reason[0] ? reason : "none");
    snprintf(hit->source, sizeof(hit->source), "%s",
             ctx && ctx->error[0] ? ctx->error : "");
}

static void webd_insights_policy_ctx_init(struct webd_insights_policy_ctx *ctx)
{
    sqlite3_stmt *st = NULL;

    if (!ctx)
        return;
    memset(ctx, 0, sizeof(*ctx));
    ctx->db_present = access(WEBD_AEGIS_DB_PATH, R_OK) == 0;
    if (!ctx->db_present) {
        snprintf(ctx->error, sizeof(ctx->error), "%s", "aegis_db_missing");
        return;
    }
    if (sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &ctx->db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK || !ctx->db) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_db_open_failed:%s",
                 ctx->db ? sqlite3_errmsg(ctx->db) : "sqlite");
        if (ctx->db) {
            sqlite3_close(ctx->db);
            ctx->db = NULL;
        }
        return;
    }
    ctx->db_open = 1;
    sqlite3_busy_timeout(ctx->db, 50);
    ctx->schema_supported = webd_insights_sqlite_table_exists(ctx->db, "aegis_events");
    if (!ctx->schema_supported) {
        snprintf(ctx->error, sizeof(ctx->error), "%s", "aegis_events_table_missing");
        return;
    }
    if (sqlite3_prepare_v2(ctx->db, "SELECT COUNT(*) FROM aegis_events", -1, &st, NULL) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW)
        ctx->event_count = sqlite3_column_int(st, 0);
    if (st)
        sqlite3_finalize(st);
    if (ctx->event_count <= 0)
        snprintf(ctx->error, sizeof(ctx->error), "%s", "no_aegis_events");
}

static void webd_insights_policy_ctx_close(struct webd_insights_policy_ctx *ctx)
{
    if (!ctx)
        return;
    if (ctx->db) {
        sqlite3_close(ctx->db);
        ctx->db = NULL;
    }
    ctx->db_open = 0;
}

static int webd_insights_policy_available(const struct webd_insights_policy_ctx *ctx)
{
    return ctx && ctx->db && ctx->schema_supported && ctx->event_count > 0;
}

static void webd_insights_policy_sql_add_list(char *where, size_t where_len,
                                                const char *column,
                                                const struct webd_insights_filter_entry *entry,
                                                int exclude)
{
    char clause[2048];
    int i;

    if (!where || !where_len || !column || !entry || entry->count <= 0)
        return;
    snprintf(clause, sizeof(clause), " AND lower(COALESCE(%s,'')) %sIN (",
             column, exclude ? "NOT " : "");
    for (i = 0; i < entry->count; i++) {
        char esc[WEBD_INSIGHTS_FILTER_VALUE_LEN * 2 + 1];
        size_t j, k = 0;

        if (i > 0)
            strncat(clause, ",", sizeof(clause) - strlen(clause) - 1);
        for (j = 0; entry->values[i][j] && k + 2 < sizeof(esc); j++) {
            char c = (char)tolower((unsigned char)entry->values[i][j]);
            if (c == '\'')
                esc[k++] = '\'';
            esc[k++] = c;
        }
        esc[k] = '\0';
        strncat(clause, "'", sizeof(clause) - strlen(clause) - 1);
        strncat(clause, esc, sizeof(clause) - strlen(clause) - 1);
        strncat(clause, "'", sizeof(clause) - strlen(clause) - 1);
    }
    strncat(clause, ")", sizeof(clause) - strlen(clause) - 1);
    strncat(where, clause, where_len - strlen(where) - 1);
}

static void webd_insights_policy_sql_add_text_like(char *where, size_t where_len,
                                                   const char *column,
                                                   const struct webd_insights_filter_entry *entry,
                                                   int exclude)
{
    char clause[2048];
    int i;

    if (!where || !where_len || !column || !entry || entry->count <= 0)
        return;
    snprintf(clause, sizeof(clause), " AND %s (", exclude ? "NOT" : "");
    for (i = 0; i < entry->count; i++) {
        char esc[WEBD_INSIGHTS_FILTER_VALUE_LEN * 2 + 1];
        size_t j, k = 0;

        if (i > 0)
            strncat(clause, " OR ", sizeof(clause) - strlen(clause) - 1);
        for (j = 0; entry->values[i][j] && k + 2 < sizeof(esc); j++) {
            char c = (char)tolower((unsigned char)entry->values[i][j]);
            if (c == '\'')
                esc[k++] = '\'';
            esc[k++] = c;
        }
        esc[k] = '\0';
        strncat(clause, "lower(COALESCE(", sizeof(clause) - strlen(clause) - 1);
        strncat(clause, column, sizeof(clause) - strlen(clause) - 1);
        strncat(clause, ",'')) LIKE '%", sizeof(clause) - strlen(clause) - 1);
        strncat(clause, esc, sizeof(clause) - strlen(clause) - 1);
        strncat(clause, "%'", sizeof(clause) - strlen(clause) - 1);
    }
    strncat(clause, ")", sizeof(clause) - strlen(clause) - 1);
    strncat(where, clause, where_len - strlen(where) - 1);
}


static int webd_insights_filter_bool_value(const char *value, int *out)
{
    if (!value || !value[0] || !out)
        return 0;
    if (!strcasecmp(value, "1") || !strcasecmp(value, "true") ||
        !strcasecmp(value, "yes") || !strcasecmp(value, "on") ||
        !strcasecmp(value, "test") || !strcasecmp(value, "manual")) {
        *out = 1;
        return 1;
    }
    if (!strcasecmp(value, "0") || !strcasecmp(value, "false") ||
        !strcasecmp(value, "no") || !strcasecmp(value, "off") ||
        !strcasecmp(value, "prod") || !strcasecmp(value, "production")) {
        *out = 0;
        return 1;
    }
    return 0;
}

static void webd_insights_policy_sql_add_bool_expr(char *where, size_t where_len,
                                                   const char *expr,
                                                   const struct webd_insights_filter_entry *entry,
                                                   int exclude)
{
    int desired = 0;

    if (!where || !where_len || !expr || !entry || entry->count <= 0)
        return;
    if (!webd_insights_filter_bool_value(entry->values[0], &desired))
        desired = 1;
    strncat(where, desired ? (exclude ? " AND NOT (" : " AND (")
                             : (exclude ? " AND (" : " AND NOT (") ,
            where_len - strlen(where) - 1);
    strncat(where, expr, where_len - strlen(where) - 1);
    strncat(where, ")", where_len - strlen(where) - 1);
}

static void webd_insights_policy_build_where(const struct webd_insights_query *q,
                                             char *where, size_t where_len,
                                             int *postprocess_required)
{
    static const struct { const char *field; const char *column; int contains; } specs[] = {
        { "risk", "risk", 0 },
        { "action", "action", 0 },
        { "policy_type", "policy_type", 0 },
        { "policy", "policy_id", 1 },
        { "rule_id", "rule_id", 1 },
        { "rule_name", "rule_name", 1 },
        { "event_type", "event_type", 0 },
        { "source", "source", 1 },
        { "source_ip", "source_ip", 0 },
        { "ip", "source_ip", 0 },
        { "source_mac", "source_mac", 0 },
        { "mac", "source_mac", 0 },
        { "destination_ip", "destination_ip", 0 },
        { "remote_ip", "destination_ip", 0 },
        { "destination_host", "destination_host", 1 },
        { "host", "destination_host", 1 },
        { "protocol", "protocol", 0 },
        { "service", "protocol", 1 },
        { "app", "app_name", 1 },
        { "application", "app_name", 1 },
        { "app_id", "app_id", 0 },
        { "appid", "app_id", 0 },
        { "in_interface", "in_interface", 0 },
        { "out_interface", "out_interface", 0 },
    };
    int i;

    if (!where || !where_len)
        return;
    if (postprocess_required)
        *postprocess_required = 0;
    snprintf(where, where_len, " WHERE ts>=?1 AND ts<=?2 ");
    if (!q)
        return;
    if (q->search[0]) {
        char esc[512];
        size_t j, k = 0;

        for (j = 0; q->search[j] && k + 2 < sizeof(esc); j++) {
            char c = (char)tolower((unsigned char)q->search[j]);
            if (c == '\'')
                esc[k++] = '\'';
            esc[k++] = c;
        }
        esc[k] = '\0';
        strncat(where,
                " AND (lower(COALESCE(event_type,'')) LIKE '%",
                where_len - strlen(where) - 1);
        strncat(where, esc, where_len - strlen(where) - 1);
        strncat(where,
                "%' OR lower(COALESCE(policy_id,'')) LIKE '%",
                where_len - strlen(where) - 1);
        strncat(where, esc, where_len - strlen(where) - 1);
        strncat(where,
                "%' OR lower(COALESCE(policy_name,'')) LIKE '%",
                where_len - strlen(where) - 1);
        strncat(where, esc, where_len - strlen(where) - 1);
        strncat(where,
                "%' OR lower(COALESCE(rule_name,'')) LIKE '%",
                where_len - strlen(where) - 1);
        strncat(where, esc, where_len - strlen(where) - 1);
        strncat(where,
                "%' OR lower(COALESCE(destination_host,'')) LIKE '%",
                where_len - strlen(where) - 1);
        strncat(where, esc, where_len - strlen(where) - 1);
        strncat(where, "%' )", where_len - strlen(where) - 1);
    }
    for (i = 0; i < (int)(sizeof(specs) / sizeof(specs[0])); i++) {
        const struct webd_insights_filter_entry *inc = webd_insights_filter_get(q, 0, specs[i].field);
        const struct webd_insights_filter_entry *exc = webd_insights_filter_get(q, 1, specs[i].field);

        if (specs[i].contains) {
            webd_insights_policy_sql_add_text_like(where, where_len, specs[i].column, inc, 0);
            webd_insights_policy_sql_add_text_like(where, where_len, specs[i].column, exc, 1);
        } else {
            webd_insights_policy_sql_add_list(where, where_len, specs[i].column, inc, 0);
            webd_insights_policy_sql_add_list(where, where_len, specs[i].column, exc, 1);
        }
    }
    if (webd_insights_filter_active(q, 0, "source_port") ||
        webd_insights_filter_active(q, 1, "source_port")) {
        webd_insights_policy_sql_add_list(where, where_len, "CAST(source_port AS TEXT)",
                                          webd_insights_filter_get(q, 0, "source_port"), 0);
        webd_insights_policy_sql_add_list(where, where_len, "CAST(source_port AS TEXT)",
                                          webd_insights_filter_get(q, 1, "source_port"), 1);
    }
    if (webd_insights_filter_active(q, 0, "destination_port") ||
        webd_insights_filter_active(q, 1, "destination_port")) {
        webd_insights_policy_sql_add_list(where, where_len, "CAST(destination_port AS TEXT)",
                                          webd_insights_filter_get(q, 0, "destination_port"), 0);
        webd_insights_policy_sql_add_list(where, where_len, "CAST(destination_port AS TEXT)",
                                          webd_insights_filter_get(q, 1, "destination_port"), 1);
    }
    if (webd_insights_filter_active(q, 0, "test_event") ||
        webd_insights_filter_active(q, 1, "test_event")) {
        const char *expr = "(reason LIKE '%manual_test%' OR source LIKE '%manual_test%' OR meta_json LIKE '%\"test_event\":true%')";
        webd_insights_policy_sql_add_bool_expr(where, where_len, expr,
                                               webd_insights_filter_get(q, 0, "test_event"), 0);
        webd_insights_policy_sql_add_bool_expr(where, where_len, expr,
                                               webd_insights_filter_get(q, 1, "test_event"), 1);
    }
    if (webd_insights_filter_active(q, 0, "manual_ingest") ||
        webd_insights_filter_active(q, 1, "manual_ingest")) {
        const char *expr = "(reason LIKE '%manual%' OR source LIKE '%manual%' OR meta_json LIKE '%manual%')";
        webd_insights_policy_sql_add_bool_expr(where, where_len, expr,
                                               webd_insights_filter_get(q, 0, "manual_ingest"), 0);
        webd_insights_policy_sql_add_bool_expr(where, where_len, expr,
                                               webd_insights_filter_get(q, 1, "manual_ingest"), 1);
    }
    if (postprocess_required) {
        for (i = 0; i < q->include_filter_count; i++) {
            if (!webd_insights_filter_policy_sql_supported(q->include_filters[i].field))
                *postprocess_required = 1;
        }
        for (i = 0; i < q->exclude_filter_count; i++) {
            if (!webd_insights_filter_policy_sql_supported(q->exclude_filters[i].field))
                *postprocess_required = 1;
        }
    }
}

static void webd_insights_policy_hit_from_row(sqlite3_stmt *st,
                                              struct webd_insights_policy_hit *hit,
                                              const struct webd_insights_policy_ctx *ctx,
                                              const char *precision)
{
    if (!st || !hit)
        return;
    memset(hit, 0, sizeof(*hit));
    hit->supported = ctx && ctx->schema_supported;
    hit->matched = 1;
    hit->event_id = sqlite3_column_int64(st, 0);
    hit->ts = sqlite3_column_int64(st, 1);
    snprintf(hit->event_type, sizeof(hit->event_type), "%s", webd_sql_text(st, 2));
    snprintf(hit->level, sizeof(hit->level), "%s", webd_sql_text(st, 3));
    snprintf(hit->action, sizeof(hit->action), "%s", webd_sql_text(st, 4));
    snprintf(hit->policy_id, sizeof(hit->policy_id), "%s", webd_sql_text(st, 5));
    snprintf(hit->policy_name, sizeof(hit->policy_name), "%s", webd_sql_text(st, 6));
    snprintf(hit->policy_type, sizeof(hit->policy_type), "%s", webd_sql_text(st, 7));
    snprintf(hit->rule_id, sizeof(hit->rule_id), "%s", webd_sql_text(st, 8));
    snprintf(hit->rule_name, sizeof(hit->rule_name), "%s", webd_sql_text(st, 9));
    snprintf(hit->risk, sizeof(hit->risk), "%s", webd_sql_text(st, 10));
    snprintf(hit->risk_category, sizeof(hit->risk_category), "%s", webd_sql_text(st, 11));
    snprintf(hit->source_ip, sizeof(hit->source_ip), "%s", webd_sql_text(st, 12));
    snprintf(hit->source_mac, sizeof(hit->source_mac), "%s", webd_sql_text(st, 13));
    hit->source_port = sqlite3_column_int(st, 14);
    snprintf(hit->destination_ip, sizeof(hit->destination_ip), "%s", webd_sql_text(st, 15));
    snprintf(hit->destination_host, sizeof(hit->destination_host), "%s", webd_sql_text(st, 16));
    hit->destination_port = sqlite3_column_int(st, 17);
    snprintf(hit->protocol, sizeof(hit->protocol), "%s", webd_sql_text(st, 18));
    snprintf(hit->app_id, sizeof(hit->app_id), "%s", webd_sql_text(st, 19));
    snprintf(hit->app_name, sizeof(hit->app_name), "%s", webd_sql_text(st, 20));
    snprintf(hit->in_interface, sizeof(hit->in_interface), "%s", webd_sql_text(st, 21));
    snprintf(hit->out_interface, sizeof(hit->out_interface), "%s", webd_sql_text(st, 22));
    hit->rx_bytes = sqlite3_column_int64(st, 23);
    hit->tx_bytes = sqlite3_column_int64(st, 24);
    snprintf(hit->flow_id, sizeof(hit->flow_id), "%s", webd_sql_text(st, 25));
    snprintf(hit->reason, sizeof(hit->reason), "%s", webd_sql_text(st, 26));
    snprintf(hit->source, sizeof(hit->source), "%s", webd_sql_text(st, 27));
    snprintf(hit->meta_json, sizeof(hit->meta_json), "%s", webd_sql_text(st, 28));
    snprintf(hit->precision, sizeof(hit->precision), "%s",
             precision && precision[0] ? precision : "aegis_events");
}

static const char *webd_insights_policy_select_sql(void)
{
    return
        "SELECT id,ts,event_type,level,action,policy_id,policy_name,policy_type,"
        "rule_id,rule_name,risk,risk_category,source_ip,source_mac,source_port,"
        "destination_ip,destination_host,destination_port,protocol,app_id,app_name,"
        "in_interface,out_interface,rx_bytes,tx_bytes,flow_id,reason,source,meta_json "
        "FROM aegis_events ";
}

static int webd_insights_policy_lookup_flow_id(struct webd_insights_policy_ctx *ctx,
                                               const char *flow_id,
                                               int64_t ts,
                                               struct webd_insights_policy_hit *hit)
{
    sqlite3_stmt *st = NULL;
    char sql[1024];
    int64_t now = now_s();
    int64_t from = ts > 0 ? ts - 3600 : now - 86400;
    int64_t to = ts > 0 ? ts + 3600 : now;
    int found = 0;

    if (!webd_insights_policy_available(ctx) || !flow_id || !flow_id[0])
        return 0;
    if (from < 0)
        from = 0;
    snprintf(sql, sizeof(sql), "%s"
             "WHERE flow_id=?1 AND ts>=?2 AND ts<=?3 "
             "ORDER BY ABS(ts-?4),ts DESC,id DESC LIMIT 1",
             webd_insights_policy_select_sql());
    if (sqlite3_prepare_v2(ctx->db, sql, -1, &st, NULL) != SQLITE_OK) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_events_flow_id_prepare_failed:%s",
                 sqlite3_errmsg(ctx->db));
        return 0;
    }
    sqlite3_bind_text(st, 1, flow_id, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 2, from);
    sqlite3_bind_int64(st, 3, to);
    sqlite3_bind_int64(st, 4, ts > 0 ? ts : now);
    if (sqlite3_step(st) == SQLITE_ROW) {
        webd_insights_policy_hit_from_row(st, hit, ctx, "exact_flow_id");
        found = 1;
    }
    sqlite3_finalize(st);
    return found;
}

static int webd_insights_policy_lookup_tuple(struct webd_insights_policy_ctx *ctx,
                                             int64_t ts,
                                             const char *source_ip,
                                             const char *source_mac,
                                             int source_port,
                                             const char *destination_ip,
                                             const char *destination_host,
                                             int destination_port,
                                             const char *protocol,
                                             struct webd_insights_policy_hit *hit)
{
    sqlite3_stmt *st = NULL;
    char sql[2048];
    int64_t now = now_s();
    int64_t from = ts > 0 ? ts - 300 : now - 3600;
    int64_t to = ts > 0 ? ts + 300 : now;
    const char *sip = source_ip ? source_ip : "";
    const char *smac = source_mac ? source_mac : "";
    const char *dip = destination_ip ? destination_ip : "";
    const char *dhost = destination_host ? destination_host : "";
    const char *proto = protocol ? protocol : "";
    const char *precision;
    int found = 0;

    if (!webd_insights_policy_available(ctx))
        return 0;
    if ((!sip[0] && !smac[0]) || (!dip[0] && !dhost[0]))
        return 0;
    if (from < 0)
        from = 0;
    precision = (source_port > 0 && destination_port > 0 && proto[0]) ?
        "five_tuple_time_window" : "client_destination_time_window";
    snprintf(sql, sizeof(sql), "%s"
             "WHERE ts>=?1 AND ts<=?2 "
             "AND ((?3<>'' AND source_ip=?3) OR (?4<>'' AND lower(source_mac)=lower(?4))) "
             "AND ((?5<>'' AND destination_ip=?5) OR (?6<>'' AND lower(destination_host)=lower(?6))) "
             "AND (?7=0 OR source_port=?7) "
             "AND (?8=0 OR destination_port=?8) "
             "AND (?9='' OR lower(protocol)=lower(?9)) "
             "ORDER BY "
             "CASE WHEN flow_id<>'' THEN 0 ELSE 1 END,"
             "CASE WHEN action IN ('block','drop','reject','deny') THEN 0 WHEN action='alert' THEN 1 ELSE 2 END,"
             "ABS(ts-?10),ts DESC,id DESC LIMIT 1",
             webd_insights_policy_select_sql());
    if (sqlite3_prepare_v2(ctx->db, sql, -1, &st, NULL) != SQLITE_OK) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_events_tuple_prepare_failed:%s",
                 sqlite3_errmsg(ctx->db));
        return 0;
    }
    sqlite3_bind_int64(st, 1, from);
    sqlite3_bind_int64(st, 2, to);
    sqlite3_bind_text(st, 3, sip, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 4, smac, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 5, dip, -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(st, 6, dhost, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int(st, 7, source_port > 0 ? source_port : 0);
    sqlite3_bind_int(st, 8, destination_port > 0 ? destination_port : 0);
    sqlite3_bind_text(st, 9, proto, -1, SQLITE_TRANSIENT);
    sqlite3_bind_int64(st, 10, ts > 0 ? ts : now);
    if (sqlite3_step(st) == SQLITE_ROW) {
        webd_insights_policy_hit_from_row(st, hit, ctx, precision);
        found = 1;
    }
    sqlite3_finalize(st);
    return found;
}

static void webd_insights_policy_lookup(struct webd_insights_policy_ctx *ctx,
                                        int64_t ts,
                                        const char *flow_id,
                                        const char *source_ip,
                                        const char *source_mac,
                                        int source_port,
                                        const char *destination_ip,
                                        const char *destination_host,
                                        int destination_port,
                                        const char *protocol,
                                        struct webd_insights_policy_hit *hit)
{
    if (!hit)
        return;
    webd_insights_policy_hit_clear(hit, ctx, "none");
    if (!webd_insights_policy_available(ctx))
        return;
    if (webd_insights_policy_lookup_flow_id(ctx, flow_id, ts, hit))
        return;
    if (webd_insights_policy_lookup_tuple(ctx, ts, source_ip, source_mac, source_port,
                                          destination_ip, destination_host,
                                          destination_port, protocol, hit))
        return;
    webd_insights_policy_hit_clear(hit, ctx, "no_matching_aegis_event");
}


static int webd_insights_policy_hit_test_event(const struct webd_insights_policy_hit *hit)
{
    struct json_object *meta = NULL;
    int test_event = 0;

    if (!hit)
        return 0;
    if (strstr(hit->reason, "manual_test") || strstr(hit->source, "manual_test"))
        return 1;
    if (hit->meta_json[0]) {
        meta = json_tokener_parse(hit->meta_json);
        if (meta) {
            test_event = app_nc_json_bool(meta, "test_event", 0) ||
                         app_nc_json_bool(meta, "manual_ingest", 0);
            json_object_put(meta);
        }
    }
    return test_event;
}

static void webd_insights_policy_hit_add_meta_fields(struct json_object *dst,
                                                     const struct webd_insights_policy_hit *hit)
{
    struct json_object *meta = NULL;
    int test_event;

    if (!dst || !hit)
        return;
    test_event = webd_insights_policy_hit_test_event(hit);
    json_object_object_add(dst, "test_event", json_object_new_boolean(test_event));
    json_object_object_add(dst, "manual_ingest", json_object_new_boolean(
        strstr(hit->reason, "manual") != NULL || strstr(hit->source, ".manual") != NULL));
    if (!hit->meta_json[0])
        return;
    meta = json_tokener_parse(hit->meta_json);
    if (!meta)
        return;
    json_object_object_add(dst, "meta", meta);
    if (app_nc_json_has(meta, "drop_confirmed"))
        json_object_object_add(dst, "drop_confirmed",
                               json_object_new_boolean(app_nc_json_bool(meta, "drop_confirmed", 0)));
    if (app_nc_json_has(meta, "sampled_flow"))
        json_object_object_add(dst, "sampled_flow",
                               json_object_new_boolean(app_nc_json_bool(meta, "sampled_flow", 0)));
    if (app_nc_json_str(meta, "precision", "")[0])
        webd_obj_add_str(dst, "event_precision", app_nc_json_str(meta, "precision", ""));
    webd_copy_field_if_present(dst, meta, "severity");
    webd_copy_field_if_present(dst, meta, "sid");
    webd_copy_field_if_present(dst, meta, "gid");
    webd_copy_field_if_present(dst, meta, "rev");
    webd_copy_field_if_present(dst, meta, "signature");
    webd_copy_field_if_present(dst, meta, "category");
    webd_copy_field_if_present(dst, meta, "precision");
    webd_copy_field_if_present(dst, meta, "ingest_source");
    webd_copy_field_if_present(dst, meta, "matched_ip");
    webd_copy_field_if_present(dst, meta, "match_direction");
    webd_copy_field_if_present(dst, meta, "source_feed");
    webd_copy_field_if_present(dst, meta, "confidence");
    webd_copy_field_if_present(dst, meta, "drop_confirmed");
    webd_copy_field_if_present(dst, meta, "sampled_flow");
    webd_copy_field_if_present(dst, meta, "producer_source");
    webd_copy_field_if_present(dst, meta, "counter_source");
    webd_copy_field_if_present(dst, meta, "aggregate_counter");
    webd_copy_field_if_present(dst, meta, "delta_packets");
    webd_copy_field_if_present(dst, meta, "delta_bytes");
    webd_copy_field_if_present(dst, meta, "total_packets");
    webd_copy_field_if_present(dst, meta, "total_bytes");
    webd_copy_field_if_present(dst, meta, "table");
    webd_copy_field_if_present(dst, meta, "dataplane");
    webd_copy_field_if_present(dst, meta, "dataplane_action");
    webd_copy_field_if_present(dst, meta, "match_precision");
    webd_copy_field_if_present(dst, meta, "sample_source");
    webd_copy_field_if_present(dst, meta, "verified");
    webd_copy_field_if_present(dst, meta, "policy_hit");
    webd_copy_field_if_present(dst, meta, "security_event");
    webd_copy_field_if_present(dst, meta, "delta_hits");
    webd_copy_field_if_present(dst, meta, "total_hits");
    webd_copy_field_if_present(dst, meta, "orig_packets");
    webd_copy_field_if_present(dst, meta, "orig_bytes");
    webd_copy_field_if_present(dst, meta, "reply_packets");
    webd_copy_field_if_present(dst, meta, "reply_bytes");
}

static void webd_insights_apply_policy_hit_overlay(struct json_object *flow,
                                                   const struct webd_insights_policy_ctx *ctx,
                                                   const struct webd_insights_policy_hit *hit)
{
    struct json_object *event;
    int matched = hit && hit->matched;
    int supported = matched || (ctx && ctx->schema_supported);
    int available = matched || webd_insights_policy_available(ctx);
    const char *policy_name;
    const char *policy_type;
    const char *action;

    if (!flow || !json_object_is_type(flow, json_type_object))
        return;
    json_object_object_add(flow, "policy_supported", json_object_new_boolean(supported));
    json_object_object_add(flow, "policy_hit_supported", json_object_new_boolean(matched));
    json_object_object_add(flow, "policy_event_overlay_supported", json_object_new_boolean(available));
    json_object_object_add(flow, "policy_event_matched", json_object_new_boolean(matched));
    json_object_object_add(flow, "policy_match_exact", json_object_new_boolean(
        matched && hit && !strcmp(hit->precision, "exact_flow_id")));
    json_object_object_add(flow, "policy_engine_supported", json_object_new_boolean(supported));
    json_object_object_add(flow, "policy_runtime_apply_supported", json_object_new_boolean(0));
    json_object_object_add(flow, "policy_dataplane_accounting_supported", json_object_new_boolean(0));
    webd_obj_add_str(flow, "policy_scope", matched && hit && hit->policy_type[0] ? hit->policy_type : (available ? "aegis_events" : "unavailable"));
    webd_obj_add_str(flow, "policy_match_precision",
                     matched && hit ? hit->precision :
                     (available ? "none" : (ctx && ctx->error[0] ? ctx->error : "unavailable")));
    webd_obj_add_str(flow, "policy_source", matched ? "aegis_events" :
                     (available ? "aegis_events:no_match" : "unavailable"));
    webd_obj_add_str(flow, "policy_reason", matched ? "matched_aegis_event" :
                     (available ? "no_matching_aegis_event" :
                      (ctx && ctx->error[0] ? ctx->error : "policy_source_unavailable")));
    json_object_object_add(flow, "full_policy_supported", json_object_new_boolean(0));
    if (!matched) {
        const char *observed_action = app_nc_json_str(flow, "action", "allow");
        int ctnetlink_lifecycle =
            app_nc_json_bool(flow, "conntrack_event_lifecycle_enabled", 0) ||
            app_nc_json_bool(flow, "flow_lifecycle_exact", 0) ||
            !strcasecmp(app_nc_json_str(flow, "source_table", ""), "audit_flow_event_lifecycle") ||
            !strcasecmp(app_nc_json_str(flow, "lifecycle_source", ""), "audit_flow_event_lifecycle") ||
            !strcasecmp(app_nc_json_str(flow, "flow_event_join", ""), "ctnetlink_destroy_lifecycle");
        int observed_allow = ctnetlink_lifecycle &&
            (!observed_action || !observed_action[0] ||
             !strcasecmp(observed_action, "allow") ||
             !strcasecmp(observed_action, "accepted"));

        if (observed_allow) {
            /*
             * ctnetlink DESTROY means the kernel observed a completed conntrack
             * lifecycle.  That is a real dataplane "allowed/established flow"
             * observation, but not a policy-rule allow hit.  Keep the two
             * concepts separate so UniFi-style Insights can show verified flow
             * lifecycle without pretending a user policy explicitly allowed it.
             */
            webd_obj_add_str(flow, "action_source", "ctnetlink_destroy_observed_allow");
            webd_obj_add_str(flow, "action_semantic",
                             available ?
                             "observed_allow_conntrack_lifecycle_no_policy_match" :
                             "observed_allow_conntrack_lifecycle_policy_source_unavailable");
            json_object_object_add(flow, "dataplane_action_supported", json_object_new_boolean(1));
            json_object_object_add(flow, "netfilter_allow_observed", json_object_new_boolean(1));
            json_object_object_add(flow, "netfilter_allow_policy_accounting", json_object_new_boolean(0));
            webd_obj_add_str(flow, "netfilter_allow_accounting_source", "ctnetlink_destroy_lifecycle");
            webd_obj_add_str(flow, "netfilter_allow_accounting_semantics",
                             "completed conntrack lifecycle observed as allow; explicit policy allow rule accounting is not available");
        } else {
            webd_obj_add_str(flow, "action_source",
                             available ? "no_policy_match_default_allow" :
                             (observed_action && strcasecmp(observed_action, "allow") ?
                              "audit_flow_observed_action" : "audit_flow_default_allow"));
            webd_obj_add_str(flow, "action_semantic",
                             available ? "default_allow_no_policy_match" :
                             (observed_action && strcasecmp(observed_action, "allow") ?
                              "observed_action_without_policy_source" : "default_allow_policy_source_unavailable"));
            json_object_object_add(flow, "dataplane_action_supported", json_object_new_boolean(0));
            json_object_object_add(flow, "netfilter_allow_observed", json_object_new_boolean(0));
            json_object_object_add(flow, "netfilter_allow_policy_accounting", json_object_new_boolean(0));
        }
        return;
    }

    policy_name = hit->policy_name[0] ? hit->policy_name :
        (hit->policy_id[0] ? hit->policy_id : hit->rule_name);
    policy_type = hit->policy_type[0] ? hit->policy_type : hit->event_type;
    action = hit->action[0] ? hit->action : app_nc_json_str(flow, "action", "allow");
    webd_obj_add_str(flow, "action", action);
    webd_obj_add_str(flow, "action_source", "aegis_events");
    {
        int drop_confirmed = 0;
        int sampled_flow = 0;
        struct json_object *meta = hit->meta_json[0] ? json_tokener_parse(hit->meta_json) : NULL;

        if (meta) {
            drop_confirmed = app_nc_json_bool(meta, "drop_confirmed", 0);
            sampled_flow = app_nc_json_bool(meta, "sampled_flow", 0);
            json_object_put(meta);
        }
        json_object_object_add(flow, "drop_confirmed", json_object_new_boolean(drop_confirmed));
        json_object_object_add(flow, "sampled_flow", json_object_new_boolean(sampled_flow));
        webd_obj_add_str(flow, "action_semantic",
                         (!strcasecmp(action, "block") || !strcasecmp(action, "drop") ||
                          !strcasecmp(action, "reject") || !strcasecmp(action, "deny")) ?
                         (drop_confirmed ? "security_block_confirmed" : "security_block_observed") :
                         (!strcasecmp(action, "alert") ?
                          (sampled_flow ? "security_alert_conntrack_snapshot" : "security_alert") :
                          "security_event_observed_allow"));
        json_object_object_add(flow, "dataplane_action_supported",
                               json_object_new_boolean(drop_confirmed ||
                                   (!strcasecmp(action, "block") || !strcasecmp(action, "drop") ||
                                    !strcasecmp(action, "reject") || !strcasecmp(action, "deny"))));
    }
    webd_obj_add_str(flow, "policy", policy_name);
    webd_obj_add_str(flow, "policy_id", hit->policy_id);
    webd_obj_add_str(flow, "policy_name", policy_name);
    webd_obj_add_str(flow, "policy_type", policy_type);
    webd_obj_add_str(flow, "rule_id", hit->rule_id);
    webd_obj_add_str(flow, "rule_name", hit->rule_name);
    if (hit->risk[0] && strcasecmp(hit->risk, "unknown")) {
        webd_obj_add_str(flow, "risk", hit->risk);
        webd_obj_add_str(flow, "risk_level", hit->risk);
        webd_obj_add_str(flow, "risk_source", "aegis_events");
        json_object_object_add(flow, "risk_matched", json_object_new_boolean(1));
    }
    if (hit->risk_category[0])
        webd_obj_add_str(flow, "risk_category", hit->risk_category);
    if (hit->source_ip[0])
        webd_obj_add_str(flow, "source_ip", hit->source_ip);
    if (hit->source_mac[0])
        webd_obj_add_str(flow, "source_mac", hit->source_mac);
    if (hit->destination_ip[0])
        webd_obj_add_str(flow, "destination_ip", hit->destination_ip);
    if (hit->destination_host[0]) {
        webd_obj_add_str(flow, "destination_host", hit->destination_host);
        webd_obj_add_str(flow, "host", hit->destination_host);
    }
    if (hit->protocol[0])
        webd_obj_add_str(flow, "protocol", hit->protocol);
    if (hit->source_port > 0)
        json_object_object_add(flow, "source_port", json_object_new_int(hit->source_port));
    if (hit->destination_port > 0)
        json_object_object_add(flow, "destination_port", json_object_new_int(hit->destination_port));
    webd_insights_add_client_attribution(flow, hit->source_ip, hit->source_mac);
    if (hit->app_id[0])
        webd_obj_add_str(flow, "security_app_id", hit->app_id);
    if (hit->app_name[0])
        webd_obj_add_str(flow, "security_app_name", hit->app_name);
    if (hit->in_interface[0])
        webd_obj_add_str(flow, "security_in_interface", hit->in_interface);
    if (hit->out_interface[0])
        webd_obj_add_str(flow, "security_out_interface", hit->out_interface);

    event = json_object_new_object();
    json_object_object_add(event, "id", json_object_new_int64(hit->event_id));
    json_object_object_add(event, "ts", json_object_new_int64(hit->ts));
    webd_obj_add_str(event, "event_type", hit->event_type);
    webd_obj_add_str(event, "level", hit->level);
    webd_obj_add_str(event, "action", hit->action);
    webd_obj_add_str(event, "policy_id", hit->policy_id);
    webd_obj_add_str(event, "policy_name", hit->policy_name);
    webd_obj_add_str(event, "policy_type", hit->policy_type);
    webd_obj_add_str(event, "rule_id", hit->rule_id);
    webd_obj_add_str(event, "rule_name", hit->rule_name);
    webd_obj_add_str(event, "risk", hit->risk);
    webd_obj_add_str(event, "risk_category", hit->risk_category);
    webd_obj_add_str(event, "source_ip", hit->source_ip);
    webd_obj_add_str(event, "source_mac", hit->source_mac);
    json_object_object_add(event, "source_port", json_object_new_int(hit->source_port));
    webd_obj_add_str(event, "destination_ip", hit->destination_ip);
    webd_obj_add_str(event, "destination_host", hit->destination_host);
    json_object_object_add(event, "destination_port", json_object_new_int(hit->destination_port));
    webd_obj_add_str(event, "protocol", hit->protocol);
    webd_obj_add_str(event, "flow_id", hit->flow_id);
    webd_obj_add_str(event, "reason", hit->reason);
    webd_obj_add_str(event, "source", hit->source);
    webd_obj_add_str(event, "match_precision", hit->precision);
    webd_insights_policy_hit_add_meta_fields(event, hit);
    webd_insights_add_client_attribution(event, hit->source_ip, hit->source_mac);
    json_object_object_add(flow, "security_event", event);
}

static void webd_insights_add_trust_contract(struct json_object *item)
{
    const char *risk_source;
    const char *action_source;
    const char *policy_source;
    int risk_matched;
    int risk_supported;
    int policy_matched;
    int dataplane_action;
    int action_verified;

    if (!item || !json_object_is_type(item, json_type_object))
        return;
    risk_source = app_nc_json_str(item, "risk_source", "");
    action_source = app_nc_json_str(item, "action_source", "");
    policy_source = app_nc_json_str(item, "policy_source", "");
    risk_matched = app_nc_json_bool(item, "risk_matched", 0) ||
                   app_nc_json_bool(item, "risk_overlay_matched", 0);
    risk_supported = app_nc_json_bool(item, "risk_supported", 0) ||
                     app_nc_json_bool(item, "risk_overlay_supported", 0);
    policy_matched = app_nc_json_bool(item, "policy_event_matched", 0) ||
                     app_nc_json_bool(item, "policy_hit_supported", 0);
    dataplane_action = app_nc_json_bool(item, "dataplane_action_supported", 0);
    action_verified = dataplane_action ||
        (action_source && (!strcmp(action_source, "aegis_events") ||
                           !strcmp(action_source, "dataplane") ||
                           !strcmp(action_source, "nft") ||
                           !strcmp(action_source, "suricata") ||
                           !strcmp(action_source, "ctnetlink_destroy_observed_allow")));

    json_object_object_add(item, "risk_verified", json_object_new_boolean(risk_matched));
    json_object_object_add(item, "risk_known", json_object_new_boolean(risk_matched));
    json_object_object_add(item, "risk_default_unknown", json_object_new_boolean(!risk_matched));
    webd_obj_add_str(item, "risk_confidence_label",
                     risk_matched ? "matched" : (risk_supported ? "no_match" : "unsupported"));
    if (!risk_source || !risk_source[0])
        webd_obj_add_str(item, "risk_source", risk_supported ? "aegis_reputation:no_match" : "unavailable");

    json_object_object_add(item, "policy_verified", json_object_new_boolean(policy_matched));
    json_object_object_add(item, "policy_default_empty", json_object_new_boolean(!policy_matched));
    webd_obj_add_str(item, "policy_confidence_label",
                     policy_matched ? "matched" :
                     (policy_source && strstr(policy_source, "no_match") ? "no_match" : "unsupported"));
    if (!policy_source || !policy_source[0])
        webd_obj_add_str(item, "policy_source", "unavailable");

    json_object_object_add(item, "action_verified", json_object_new_boolean(action_verified));
    json_object_object_add(item, "action_default_allow",
                           json_object_new_boolean(!action_verified &&
                               !strcasecmp(app_nc_json_str(item, "action", "allow"), "allow")));
    webd_obj_add_str(item, "action_confidence_label",
                     !strcmp(action_source ? action_source : "", "ctnetlink_destroy_observed_allow") ?
                     "verified_flow_lifecycle_no_policy_match" :
                     (action_verified ? "verified" : "default_or_observed_without_policy"));
    if (!action_source || !action_source[0])
        webd_obj_add_str(item, "action_source", "audit_flow_sample_or_default_allow");
}

static void webd_insights_host_normalize(const char *input, char *out, size_t out_len)
{
    const char *s;
    size_t n = 0;

    if (!out || out_len == 0)
        return;
    out[0] = '\0';
    if (!input || !input[0])
        return;
    s = strstr(input, "://");
    s = s ? s + 3 : input;
    while (*s && isspace((unsigned char)*s))
        s++;
    while (*s == '.')
        s++;
    while (*s && *s != '/' && *s != '?' && *s != '#' &&
           *s != ':' && !isspace((unsigned char)*s) && n + 1 < out_len) {
        unsigned char c = (unsigned char)*s++;

        if (c <= 0x20 || c >= 0x7f)
            break;
        if (isalnum(c) || c == '-' || c == '_' || c == '.')
            out[n++] = (char)tolower(c);
    }
    while (n > 0 && out[n - 1] == '.')
        n--;
    out[n] = '\0';
}

static const char *webd_insights_risk_from_category(const char *category, int severity,
                                                    char *level, size_t level_len)
{
    char cbuf[128];
    const char *risk = "unknown";
    const char *cat = category ? category : "";

    snprintf(cbuf, sizeof(cbuf), "%s", cat);
    for (char *p = cbuf; *p; p++)
        *p = (char)tolower((unsigned char)*p);

    if (severity >= 90 || strstr(cbuf, "malware") || strstr(cbuf, "c2") ||
        strstr(cbuf, "phish") || strstr(cbuf, "exploit") || strstr(cbuf, "botnet"))
        risk = "high";
    else if (severity >= 70 || strstr(cbuf, "urlhaus") || strstr(cbuf, "threat") ||
             strstr(cbuf, "suspicious"))
        risk = "suspicious";
    else if (strstr(cbuf, "gambling") || strstr(cbuf, "adult") ||
             strstr(cbuf, "porn") || strstr(cbuf, "fakenews"))
        risk = "concerning";
    else if (strstr(cbuf, "ads") || strstr(cbuf, "tracker") ||
             strstr(cbuf, "tracking"))
        risk = "low";
    else if (severity > 0)
        risk = severity >= 60 ? "suspicious" : "low";

    if (level && level_len > 0)
        snprintf(level, level_len, "%s", risk);
    return risk;
}

static void webd_insights_risk_unknown(struct webd_insights_risk_annotation *ann,
                                       const struct webd_insights_risk_ctx *ctx,
                                       const char *reason)
{
    if (!ann)
        return;
    memset(ann, 0, sizeof(*ann));
    ann->supported = webd_insights_risk_available(ctx);
    snprintf(ann->risk, sizeof(ann->risk), "unknown");
    snprintf(ann->level, sizeof(ann->level), "unknown");
    snprintf(ann->source, sizeof(ann->source), "%s",
             ann->supported ? "aegis_reputation" : "unavailable");
    snprintf(ann->reason, sizeof(ann->reason), "%s",
             reason && reason[0] ? reason :
             (ctx && ctx->error[0] ? ctx->error : "no_reputation_match"));
}

static int webd_insights_risk_query_one(struct webd_insights_risk_ctx *ctx,
                                        const char *domain,
                                        struct webd_insights_risk_annotation *ann)
{
    static const char *rep_sql =
        "SELECT category,severity,confidence,source_feed,value "
        "FROM aegis_reputation_items "
        "WHERE kind='domain' AND value=? "
        "ORDER BY severity DESC, confidence DESC LIMIT 1";
    static const char *cat_sql =
        "SELECT category,0,confidence,source_feed,domain "
        "FROM aegis_domain_categories "
        "WHERE domain=? ORDER BY confidence DESC LIMIT 1";
    sqlite3_stmt *st = NULL;
    const char *sqls[2] = {rep_sql, cat_sql};
    int pass;

    if (!ctx || !ctx->db || !domain || !domain[0] || !ann)
        return 0;
    for (pass = 0; pass < 2; pass++) {
        if (sqlite3_prepare_v2(ctx->db, sqls[pass], -1, &st, NULL) != SQLITE_OK) {
            if (!ctx->error[0])
                snprintf(ctx->error, sizeof(ctx->error), "aegis_query_failed:%s",
                         sqlite3_errmsg(ctx->db));
            continue;
        }
        sqlite3_bind_text(st, 1, domain, -1, SQLITE_TRANSIENT);
        if (sqlite3_step(st) == SQLITE_ROW) {
            const char *category = (const char *)sqlite3_column_text(st, 0);
            int severity = sqlite3_column_int(st, 1);
            int confidence = sqlite3_column_int(st, 2);
            const char *feed = (const char *)sqlite3_column_text(st, 3);
            const char *matched = (const char *)sqlite3_column_text(st, 4);
            char level[32];
            const char *risk = webd_insights_risk_from_category(category, severity,
                                                                level, sizeof(level));

            memset(ann, 0, sizeof(*ann));
            ann->supported = 1;
            ann->matched = 1;
            snprintf(ann->risk, sizeof(ann->risk), "%s", risk);
            snprintf(ann->level, sizeof(ann->level), "%s", level);
            snprintf(ann->source, sizeof(ann->source), "%s",
                     pass == 0 ? "aegis_reputation_items" : "aegis_domain_categories");
            snprintf(ann->category, sizeof(ann->category), "%s", category ? category : "");
            snprintf(ann->feed, sizeof(ann->feed), "%s", feed ? feed : "");
            snprintf(ann->matched_domain, sizeof(ann->matched_domain), "%s",
                     matched && matched[0] ? matched : domain);
            snprintf(ann->reason, sizeof(ann->reason), "matched:%s",
                     pass == 0 ? "reputation_item" : "domain_category");
            ann->severity = severity;
            ann->confidence = confidence;
            sqlite3_finalize(st);
            return 1;
        }
        sqlite3_finalize(st);
        st = NULL;
    }
    return 0;
}

static void webd_insights_risk_lookup(struct webd_insights_risk_ctx *ctx,
                                      const char *host,
                                      struct webd_insights_risk_annotation *ann)
{
    char domain[256];
    char candidate[256];
    char *p;
    time_t now = time(NULL);
    int i;

    webd_insights_risk_unknown(ann, ctx, "no_reputation_match");
    if (!webd_insights_risk_available(ctx)) {
        webd_insights_risk_unknown(ann, ctx, ctx ? ctx->error : "aegis_db_unavailable");
        return;
    }
    webd_insights_host_normalize(host, domain, sizeof(domain));
    if (!domain[0]) {
        webd_insights_risk_unknown(ann, ctx, "empty_or_invalid_destination_host");
        return;
    }
    for (i = 0; i < WEBD_INSIGHTS_RISK_CACHE_MAX; i++) {
        struct webd_insights_risk_cache_entry *e = &g_webd_insights_risk_cache[i];

        if (!e->domain[0] || strcmp(e->domain, domain))
            continue;
        if (now - e->ts > WEBD_INSIGHTS_RISK_CACHE_TTL_S ||
            e->rep_count != ctx->rep_count ||
            e->category_count != ctx->category_count)
            continue;
        *ann = e->ann;
        return;
    }
    snprintf(candidate, sizeof(candidate), "%s", domain);
    p = candidate;
    while (p && *p) {
        if (webd_insights_risk_query_one(ctx, p, ann))
            break;
        p = strchr(p, '.');
        if (p)
            p++;
    }
    {
        struct webd_insights_risk_cache_entry *e =
            &g_webd_insights_risk_cache[g_webd_insights_risk_cache_cursor++ % WEBD_INSIGHTS_RISK_CACHE_MAX];

        snprintf(e->domain, sizeof(e->domain), "%s", domain);
        e->ann = *ann;
        e->ts = now;
        e->rep_count = ctx->rep_count;
        e->category_count = ctx->category_count;
    }
}

static int webd_insights_risk_matches_query(const struct webd_insights_query *q,
                                            const struct webd_insights_risk_annotation *ann)
{
    const char *values[3];

    if (!q)
        return 1;
    values[0] = ann && ann->risk[0] ? ann->risk : "unknown";
    values[1] = ann && ann->level[0] ? ann->level : "unknown";
    values[2] = ann && ann->category[0] ? ann->category : "";
    return webd_insights_filter_apply_field(q, "risk", values, 3, 0);
}

static void webd_insights_risk_for_flow(struct webd_insights_risk_ctx *ctx,
                                        struct json_object *flow,
                                        struct webd_insights_risk_annotation *ann)
{
    const char *host;

    if (!ann)
        return;
    host = webd_first_nonempty4(
        app_nc_json_str(flow, "destination_host", ""),
        app_nc_json_str(flow, "host", ""),
        app_nc_json_str(flow, "remote_ip", ""),
        app_nc_json_str(flow, "destination_ip",
            app_nc_json_str(flow, "dst", "")));
    webd_insights_risk_lookup(ctx, host, ann);
}

static void webd_insights_apply_flow_risk_overlay(struct json_object *flow,
                                                  const struct webd_insights_risk_annotation *ann)
{
    const char *raw_risk;
    const char *effective_risk;
    int raw_known;

    if (!flow || !json_object_is_type(flow, json_type_object))
        return;
    raw_risk = app_nc_json_str(flow, "risk", "");
    raw_known = raw_risk && raw_risk[0] && strcasecmp(raw_risk, "unknown");
    effective_risk = raw_known ? raw_risk :
        (ann && ann->risk[0] ? ann->risk : "unknown");

    webd_obj_add_str(flow, "risk", effective_risk);
    webd_obj_add_str(flow, "risk_level",
                     raw_known ? effective_risk :
                     (ann && ann->level[0] ? ann->level : "unknown"));
    json_object_object_add(flow, "risk_supported",
                           json_object_new_boolean(ann && ann->supported));
    json_object_object_add(flow, "risk_matched",
                           json_object_new_boolean(raw_known || (ann && ann->matched)));
    json_object_object_add(flow, "risk_overlay_supported",
                           json_object_new_boolean(ann && ann->supported));
    json_object_object_add(flow, "risk_overlay_matched",
                           json_object_new_boolean(ann && ann->matched));
    webd_obj_add_str(flow, "risk_source",
                     raw_known ? app_nc_json_str(flow, "risk_source", "audit_flow_record") :
                     (ann && ann->source[0] ? ann->source : "unavailable"));
    webd_obj_add_str(flow, "risk_category", ann && ann->category[0] ? ann->category : "");
    webd_obj_add_str(flow, "risk_feed", ann && ann->feed[0] ? ann->feed : "");
    webd_obj_add_str(flow, "risk_matched_domain",
                     ann && ann->matched_domain[0] ? ann->matched_domain : "");
    webd_obj_add_str(flow, "risk_reason",
                     raw_known ? app_nc_json_str(flow, "risk_reason", "record_has_risk") :
                     (ann && ann->reason[0] ? ann->reason : "no_reputation_match"));
    webd_obj_add_str(flow, "risk_annotation_source",
                     ann && ann->supported ? "webd.aegis_reputation_overlay" : "unavailable");
    json_object_object_add(flow, "risk_severity", json_object_new_int(ann ? ann->severity : 0));
    json_object_object_add(flow, "risk_confidence", json_object_new_int(ann ? ann->confidence : 0));
    json_object_object_add(flow, "policy_supported", json_object_new_boolean(0));
    json_object_object_add(flow, "policy_hit_supported", json_object_new_boolean(0));
    json_object_object_add(flow, "dataplane_action_supported", json_object_new_boolean(0));
    webd_obj_add_str(flow, "policy", app_nc_json_str(flow, "policy", ""));
    webd_obj_add_str(flow, "policy_type", app_nc_json_str(flow, "policy_type", ""));
    if (!json_object_object_get(flow, "action_source"))
        webd_obj_add_str(flow, "action_source", "audit_flow_sample_or_default_allow");
}

static void webd_insights_annotate_flow_array(struct json_object *arr,
                                              struct webd_insights_risk_ctx *ctx,
                                              struct webd_insights_policy_ctx *policy_ctx,
                                              int *annotated,
                                              int *matched,
                                              int *policy_matched)
{
    int i, n;

    if (!arr || !json_object_is_type(arr, json_type_array))
        return;
    n = (int)json_object_array_length(arr);
    for (i = 0; i < n; i++) {
        struct json_object *flow = json_object_array_get_idx(arr, i);
        struct webd_insights_risk_annotation ann;
        struct webd_insights_policy_hit policy_hit;
        const char *flow_id;
        const char *source_ip;
        const char *source_mac;
        const char *destination_ip;
        const char *destination_host;
        const char *protocol;
        int source_port;
        int destination_port;
        int64_t ts;

        if (!flow || !json_object_is_type(flow, json_type_object))
            continue;
        webd_insights_risk_for_flow(ctx, flow, &ann);
        webd_insights_apply_flow_risk_overlay(flow, &ann);
        ts = app_nc_json_int64(flow, "ts", app_nc_json_int64(flow, "timestamp",
             app_nc_json_int64(flow, "last_seen", 0)));
        flow_id = app_nc_json_str(flow, "flow_id", "");
        source_ip = webd_first_nonempty4(app_nc_json_str(flow, "source_ip", ""),
                                         app_nc_json_str(flow, "client_ip", ""),
                                         app_nc_json_str(flow, "src", ""),
                                         "");
        source_mac = webd_first_nonempty4(app_nc_json_str(flow, "source_mac", ""),
                                          app_nc_json_str(flow, "client_mac", ""),
                                          "", "");
        destination_ip = webd_first_nonempty4(app_nc_json_str(flow, "destination_ip", ""),
                                             app_nc_json_str(flow, "remote_ip", ""),
                                             app_nc_json_str(flow, "dst", ""),
                                             "");
        destination_host = webd_first_nonempty4(app_nc_json_str(flow, "destination_host", ""),
                                               app_nc_json_str(flow, "host", ""),
                                               "", "");
        protocol = app_nc_json_str(flow, "protocol", app_nc_json_str(flow, "proto", ""));
        source_port = app_nc_json_int(flow, "source_port", app_nc_json_int(flow, "sport", 0));
        destination_port = app_nc_json_int(flow, "destination_port", app_nc_json_int(flow, "dport", 0));
        webd_insights_policy_lookup(policy_ctx, ts, flow_id, source_ip, source_mac,
                                    source_port, destination_ip, destination_host,
                                    destination_port, protocol, &policy_hit);
        webd_insights_apply_policy_hit_overlay(flow, policy_ctx, &policy_hit);
        webd_insights_add_trust_contract(flow);
        if (annotated)
            (*annotated)++;
        if (matched && ann.matched)
            (*matched)++;
        if (policy_matched && policy_hit.matched)
            (*policy_matched)++;
    }
}

static void webd_insights_annotate_flow_data(struct json_object *data,
                                             struct webd_insights_risk_ctx *ctx)
{
    struct json_object *items = webd_obj_child_array(data, "items");
    struct json_object *flows = webd_obj_child_array(data, "flows");
    struct webd_insights_policy_ctx policy_ctx;
    int annotated = 0;
    int matched = 0;
    int policy_matched = 0;

    if (!data || !json_object_is_type(data, json_type_object))
        return;
    webd_insights_policy_ctx_init(&policy_ctx);
    webd_insights_annotate_flow_array(items, ctx, &policy_ctx,
                                      &annotated, &matched, &policy_matched);
    if (flows && flows != items)
        webd_insights_annotate_flow_array(flows, ctx, &policy_ctx,
                                          &annotated, &matched, &policy_matched);
    json_object_object_add(data, "risk_supported",
                           json_object_new_boolean(webd_insights_risk_available(ctx)));
    json_object_object_add(data, "risk_overlay_supported",
                           json_object_new_boolean(webd_insights_risk_available(ctx)));
    json_object_object_add(data, "risk_overlay_applied",
                           json_object_new_boolean(annotated > 0));
    json_object_object_add(data, "risk_matched_count", json_object_new_int(matched));
    webd_obj_add_str(data, "risk_annotation_source",
                     webd_insights_risk_available(ctx) ? "webd.aegis_reputation_overlay" : "unavailable");
    webd_obj_add_str(data, "risk_source_error", ctx ? ctx->error : "");
    json_object_object_add(data, "policy_supported", json_object_new_boolean(policy_ctx.schema_supported));
    json_object_object_add(data, "policy_event_overlay_supported",
                           json_object_new_boolean(webd_insights_policy_available(&policy_ctx)));
    json_object_object_add(data, "policy_hit_supported", json_object_new_boolean(policy_matched > 0));
    json_object_object_add(data, "policy_matched_count", json_object_new_int(policy_matched));
    json_object_object_add(data, "full_policy_supported", json_object_new_boolean(0));
    json_object_object_add(data, "dataplane_action_supported", json_object_new_boolean(policy_matched > 0));
    json_object_object_add(data, "action_verified_supported", json_object_new_boolean(policy_matched > 0));
    json_object_object_add(data, "default_allow_semantics", json_object_new_boolean(policy_matched <= 0));
    json_object_object_add(data, "risk_trust_fields_supported", json_object_new_boolean(1));
    json_object_object_add(data, "policy_trust_fields_supported", json_object_new_boolean(1));
    webd_obj_add_str(data, "action_source", policy_matched > 0 ?
                     "aegis_events+audit_flow_sample_or_default_allow" :
                     "audit_flow_sample_or_default_allow");
    webd_obj_add_str(data, "policy_source_error", policy_ctx.error);
    json_object_object_add(data, "capabilities", webd_insights_capabilities());
    webd_insights_policy_ctx_close(&policy_ctx);
}

struct webd_insights_aegis_stats {
    int schema_supported;
    int available;
    int total_all;
    int total;
    int blocks;
    int alerts;
    int dns_blocks;
    int last_event_at;
    int rows_scanned;
    int limited;
    int risk_unknown;
    int risk_low;
    int risk_suspicious;
    int risk_concerning;
    int risk_high;
    int action_allow;
    int action_block;
    int action_alert;
    int action_other;
    int policy_dns_filter;
    int policy_reputation_ip;
    int policy_ids_ips;
    int policy_route;
    int policy_other;
    int geo_external_event_candidates;
    int client_attributed;
    int client_unattributed;
    char reason[128];
    struct webd_insights_group policies[64];
    int policy_count;
    struct webd_insights_group destinations[64];
    int destination_count;
    struct webd_insights_group clients[64];
    int client_count;
};


static const char *webd_insights_policy_scope_from_stats(const struct webd_insights_aegis_stats *s)
{
    int kinds;

    if (!s || !s->schema_supported || s->total <= 0)
        return "unavailable";
    kinds = (s->policy_dns_filter > 0) + (s->policy_reputation_ip > 0) +
            (s->policy_ids_ips > 0) + (s->policy_route > 0) +
            (s->policy_other > 0);
    if (kinds > 1)
        return "mixed_aegis_events";
    if (s->policy_dns_filter > 0)
        return "dns_filter";
    if (s->policy_reputation_ip > 0)
        return "reputation_ip";
    if (s->policy_ids_ips > 0)
        return "ids_ips";
    if (s->policy_route > 0)
        return "policy_route";
    return "aegis_events";
}

static struct json_object *webd_insights_aegis_policy_type_breakdown_json(const struct webd_insights_aegis_stats *s)
{
    struct json_object *o = json_object_new_object();

    json_object_object_add(o, "dns_filter", json_object_new_int(s ? s->policy_dns_filter : 0));
    json_object_object_add(o, "reputation_ip", json_object_new_int(s ? s->policy_reputation_ip : 0));
    json_object_object_add(o, "ids_ips", json_object_new_int(s ? s->policy_ids_ips : 0));
    json_object_object_add(o, "policy_route", json_object_new_int(s ? s->policy_route : 0));
    json_object_object_add(o, "other", json_object_new_int(s ? s->policy_other : 0));
    json_object_object_add(o, "total", json_object_new_int(s ? s->total : 0));
    json_object_object_add(o, "source", json_object_new_string("aegis_events.policy_type"));
    return o;
}

static void webd_insights_aegis_stats_add_risk(struct webd_insights_aegis_stats *s,
                                               const char *risk, int inc)
{
    int n = inc > 0 ? inc : 1;

    if (!s)
        return;
    if (risk && !strcasecmp(risk, "low"))
        s->risk_low += n;
    else if (risk && (!strcasecmp(risk, "suspicious") || !strcasecmp(risk, "medium")))
        s->risk_suspicious += n;
    else if (risk && (!strcasecmp(risk, "concerning") || !strcasecmp(risk, "warn")))
        s->risk_concerning += n;
    else if (risk && (!strcasecmp(risk, "high") || !strcasecmp(risk, "critical")))
        s->risk_high += n;
    else
        s->risk_unknown += n;
}

static void webd_insights_aegis_stats_add_action(struct webd_insights_aegis_stats *s,
                                                 const char *action, int inc)
{
    int n = inc > 0 ? inc : 1;

    if (!s)
        return;
    if (action && (!strcasecmp(action, "block") || !strcasecmp(action, "blocked") ||
                   !strcasecmp(action, "drop") || !strcasecmp(action, "deny") ||
                   !strcasecmp(action, "reject"))) {
        s->action_block += n;
        s->blocks += n;
    } else if (action && !strcasecmp(action, "alert")) {
        s->action_alert += n;
        s->alerts += n;
    } else if (!action || !action[0] || !strcasecmp(action, "allow")) {
        s->action_allow += n;
    } else {
        s->action_other += n;
    }
}

static void webd_insights_aegis_group_add(struct webd_insights_group *groups,
                                          int *count, int max_groups,
                                          const char *key, const char *label,
                                          const char *mac, const char *ip,
                                          int inc, int64_t ts,
                                          const char *risk, const char *action,
                                          const char *category,
                                          const char *family)
{
    struct webd_insights_risk_annotation ann;
    int before = count ? *count : 0;

    memset(&ann, 0, sizeof(ann));
    ann.supported = 1;
    ann.matched = risk && risk[0] && strcasecmp(risk, "unknown");
    snprintf(ann.risk, sizeof(ann.risk), "%s", risk && risk[0] ? risk : "unknown");
    snprintf(ann.level, sizeof(ann.level), "%s", ann.risk);
    webd_insights_group_add(groups, count, max_groups, key, label, mac, ip, 0,
                            inc, ts, &ann, action);
    if (groups && count && *count > before && before < max_groups) {
        snprintf(groups[before].category, sizeof(groups[before].category), "%s",
                 category ? category : "");
        snprintf(groups[before].family, sizeof(groups[before].family), "%s",
                 family ? family : "");
        snprintf(groups[before].name_source, sizeof(groups[before].name_source), "%s",
                 "aegis_events");
    }
}

static int webd_insights_aegis_event_matches(const struct webd_insights_query *q,
                                             const char *event_type,
                                             const char *level,
                                             const char *action,
                                             const char *policy_id,
                                             const char *policy_name,
                                             const char *policy_type,
                                             const char *risk,
                                             const char *risk_category,
                                             const char *source_ip,
                                             const char *source_mac,
                                             int source_port,
                                             const char *destination_ip,
                                             const char *destination_host,
                                             int destination_port,
                                             const char *protocol,
                                             const char *app_id,
                                             const char *app_name,
                                             const char *in_interface,
                                             const char *out_interface,
                                             const char *reason,
                                             const char *source)
{
    char haystack[2048];
    const char *risk_values[] = { risk, level, risk_category };
    const char *action_values[] = { action };
    const char *policy_values[] = { policy_id, policy_name };
    const char *policy_type_values[] = { policy_type };
    const char *source_ip_values[] = { source_ip };
    const char *source_mac_values[] = { source_mac };
    const char *source_host_values[] = { source_ip, source_mac };
    const char *destination_host_values[] = { destination_host };
    const char *destination_ip_values[] = { destination_ip };
    const char *protocol_values[] = { protocol };
    const char *service_values[] = { protocol, destination_host, app_name, event_type };
    const char *app_values[] = { app_id, app_name, destination_host };
    const char *interface_values[] = { in_interface, out_interface };
    const char *direction_values[] = { "unknown" };
    char source_port_buf[32];
    char destination_port_buf[32];

    snprintf(source_port_buf, sizeof(source_port_buf), "%d", source_port);
    snprintf(destination_port_buf, sizeof(destination_port_buf), "%d", destination_port);

    if (!q)
        return 1;
    if (q->search[0]) {
        snprintf(haystack, sizeof(haystack),
                 "%s %s %s %s %s %s %s %s %s %s %s %s %s %s",
                 event_type ? event_type : "", level ? level : "",
                 action ? action : "", policy_id ? policy_id : "",
                 policy_name ? policy_name : "", policy_type ? policy_type : "",
                 risk ? risk : "", risk_category ? risk_category : "",
                 source_ip ? source_ip : "", source_mac ? source_mac : "",
                 destination_ip ? destination_ip : "",
                 destination_host ? destination_host : "",
                 reason ? reason : "", source ? source : "");
        if (!webd_str_contains_i(haystack, q->search))
            return 0;
    }
    if (!webd_insights_filter_apply_field(q, "risk", risk_values, 3, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "action", action_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "direction", direction_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "policy", policy_values, 2, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "policy_type", policy_type_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "source_ip", source_ip_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "ip", source_ip_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "source_mac", source_mac_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "mac", source_mac_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "source_host", source_host_values, 2, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "source_port",
                                          (const char *[]){ source_port_buf }, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "destination_host", destination_host_values, 1, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "host", destination_host_values, 1, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "destination_ip", destination_ip_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "remote_ip", destination_ip_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "destination_port",
                                          (const char *[]){ destination_port_buf }, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "protocol", protocol_values, 1, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "service", service_values, 4, 1))
        return 0;
    if (!webd_insights_filter_apply_field(q, "app", app_values, 3, 1) ||
        !webd_insights_filter_apply_field(q, "application", app_values, 3, 1) ||
        !webd_insights_filter_apply_field(q, "app_id", app_values, 3, 0) ||
        !webd_insights_filter_apply_field(q, "appid", app_values, 3, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "in_interface", interface_values, 2, 0))
        return 0;
    if (!webd_insights_filter_apply_field(q, "out_interface", interface_values, 2, 0))
        return 0;
    return 1;
}

static void webd_insights_aegis_stats_load(const struct webd_insights_query *q,
                                           struct webd_insights_aegis_stats *s)
{
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;
    int64_t ts_from = q ? q->ts_from : 0;
    int64_t ts_to = q ? q->ts_to : now_s();
    int limit = 2000;

    if (!s)
        return;
    memset(s, 0, sizeof(*s));
    snprintf(s->reason, sizeof(s->reason), "%s", "aegis_db_missing");
    if (access(WEBD_AEGIS_DB_PATH, R_OK) != 0)
        return;
    if (sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK || !db) {
        snprintf(s->reason, sizeof(s->reason), "%s", "aegis_db_open_failed");
        if (db)
            sqlite3_close(db);
        return;
    }
    sqlite3_busy_timeout(db, 50);
    s->schema_supported = webd_insights_sqlite_table_exists(db, "aegis_events");
    if (!s->schema_supported) {
        snprintf(s->reason, sizeof(s->reason), "%s", "aegis_events_table_missing");
        sqlite3_close(db);
        return;
    }
    if (sqlite3_prepare_v2(db, "SELECT COUNT(*) FROM aegis_events", -1, &st, NULL) == SQLITE_OK &&
        sqlite3_step(st) == SQLITE_ROW)
        s->total_all = sqlite3_column_int(st, 0);
    if (st)
        sqlite3_finalize(st);
    st = NULL;
    if (ts_to <= 0)
        ts_to = now_s();
    if (ts_from <= 0)
        ts_from = ts_to - webd_insights_period_seconds(q ? q->period : "day");
    if (sqlite3_prepare_v2(db,
            "SELECT ts,event_type,level,action,policy_id,policy_name,policy_type,"
            "risk,risk_category,source_ip,source_mac,source_port,destination_ip,destination_host,"
            "destination_port,protocol,app_id,app_name,in_interface,out_interface,"
            "rx_bytes,tx_bytes,reason,source "
            "FROM aegis_events WHERE ts>=?1 AND ts<=?2 "
            "ORDER BY ts DESC,id DESC LIMIT ?3",
            -1, &st, NULL) != SQLITE_OK) {
        snprintf(s->reason, sizeof(s->reason), "aegis_events_query_failed:%s",
                 sqlite3_errmsg(db));
        sqlite3_close(db);
        return;
    }
    sqlite3_bind_int64(st, 1, ts_from);
    sqlite3_bind_int64(st, 2, ts_to);
    sqlite3_bind_int(st, 3, limit + 1);
    while (sqlite3_step(st) == SQLITE_ROW) {
        int64_t ts = sqlite3_column_int64(st, 0);
        const char *event_type = (const char *)sqlite3_column_text(st, 1);
        const char *level = (const char *)sqlite3_column_text(st, 2);
        const char *action = (const char *)sqlite3_column_text(st, 3);
        const char *policy_id = (const char *)sqlite3_column_text(st, 4);
        const char *policy_name = (const char *)sqlite3_column_text(st, 5);
        const char *policy_type = (const char *)sqlite3_column_text(st, 6);
        const char *risk = (const char *)sqlite3_column_text(st, 7);
        const char *risk_category = (const char *)sqlite3_column_text(st, 8);
        const char *source_ip = (const char *)sqlite3_column_text(st, 9);
        const char *source_mac = (const char *)sqlite3_column_text(st, 10);
        int source_port = sqlite3_column_int(st, 11);
        const char *destination_ip = (const char *)sqlite3_column_text(st, 12);
        const char *destination_host = (const char *)sqlite3_column_text(st, 13);
        int destination_port = sqlite3_column_int(st, 14);
        const char *protocol = (const char *)sqlite3_column_text(st, 15);
        const char *app_id = (const char *)sqlite3_column_text(st, 16);
        const char *app_name = (const char *)sqlite3_column_text(st, 17);
        const char *in_interface = (const char *)sqlite3_column_text(st, 18);
        const char *out_interface = (const char *)sqlite3_column_text(st, 19);
        const char *reason = (const char *)sqlite3_column_text(st, 22);
        const char *source = (const char *)sqlite3_column_text(st, 23);
        char policy_key[384];
        char policy_label[384];
        char destination_label[256];
        char client_key[128];
        char client_label[128];
        int client_attributable;

        if (s->rows_scanned >= limit) {
            s->limited = 1;
            break;
        }
        s->rows_scanned++;
        if (!webd_insights_aegis_event_matches(q,
                event_type ? event_type : "", level ? level : "",
                action ? action : "", policy_id ? policy_id : "",
                policy_name ? policy_name : "", policy_type ? policy_type : "",
                risk ? risk : "", risk_category ? risk_category : "",
                source_ip ? source_ip : "", source_mac ? source_mac : "",
                source_port,
                destination_ip ? destination_ip : "",
                destination_host ? destination_host : "", destination_port,
                protocol ? protocol : "", app_id ? app_id : "",
                app_name ? app_name : "", in_interface ? in_interface : "",
                out_interface ? out_interface : "", reason ? reason : "",
                source ? source : ""))
            continue;
        s->total++;
        if (ts > s->last_event_at)
            s->last_event_at = (int)ts;
        if (destination_ip && destination_ip[0] &&
            !webd_insights_ip_is_private_or_local(destination_ip))
            s->geo_external_event_candidates++;
        webd_insights_aegis_stats_add_risk(s, risk, 1);
        webd_insights_aegis_stats_add_action(s, action, 1);
        if (policy_type && !strcasecmp(policy_type, "dns_filter"))
            s->policy_dns_filter++;
        else if (policy_type && (!strcasecmp(policy_type, "reputation_ip") ||
                                 webd_str_contains_i(policy_type, "reputation")))
            s->policy_reputation_ip++;
        else if (policy_type && (!strcasecmp(policy_type, "ids_ips") ||
                                 webd_str_contains_i(policy_type, "suricata")))
            s->policy_ids_ips++;
        else if (policy_type && (!strcasecmp(policy_type, "policy_route") ||
                                 webd_str_contains_i(policy_type, "route")))
            s->policy_route++;
        else
            s->policy_other++;
        if (policy_type && !strcasecmp(policy_type, "dns_filter") &&
            action && (!strcasecmp(action, "block") || !strcasecmp(action, "drop") ||
                       !strcasecmp(action, "reject")))
            s->dns_blocks++;
        snprintf(policy_key, sizeof(policy_key), "%s|%s",
                 policy_type && policy_type[0] ? policy_type : "unknown",
                 policy_id && policy_id[0] ? policy_id : "unknown");
        snprintf(policy_label, sizeof(policy_label), "%s",
                 policy_name && policy_name[0] ? policy_name :
                 (policy_id && policy_id[0] ? policy_id : policy_key));
        webd_insights_aegis_group_add(s->policies, &s->policy_count,
                                      (int)ARRAY_SIZE(s->policies),
                                      policy_key, policy_label, "", "", 1, ts,
                                      risk, action, policy_type, policy_id);
        snprintf(destination_label, sizeof(destination_label), "%s",
                 destination_host && destination_host[0] ? destination_host :
                 (destination_ip && destination_ip[0] ? destination_ip : "unknown"));
        if (destination_label[0] && strcmp(destination_label, "unknown"))
            webd_insights_aegis_group_add(s->destinations, &s->destination_count,
                                          (int)ARRAY_SIZE(s->destinations),
                                          destination_label, destination_label, "", "",
                                          1, ts, risk, action,
                                          risk_category, protocol);
        client_attributable = webd_insights_security_client_attributable(
            source_ip ? source_ip : "", source_mac ? source_mac : "");
        if (client_attributable)
            s->client_attributed++;
        else
            s->client_unattributed++;
        snprintf(client_key, sizeof(client_key), "%s",
                 source_mac && source_mac[0] ? source_mac :
                 (client_attributable && source_ip && source_ip[0] ? source_ip : ""));
        snprintf(client_label, sizeof(client_label), "%s",
                 client_attributable && source_ip && source_ip[0] ? source_ip :
                 (source_mac && source_mac[0] ? source_mac : ""));
        if (client_attributable && client_key[0])
            webd_insights_aegis_group_add(s->clients, &s->client_count,
                                          (int)ARRAY_SIZE(s->clients),
                                          client_key, client_label,
                                          source_mac ? source_mac : "",
                                          source_ip ? source_ip : "",
                                          1, ts, risk, action,
                                          policy_type, "");
    }
    sqlite3_finalize(st);
    sqlite3_close(db);
    s->available = s->total > 0;
    snprintf(s->reason, sizeof(s->reason), "%s",
             s->available ? "" :
             (s->total_all > 0 ? "no_aegis_events_in_selected_window_or_filters" :
              "no_policy_hit_events"));
}

static struct json_object *webd_insights_aegis_action_breakdown_json(const struct webd_insights_aegis_stats *s)
{
    struct json_object *o = json_object_new_object();

    json_object_object_add(o, "allow", json_object_new_int(s ? s->action_allow : 0));
    json_object_object_add(o, "block", json_object_new_int(s ? s->action_block : 0));
    json_object_object_add(o, "alert", json_object_new_int(s ? s->action_alert : 0));
    json_object_object_add(o, "other", json_object_new_int(s ? s->action_other : 0));
    return o;
}

static struct json_object *webd_insights_aegis_risk_breakdown_json(const struct webd_insights_aegis_stats *s)
{
    struct json_object *o = json_object_new_object();

    json_object_object_add(o, "unknown", json_object_new_int(s ? s->risk_unknown : 0));
    json_object_object_add(o, "low", json_object_new_int(s ? s->risk_low : 0));
    json_object_object_add(o, "suspicious", json_object_new_int(s ? s->risk_suspicious : 0));
    json_object_object_add(o, "concerning", json_object_new_int(s ? s->risk_concerning : 0));
    json_object_object_add(o, "high", json_object_new_int(s ? s->risk_high : 0));
    json_object_object_add(o, "supported", json_object_new_boolean(s && s->schema_supported));
    json_object_object_add(o, "source", json_object_new_string("aegis_events"));
    return o;
}

static struct json_object *webd_insights_aegis_groups_to_array(struct webd_insights_group *groups,
                                                              int count, int limit,
                                                              const char *kind)
{
    struct json_object *arr = json_object_new_array();
    int i;

    if (!groups || count <= 0)
        return arr;
    if (count > 1)
        qsort(groups, (size_t)count, sizeof(groups[0]), webd_insights_group_cmp);
    if (limit <= 0 || limit > count)
        limit = count;
    for (i = 0; i < limit; i++) {
        struct json_object *o = json_object_new_object();

        webd_obj_add_str(o, "id", groups[i].key);
        webd_obj_add_str(o, "key", groups[i].key);
        webd_obj_add_str(o, "name", groups[i].label);
        webd_obj_add_str(o, "display_name", groups[i].label);
        webd_obj_add_str(o, "type", kind && kind[0] ? kind : "security_event");
        webd_obj_add_str(o, "metric_type", "event_count");
        webd_obj_add_str(o, "ranking_basis", "aegis_policy_hit_events");
        webd_obj_add_str(o, "semantic", "cybersecure_policy_hit_events");
        webd_obj_add_str(o, "source", "aegis_events");
        json_object_object_add(o, "count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "event_count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "hit_count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "last_seen", json_object_new_int64(groups[i].last_ts));
        json_object_object_add(o, "risk_breakdown", webd_insights_aegis_risk_breakdown_json(
            &(struct webd_insights_aegis_stats){
                .risk_unknown = groups[i].risk_unknown,
                .risk_low = groups[i].risk_low,
                .risk_suspicious = groups[i].risk_suspicious,
                .risk_concerning = groups[i].risk_concerning,
                .risk_high = groups[i].risk_high,
                .schema_supported = 1
            }));
        json_object_object_add(o, "action_breakdown", webd_insights_aegis_action_breakdown_json(
            &(struct webd_insights_aegis_stats){
                .action_allow = groups[i].action_allow,
                .action_block = groups[i].action_block,
                .action_other = groups[i].action_other
            }));
        json_object_object_add(o, "affected", json_object_new_boolean(groups[i].affected_count > 0));
        json_object_object_add(o, "affected_count", json_object_new_int(groups[i].affected_count));
        json_object_object_add(o, "risk_supported", json_object_new_boolean(1));
        json_object_object_add(o, "policy_supported", json_object_new_boolean(1));
        json_object_object_add(o, "policy_hit_supported", json_object_new_boolean(1));
        webd_obj_add_str(o, "action", groups[i].action_block > 0 ? "block" :
                         (groups[i].action_other > 0 ? "other" : "allow"));
        if (kind && !strcmp(kind, "policy")) {
            webd_obj_add_str(o, "policy_key", groups[i].key);
            webd_obj_add_str(o, "policy_type", groups[i].category);
            webd_obj_add_str(o, "policy_id", groups[i].family);
        } else if (kind && !strcmp(kind, "client")) {
            webd_obj_add_str(o, "mac", groups[i].mac);
            webd_obj_add_str(o, "ip", groups[i].ip);
            json_object_object_add(o, "client_attribution", json_object_new_boolean(1));
        } else {
            webd_obj_add_str(o, "destination_host", groups[i].key);
            webd_obj_add_str(o, "host", groups[i].key);
            webd_obj_add_str(o, "risk_category", groups[i].category);
            webd_obj_add_str(o, "protocol", groups[i].family);
        }
        json_object_array_add(arr, o);
    }
    return arr;
}

static struct json_object *webd_insights_aegis_stats_json(struct webd_insights_aegis_stats *s,
                                                         int top)
{
    struct json_object *o = json_object_new_object();

    json_object_object_add(o, "supported", json_object_new_boolean(s && s->schema_supported));
    json_object_object_add(o, "available", json_object_new_boolean(s && s->available));
    json_object_object_add(o, "total_all", json_object_new_int(s ? s->total_all : 0));
    json_object_object_add(o, "total", json_object_new_int(s ? s->total : 0));
    json_object_object_add(o, "events", json_object_new_int(s ? s->total : 0));
    json_object_object_add(o, "blocks", json_object_new_int(s ? s->blocks : 0));
    json_object_object_add(o, "alerts", json_object_new_int(s ? s->alerts : 0));
    json_object_object_add(o, "dns_blocks", json_object_new_int(s ? s->dns_blocks : 0));
    json_object_object_add(o, "last_event_at", json_object_new_int64(s ? s->last_event_at : 0));
    json_object_object_add(o, "rows_scanned", json_object_new_int(s ? s->rows_scanned : 0));
    json_object_object_add(o, "limited", json_object_new_boolean(s && s->limited));
    json_object_object_add(o, "geo_external_event_candidates",
                           json_object_new_int(s ? s->geo_external_event_candidates : 0));
    json_object_object_add(o, "geo_policy_breakdown_supported",
                           json_object_new_boolean(s && s->available &&
                               s->geo_external_event_candidates > 0 &&
                               (access(WEBD_GEOIP_CITY_MMDB_DEFAULT, R_OK) == 0 ||
                                access(WEBD_GEOIP_COUNTRY_MMDB_DEFAULT, R_OK) == 0)));
    json_object_object_add(o, "geo_policy_event_regions_supported",
                           json_object_new_boolean(s && s->available &&
                               s->geo_external_event_candidates > 0 &&
                               (access(WEBD_GEOIP_CITY_MMDB_DEFAULT, R_OK) == 0 ||
                                access(WEBD_GEOIP_COUNTRY_MMDB_DEFAULT, R_OK) == 0)));
    json_object_object_add(o, "client_attribution_supported", json_object_new_boolean(1));
    json_object_object_add(o, "client_attributed", json_object_new_int(s ? s->client_attributed : 0));
    json_object_object_add(o, "client_unattributed", json_object_new_int(s ? s->client_unattributed : 0));
    json_object_object_add(o, "reason", json_object_new_string(s ? s->reason : "not_loaded"));
    json_object_object_add(o, "source", json_object_new_string("aegis_events"));
    json_object_object_add(o, "policy_scope", json_object_new_string(webd_insights_policy_scope_from_stats(s)));
    json_object_object_add(o, "policy_type_breakdown", webd_insights_aegis_policy_type_breakdown_json(s));
    json_object_object_add(o, "full_policy_supported", json_object_new_boolean(0));
    json_object_object_add(o, "dns_filter_policy_hit_supported", json_object_new_boolean(s && s->policy_dns_filter > 0));
    json_object_object_add(o, "reputation_ip_policy_hit_supported", json_object_new_boolean(s && s->policy_reputation_ip > 0));
    json_object_object_add(o, "ids_ips_policy_hit_supported", json_object_new_boolean(s && s->policy_ids_ips > 0));
    json_object_object_add(o, "policy_route_hit_supported", json_object_new_boolean(s && s->policy_route > 0));
    json_object_object_add(o, "risk_breakdown", webd_insights_aegis_risk_breakdown_json(s));
    json_object_object_add(o, "action_breakdown", webd_insights_aegis_action_breakdown_json(s));
    json_object_object_add(o, "policy_breakdown",
        webd_insights_aegis_groups_to_array(s ? s->policies : NULL, s ? s->policy_count : 0, top, "policy"));
    json_object_object_add(o, "top_destinations",
        webd_insights_aegis_groups_to_array(s ? s->destinations : NULL, s ? s->destination_count : 0, top, "destination"));
    json_object_object_add(o, "top_clients",
        webd_insights_aegis_groups_to_array(s ? s->clients : NULL, s ? s->client_count : 0, top, "client"));
    return o;
}

static int webd_insights_aegis_geo_event_candidates(const struct webd_insights_query *q,
                                                    int *limited_out)
{
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;
    int64_t ts_from = q ? q->ts_from : 0;
    int64_t ts_to = q ? q->ts_to : now_s();
    int limit = q && q->top > 0 ? q->top * 50 : 2000;
    int count = 0;
    int scanned = 0;

    if (limited_out)
        *limited_out = 0;
    if (ts_to <= 0)
        ts_to = now_s();
    if (ts_from <= 0)
        ts_from = ts_to - webd_insights_period_seconds(q ? q->period : "day");
    if (limit < 500)
        limit = 500;
    if (limit > 5000)
        limit = 5000;
    if (access(WEBD_AEGIS_DB_PATH, R_OK) != 0)
        return 0;
    if (sqlite3_open_v2(WEBD_AEGIS_DB_PATH, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK || !db) {
        if (db)
            sqlite3_close(db);
        return 0;
    }
    sqlite3_busy_timeout(db, 50);
    if (!webd_insights_sqlite_table_exists(db, "aegis_events")) {
        sqlite3_close(db);
        return 0;
    }
    if (sqlite3_prepare_v2(db,
            "SELECT event_type,level,action,policy_id,policy_name,policy_type,"
            "risk,risk_category,source_ip,source_mac,source_port,destination_ip,destination_host,"
            "destination_port,protocol,app_id,app_name,in_interface,out_interface,reason,source "
            "FROM aegis_events WHERE ts>=?1 AND ts<=?2 "
            "AND COALESCE(destination_ip,'')<>'' "
            "ORDER BY ts DESC,id DESC LIMIT ?3",
            -1, &st, NULL) != SQLITE_OK) {
        sqlite3_close(db);
        return 0;
    }
    sqlite3_bind_int64(st, 1, ts_from);
    sqlite3_bind_int64(st, 2, ts_to);
    sqlite3_bind_int(st, 3, limit + 1);
    while (sqlite3_step(st) == SQLITE_ROW) {
        const char *event_type = (const char *)sqlite3_column_text(st, 0);
        const char *level = (const char *)sqlite3_column_text(st, 1);
        const char *action = (const char *)sqlite3_column_text(st, 2);
        const char *policy_id = (const char *)sqlite3_column_text(st, 3);
        const char *policy_name = (const char *)sqlite3_column_text(st, 4);
        const char *policy_type = (const char *)sqlite3_column_text(st, 5);
        const char *risk = (const char *)sqlite3_column_text(st, 6);
        const char *risk_category = (const char *)sqlite3_column_text(st, 7);
        const char *source_ip = (const char *)sqlite3_column_text(st, 8);
        const char *source_mac = (const char *)sqlite3_column_text(st, 9);
        int source_port = sqlite3_column_int(st, 10);
        const char *destination_ip = (const char *)sqlite3_column_text(st, 11);
        const char *destination_host = (const char *)sqlite3_column_text(st, 12);
        int destination_port = sqlite3_column_int(st, 13);
        const char *protocol = (const char *)sqlite3_column_text(st, 14);
        const char *app_id = (const char *)sqlite3_column_text(st, 15);
        const char *app_name = (const char *)sqlite3_column_text(st, 16);
        const char *in_interface = (const char *)sqlite3_column_text(st, 17);
        const char *out_interface = (const char *)sqlite3_column_text(st, 18);
        const char *reason = (const char *)sqlite3_column_text(st, 19);
        const char *source = (const char *)sqlite3_column_text(st, 20);

        scanned++;
        if (scanned > limit) {
            if (limited_out)
                *limited_out = 1;
            break;
        }
        if (webd_insights_ip_is_private_or_local(destination_ip ? destination_ip : ""))
            continue;
        if (!webd_insights_aegis_event_matches(q,
                event_type ? event_type : "", level ? level : "",
                action ? action : "", policy_id ? policy_id : "",
                policy_name ? policy_name : "", policy_type ? policy_type : "",
                risk ? risk : "", risk_category ? risk_category : "",
                source_ip ? source_ip : "", source_mac ? source_mac : "",
                source_port,
                destination_ip ? destination_ip : "",
                destination_host ? destination_host : "", destination_port,
                protocol ? protocol : "", app_id ? app_id : "",
                app_name ? app_name : "", in_interface ? in_interface : "",
                out_interface ? out_interface : "", reason ? reason : "",
                source ? source : ""))
            continue;
        count++;
    }
    sqlite3_finalize(st);
    sqlite3_close(db);
    return count;
}

static struct json_object *webd_insights_aegis_event_flow_item(const struct webd_insights_policy_hit *hit,
                                                               struct json_object *clients)
{
    struct json_object *item = json_object_new_object();
    struct json_object *src = json_object_new_object();
    struct webd_insights_policy_ctx pseudo_ctx = {0};
    struct json_object *client = NULL;
    char id[96];
    int has_tuple;
    int client_attributable;
    const char *client_name;
    const char *client_ip;
    const char *client_mac;

    if (!hit)
        return item;
    client_attributable = webd_insights_security_client_attributable(hit->source_ip,
                                                                     hit->source_mac);
    if (client_attributable)
        client = webd_insights_find_client_by_mac_or_ip(clients, hit->source_mac,
                                                        hit->source_ip);
    client_name = client ? webd_insights_client_name(client, hit->source_mac) :
        (client_attributable ? hit->source_ip : "");
    client_ip = client ? app_nc_json_str(client, "ip", hit->source_ip) :
        (client_attributable ? hit->source_ip : "");
    client_mac = client ? app_nc_json_str(client, "mac", hit->source_mac) : hit->source_mac;
    snprintf(id, sizeof(id), "aegis-event:%lld", (long long)hit->event_id);
    pseudo_ctx.schema_supported = 1;
    pseudo_ctx.event_count = 1;
    webd_obj_add_str(item, "id", id);
    json_object_object_add(item, "ts", json_object_new_int64(hit->ts));
    json_object_object_add(item, "timestamp", json_object_new_int64(hit->ts));
    webd_obj_add_str(item, "source", "aegis_events");
    webd_obj_add_str(item, "record_source", hit->source);
    webd_obj_add_str(item, "source_table", "aegis_events");
    webd_insights_policy_hit_add_meta_fields(item, hit);
    webd_obj_add_str(item, "event_type", hit->event_type);
    webd_obj_add_str(item, "level", hit->level);
    webd_obj_add_str(item, "flow_id", hit->flow_id);
    webd_obj_add_str(item, "risk", hit->risk[0] ? hit->risk : "unknown");
    webd_obj_add_str(item, "risk_level", hit->risk[0] ? hit->risk : "unknown");
    json_object_object_add(item, "risk_supported", json_object_new_boolean(1));
    json_object_object_add(item, "risk_matched",
                           json_object_new_boolean(hit->risk[0] && strcasecmp(hit->risk, "unknown")));
    webd_obj_add_str(item, "risk_source", "aegis_events");
    webd_obj_add_str(item, "risk_category", hit->risk_category);
    webd_obj_add_str(item, "risk_reason", hit->reason);
    webd_obj_add_str(item, "risk_annotation_source", "aegis_events");
    webd_obj_add_str(item, "action", hit->action);
    webd_obj_add_str(item, "action_source", "aegis_events");
    webd_obj_add_str(item, "direction", "unknown");
    webd_obj_add_str(item, "protocol", hit->protocol);
    webd_obj_add_str(item, "service", hit->destination_host[0] ? hit->destination_host : hit->protocol);
    webd_obj_add_str(item, "source_ip", hit->source_ip);
    webd_obj_add_str(item, "source_mac", hit->source_mac);
    json_object_object_add(item, "source_port", json_object_new_int(hit->source_port));
    webd_obj_add_str(item, "source_host", hit->source_ip);
    webd_insights_add_client_attribution(item, hit->source_ip, hit->source_mac);
    webd_obj_add_str(item, "destination_ip", hit->destination_ip);
    webd_obj_add_str(item, "destination_host", hit->destination_host);
    webd_obj_add_str(item, "host", hit->destination_host);
    json_object_object_add(item, "destination_port", json_object_new_int(hit->destination_port));
    webd_obj_add_str(item, "destination_region", "");
    webd_obj_add_str(item, "source_region", "");
    webd_obj_add_str(item, "in_interface", hit->in_interface);
    webd_obj_add_str(item, "out_interface", hit->out_interface);
    webd_obj_add_str(item, "in_network_id", "");
    webd_obj_add_str(item, "out_network_id", "");
    webd_obj_add_str(item, "app_id", hit->app_id);
    webd_obj_add_str(item, "appid", hit->app_id);
    webd_obj_add_str(item, "app_name", hit->app_name);
    webd_obj_add_str(item, "app_name_source", hit->app_name[0] ? "aegis_events" : "unavailable");
    webd_obj_add_str(item, "policy", hit->policy_name[0] ? hit->policy_name : hit->policy_id);
    webd_obj_add_str(item, "policy_id", hit->policy_id);
    webd_obj_add_str(item, "policy_name", hit->policy_name);
    webd_obj_add_str(item, "policy_type", hit->policy_type);
    webd_obj_add_str(item, "rule_id", hit->rule_id);
    webd_obj_add_str(item, "rule_name", hit->rule_name);
    json_object_object_add(item, "rx_bytes", json_object_new_int64(hit->rx_bytes));
    json_object_object_add(item, "tx_bytes", json_object_new_int64(hit->tx_bytes));
    json_object_object_add(item, "down_bytes", json_object_new_int64(hit->rx_bytes));
    json_object_object_add(item, "up_bytes", json_object_new_int64(hit->tx_bytes));
    json_object_object_add(item, "bytes", json_object_new_int64(hit->rx_bytes + hit->tx_bytes));
    json_object_object_add(item, "bytes_supported", json_object_new_boolean(hit->rx_bytes + hit->tx_bytes > 0));
    json_object_object_add(item, "connections", json_object_new_int(0));
    json_object_object_add(item, "hit_count", json_object_new_int(1));
    json_object_object_add(item, "flow_count", json_object_new_int(0));
    has_tuple = hit->source_ip[0] && hit->destination_ip[0] &&
                hit->source_port > 0 && hit->destination_port > 0 && hit->protocol[0];
    json_object_object_add(item, "five_tuple_supported", json_object_new_boolean(has_tuple));
    json_object_object_add(item, "five_tuple_exact", json_object_new_boolean(has_tuple));
    json_object_object_add(item, "historical_sample", json_object_new_boolean(0));
    json_object_object_add(item, "historical_lifecycle", json_object_new_boolean(0));
    json_object_object_add(item, "security_event_only", json_object_new_boolean(!hit->flow_id[0]));
    webd_obj_add_str(item, "flow_event_join",
                     hit->flow_id[0] ? "aegis_events.flow_id" : "aegis_event_row_not_conntrack_flow");
    webd_obj_add_str(src, "mac", client_mac);
    webd_obj_add_str(src, "ip", client_ip);
    webd_obj_add_str(src, "name", client_name);
    if (client) {
        webd_obj_add_str(src, "hostname", app_nc_json_str(client, "hostname", ""));
        webd_obj_add_str(src, "vendor_name", webd_first_nonempty4(
            app_nc_json_str(client, "vendor_name", ""),
            app_nc_json_str(client, "vendor", ""),
            "", ""));
        webd_obj_add_str(src, "device_type", webd_first_nonempty4(
            app_nc_json_str(client, "device_type", ""),
            app_nc_json_str(client, "type", ""),
            "", ""));
        webd_obj_add_str(src, "model", app_nc_json_str(client, "model", ""));
        if (json_object_object_get(client, "image"))
            json_object_object_add(src, "icon", json_object_get(json_object_object_get(client, "image")));
        webd_obj_add_str(src, "identity_source", "clients_inventory");
    }
    json_object_object_add(src, "identity_valid", json_object_new_boolean(client_attributable));
    webd_insights_add_client_attribution(src, hit->source_ip, hit->source_mac);
    json_object_object_add(item, "source_client", src);
    {
        struct webd_insights_policy_hit overlay = *hit;

        snprintf(overlay.precision, sizeof(overlay.precision), "%s", "aegis_event_row");
        webd_insights_apply_policy_hit_overlay(item, &pseudo_ctx, &overlay);
    }
    return item;
}

static int webd_insights_append_aegis_event_items(const struct webd_insights_query *q,
                                                  struct webd_insights_policy_ctx *ctx,
                                                  struct json_object *clients,
                                                  struct json_object *items,
                                                  int max_emit,
                                                  int *total_out)
{
    sqlite3_stmt *st = NULL;
    sqlite3_stmt *count_st = NULL;
    char where[8192];
    char sql[12288];
    int64_t from = q ? q->ts_from : 0;
    int64_t to = q ? q->ts_to : now_s();
    int total = 0;
    int emitted = 0;
    int scanned = 0;
    int postprocess_required = 0;
    int limit = 2000;
    int page_number = q && q->page_number > 0 ? q->page_number : 1;
    int page_size = q && q->page_size > 0 ? q->page_size : (max_emit > 0 ? max_emit : 50);
    int offset = (page_number - 1) * (page_size > 0 ? page_size : 50);
    int matched_seen = 0;

    if (total_out)
        *total_out = 0;
    if (!items || !json_object_is_type(items, json_type_array) ||
        !webd_insights_policy_available(ctx))
        return 0;
    if (to <= 0)
        to = now_s();
    if (from <= 0)
        from = to - webd_insights_period_seconds(q ? q->period : "day");
    webd_insights_policy_build_where(q, where, sizeof(where), &postprocess_required);
    ctx->last_query_exact = !postprocess_required;
    ctx->last_query_limit = limit;
    snprintf(sql, sizeof(sql), "SELECT COUNT(*) FROM aegis_events %s", where);
    if (sqlite3_prepare_v2(ctx->db, sql, -1, &count_st, NULL) == SQLITE_OK) {
        sqlite3_bind_int64(count_st, 1, from);
        sqlite3_bind_int64(count_st, 2, to);
        if (sqlite3_step(count_st) == SQLITE_ROW)
            total = sqlite3_column_int(count_st, 0);
    } else {
        ctx->last_query_exact = 0;
    }
    if (count_st)
        sqlite3_finalize(count_st);
    snprintf(sql, sizeof(sql), "%s%s ORDER BY ts DESC,id DESC LIMIT ?3",
             webd_insights_policy_select_sql(), where);
    if (sqlite3_prepare_v2(ctx->db, sql, -1, &st, NULL) != SQLITE_OK) {
        snprintf(ctx->error, sizeof(ctx->error), "aegis_events_items_prepare_failed:%s",
                 sqlite3_errmsg(ctx->db));
        return 0;
    }
    sqlite3_bind_int64(st, 1, from);
    sqlite3_bind_int64(st, 2, to);
    sqlite3_bind_int(st, 3, limit);
    while (sqlite3_step(st) == SQLITE_ROW) {
        struct webd_insights_policy_hit hit;

        scanned++;
        webd_insights_policy_hit_from_row(st, &hit, ctx, "aegis_event_row");
        if (!webd_insights_aegis_event_matches(q,
                hit.event_type, hit.level, hit.action, hit.policy_id,
                hit.policy_name, hit.policy_type, hit.risk, hit.risk_category,
                hit.source_ip, hit.source_mac, hit.source_port,
                hit.destination_ip, hit.destination_host, hit.destination_port,
                hit.protocol, hit.app_id, hit.app_name, hit.in_interface,
                hit.out_interface, hit.reason, hit.source))
            continue;
        matched_seen++;
        if (!ctx->last_query_exact)
            total++;
        if (matched_seen <= offset)
            continue;
        if (emitted < max_emit) {
            json_object_array_add(items, webd_insights_aegis_event_flow_item(&hit, clients));
            emitted++;
        }
    }
    sqlite3_finalize(st);
    if (!ctx->last_query_exact && scanned >= limit)
        snprintf(ctx->error, sizeof(ctx->error), "%s", "aegis_events_postprocess_limit_reached");
    if (total_out)
        *total_out = total;
    return emitted;
}

static int webd_insights_app_lookup(int app_id,
                                    char *name, size_t name_len,
                                    char *category, size_t category_len,
                                    char *family, size_t family_len,
                                    int *canonical_app_id)
{
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;
    time_t now = time(NULL);
    char sig_path[512];
    char source_error[64];
    enum jmx_system_db_source db_source;
    int i, found = 0;
    int canon = app_id;

    if (name && name_len)
        name[0] = '\0';
    if (category && category_len)
        category[0] = '\0';
    if (family && family_len)
        family[0] = '\0';
    if (canonical_app_id)
        *canonical_app_id = app_id;
    if (app_id <= 0)
        return 0;
    for (i = 0; i < WEBD_INSIGHTS_APP_CACHE_MAX; i++) {
        struct webd_insights_app_cache_entry *e = &g_webd_insights_app_cache[i];

        if (e->app_id != app_id || now - e->ts > WEBD_INSIGHTS_APP_CACHE_TTL_S)
            continue;
        if (name && name_len)
            snprintf(name, name_len, "%s", e->name);
        if (category && category_len)
            snprintf(category, category_len, "%s", e->category);
        if (family && family_len)
            snprintf(family, family_len, "%s", e->family);
        if (canonical_app_id)
            *canonical_app_id = e->canonical_app_id;
        return e->found;
    }
    if (webd_system_db_open(JMX_SYSTEM_DB_SIGNATURE, &db,
                            sig_path, sizeof(sig_path), &db_source,
                            source_error, sizeof(source_error)) != 0)
        goto out;
    sqlite3_busy_timeout(db, 50);
    if (sqlite3_prepare_v2(db,
            "SELECT a.app_id,a.name,COALESCE(c.name,''),COALESCE(a.family,'') "
            "FROM app a LEFT JOIN app_category c ON a.category_id=c.category_id "
            "WHERE a.app_id=?1 LIMIT 1",
            -1, &st, NULL) == SQLITE_OK) {
        sqlite3_bind_int(st, 1, app_id);
        if (sqlite3_step(st) == SQLITE_ROW) {
            canon = sqlite3_column_int(st, 0);
            if (name && name_len)
                snprintf(name, name_len, "%s", sqlite3_column_text(st, 1) ? (const char *)sqlite3_column_text(st, 1) : "");
            if (category && category_len)
                snprintf(category, category_len, "%s", sqlite3_column_text(st, 2) ? (const char *)sqlite3_column_text(st, 2) : "");
            if (family && family_len)
                snprintf(family, family_len, "%s", sqlite3_column_text(st, 3) ? (const char *)sqlite3_column_text(st, 3) : "");
            found = name && name[0];
        }
    }
    if (st)
        sqlite3_finalize(st);
    st = NULL;
    if (!found && sqlite3_prepare_v2(db,
            "SELECT a.app_id,a.name,COALESCE(c.name,''),COALESCE(a.family,'') "
            "FROM app_id_map m JOIN app a ON a.app_id=m.app_id "
            "LEFT JOIN app_category c ON a.category_id=c.category_id "
            "WHERE m.source_app_id=?1 ORDER BY m.confidence DESC LIMIT 1",
            -1, &st, NULL) == SQLITE_OK) {
        char idbuf[32];

        snprintf(idbuf, sizeof(idbuf), "%d", app_id);
        sqlite3_bind_text(st, 1, idbuf, -1, SQLITE_TRANSIENT);
        if (sqlite3_step(st) == SQLITE_ROW) {
            canon = sqlite3_column_int(st, 0);
            if (name && name_len)
                snprintf(name, name_len, "%s", sqlite3_column_text(st, 1) ? (const char *)sqlite3_column_text(st, 1) : "");
            if (category && category_len)
                snprintf(category, category_len, "%s", sqlite3_column_text(st, 2) ? (const char *)sqlite3_column_text(st, 2) : "");
            if (family && family_len)
                snprintf(family, family_len, "%s", sqlite3_column_text(st, 3) ? (const char *)sqlite3_column_text(st, 3) : "");
            found = name && name[0];
        }
    }
out:
    if (st)
        sqlite3_finalize(st);
    if (db)
        sqlite3_close(db);
    {
        struct webd_insights_app_cache_entry *e =
            &g_webd_insights_app_cache[g_webd_insights_app_cache_cursor++ % WEBD_INSIGHTS_APP_CACHE_MAX];

        memset(e, 0, sizeof(*e));
        e->app_id = app_id;
        e->found = found;
        e->canonical_app_id = canon;
        e->ts = now;
        if (name && name_len)
            snprintf(e->name, sizeof(e->name), "%s", name);
        if (category && category_len)
            snprintf(e->category, sizeof(e->category), "%s", category);
        if (family && family_len)
            snprintf(e->family, sizeof(e->family), "%s", family);
    }
    if (canonical_app_id)
        *canonical_app_id = canon;
    return found;
}

static void webd_insights_read_query(const struct http_req *req, struct json_object *body,
                                     struct webd_insights_query *q)
{
    char buf[128];
    int64_t now = now_s();

    memset(q, 0, sizeof(*q));
    snprintf(q->period, sizeof(q->period), "%s", app_nc_json_str(body, "period", "day"));
    snprintf(q->map_scope, sizeof(q->map_scope), "%s",
             webd_first_nonempty4(app_nc_json_str(body, "map_scope", ""),
                                  app_nc_json_str(body, "geo_scope", ""),
                                  app_nc_json_str(body, "scope", ""),
                                  "world"));
    if (req && webd_query_get(req->query, "period", buf, sizeof(buf)))
        snprintf(q->period, sizeof(q->period), "%s", buf);
    if (req && webd_query_get(req->query, "map_scope", buf, sizeof(buf)))
        snprintf(q->map_scope, sizeof(q->map_scope), "%s", buf);
    else if (req && webd_query_get(req->query, "geo_scope", buf, sizeof(buf)))
        snprintf(q->map_scope, sizeof(q->map_scope), "%s", buf);
    else if (req && webd_query_get(req->query, "scope", buf, sizeof(buf)))
        snprintf(q->map_scope, sizeof(q->map_scope), "%s", buf);
    if (!q->map_scope[0])
        snprintf(q->map_scope, sizeof(q->map_scope), "%s", "world");

    q->page_number = app_nc_json_int(body, "pageNumber", app_nc_json_int(body, "page_number", 1));
    q->page_size = app_nc_json_int(body, "pageSize", app_nc_json_int(body, "page_size", 50));
    q->top = app_nc_json_int(body, "top", 30);
    if (req && webd_query_get(req->query, "pageNumber", buf, sizeof(buf)))
        q->page_number = atoi(buf);
    if (req && webd_query_get(req->query, "pageSize", buf, sizeof(buf)))
        q->page_size = atoi(buf);
    if (req && webd_query_get(req->query, "top", buf, sizeof(buf)))
        q->top = atoi(buf);
    if (q->page_number <= 0)
        q->page_number = 1;
    if (q->page_size <= 0)
        q->page_size = 50;
    if (q->page_size > 500)
        q->page_size = 500;
    if (q->top <= 0)
        q->top = 30;
    if (q->top > 100)
        q->top = 100;

    webd_insights_filter_read_body(q, body);
    webd_insights_filter_read_query_string(q, req);

    snprintf(q->search, sizeof(q->search), "%s", app_nc_json_str(body, "search_text", ""));
    snprintf(q->risk, sizeof(q->risk), "%s", webd_insights_filter_first(q, 0, "risk"));
    snprintf(q->action, sizeof(q->action), "%s", webd_insights_filter_first(q, 0, "action"));
    snprintf(q->direction, sizeof(q->direction), "%s", webd_insights_filter_first(q, 0, "direction"));
    snprintf(q->protocol, sizeof(q->protocol), "%s", webd_insights_filter_first(q, 0, "protocol"));
    snprintf(q->mode, sizeof(q->mode), "%s", app_nc_json_str(body, "mode", ""));
    if (!q->mode[0])
        snprintf(q->mode, sizeof(q->mode), "%s",
                 app_nc_json_str(body, "flow_mode",
                     app_nc_json_str(body, "source_mode", "")));
    snprintf(q->dataset, sizeof(q->dataset), "%s", webd_first_nonempty4(
        app_nc_json_str(body, "dataset", ""),
        app_nc_json_str(body, "source_dataset", ""),
        app_nc_json_str(body, "data_source", ""), ""));
    q->security_only = app_nc_json_bool(body, "security_only",
        app_nc_json_bool(body, "securityOnly",
        app_nc_json_bool(body, "cybersecure_only", 0)));
    if (webd_insights_dataset_is_security(q->dataset) ||
        webd_insights_dataset_is_security(q->mode))
        q->security_only = 1;
    snprintf(q->source_mac, sizeof(q->source_mac), "%s", webd_insights_filter_first(q, 0, "source_mac"));
    snprintf(q->source_ip, sizeof(q->source_ip), "%s", webd_insights_filter_first(q, 0, "source_ip"));
    snprintf(q->destination_host, sizeof(q->destination_host), "%s", webd_insights_filter_first(q, 0, "destination_host"));
    snprintf(q->destination_ip, sizeof(q->destination_ip), "%s", webd_insights_filter_first(q, 0, "destination_ip"));
    snprintf(q->service, sizeof(q->service), "%s", webd_insights_filter_first(q, 0, "service"));

    if (req) {
        if (webd_query_get(req->query, "search_text", buf, sizeof(buf)))
            snprintf(q->search, sizeof(q->search), "%s", buf);
        if (webd_query_get(req->query, "risk", buf, sizeof(buf)))
            snprintf(q->risk, sizeof(q->risk), "%s", buf);
        if (webd_query_get(req->query, "action", buf, sizeof(buf)))
            snprintf(q->action, sizeof(q->action), "%s", buf);
        if (webd_query_get(req->query, "direction", buf, sizeof(buf)))
            snprintf(q->direction, sizeof(q->direction), "%s", buf);
        if (webd_query_get(req->query, "protocol", buf, sizeof(buf)))
            snprintf(q->protocol, sizeof(q->protocol), "%s", buf);
        if (webd_query_get(req->query, "mode", buf, sizeof(buf))) {
            snprintf(q->mode, sizeof(q->mode), "%s", buf);
            if (webd_insights_dataset_is_security(buf))
                q->security_only = 1;
        }
        if (!q->mode[0] &&
            (webd_query_get(req->query, "flow_mode", buf, sizeof(buf)) ||
             webd_query_get(req->query, "source_mode", buf, sizeof(buf)))) {
            snprintf(q->mode, sizeof(q->mode), "%s", buf);
            if (webd_insights_dataset_is_security(buf))
                q->security_only = 1;
        }
        if (webd_query_get(req->query, "dataset", buf, sizeof(buf)) ||
            webd_query_get(req->query, "source_dataset", buf, sizeof(buf)) ||
            webd_query_get(req->query, "data_source", buf, sizeof(buf))) {
            snprintf(q->dataset, sizeof(q->dataset), "%s", buf);
            if (webd_insights_dataset_is_security(buf))
                q->security_only = 1;
        }
        if (webd_query_get(req->query, "security_only", buf, sizeof(buf)) ||
            webd_query_get(req->query, "securityOnly", buf, sizeof(buf)) ||
            webd_query_get(req->query, "cybersecure_only", buf, sizeof(buf)))
            q->security_only = webd_insights_truthy(buf, q->security_only);
        if (webd_query_get(req->query, "source_mac", buf, sizeof(buf)))
            snprintf(q->source_mac, sizeof(q->source_mac), "%s", buf);
        if (webd_query_get(req->query, "source_ip", buf, sizeof(buf)))
            snprintf(q->source_ip, sizeof(q->source_ip), "%s", buf);
        if (webd_query_get(req->query, "destination_host", buf, sizeof(buf)))
            snprintf(q->destination_host, sizeof(q->destination_host), "%s", buf);
        if (webd_query_get(req->query, "destination_ip", buf, sizeof(buf)))
            snprintf(q->destination_ip, sizeof(q->destination_ip), "%s", buf);
        if (webd_query_get(req->query, "service", buf, sizeof(buf)))
            snprintf(q->service, sizeof(q->service), "%s", buf);
    }

    q->ts_from = webd_insights_ts_normalize(app_nc_json_int64(body, "timestampFrom",
        app_nc_json_int64(body, "ts_from", 0)));
    q->ts_to = webd_insights_ts_normalize(app_nc_json_int64(body, "timestampTo",
        app_nc_json_int64(body, "ts_to", 0)));
    if (req && webd_query_get(req->query, "timestampFrom", buf, sizeof(buf)))
        q->ts_from = webd_insights_ts_normalize(atoll(buf));
    if (req && webd_query_get(req->query, "timestampTo", buf, sizeof(buf)))
        q->ts_to = webd_insights_ts_normalize(atoll(buf));
    if (req && webd_query_get(req->query, "ts_from", buf, sizeof(buf)))
        q->ts_from = webd_insights_ts_normalize(atoll(buf));
    if (req && webd_query_get(req->query, "ts_to", buf, sizeof(buf)))
        q->ts_to = webd_insights_ts_normalize(atoll(buf));
    if (q->ts_to <= 0)
        q->ts_to = now;
    if (q->ts_from <= 0)
        q->ts_from = q->ts_to - webd_insights_period_seconds(q->period);
    if (q->ts_from > q->ts_to) {
        int64_t t = q->ts_from;
        q->ts_from = q->ts_to;
        q->ts_to = t;
    }
}

static struct json_object *webd_insights_capabilities(void)
{
    struct json_object *cap = json_object_new_object();
    webd_mmdb_t *mmdb = NULL;
    char city_error[96] = "";
    char country_error[96] = "";
    static time_t geo_cache_ts = 0;
    static int geoip_country_mmdb_present = 0;
    static int geoip_city_mmdb_present = 0;
    static int geo_lookup_available = 0;
    static int geo_city_lookup_available = 0;
    static char geo_lookup_error[96] = "";
    struct webd_insights_event_lifecycle_status event_lifecycle;
    time_t now = time(NULL);

    webd_insights_event_lifecycle_status_init(&event_lifecycle);
    if (geo_cache_ts == 0 || now - geo_cache_ts > 30) {
        geo_cache_ts = now;
        geoip_country_mmdb_present = access(WEBD_GEOIP_COUNTRY_MMDB_DEFAULT, R_OK) == 0;
        geoip_city_mmdb_present = access(WEBD_GEOIP_CITY_MMDB_DEFAULT, R_OK) == 0;
        geo_lookup_available = 0;
        geo_city_lookup_available = 0;
        geo_lookup_error[0] = '\0';
        if (webd_mmdb_open(WEBD_GEOIP_CITY_MMDB_DEFAULT, &mmdb,
                           city_error, sizeof(city_error)) == 0) {
            geo_lookup_available = 1;
            geo_city_lookup_available = 1;
            webd_mmdb_close(mmdb);
            mmdb = NULL;
        } else if (webd_mmdb_open(WEBD_GEOIP_COUNTRY_MMDB_DEFAULT, &mmdb,
                                  country_error, sizeof(country_error)) == 0) {
            geo_lookup_available = 1;
            webd_mmdb_close(mmdb);
            mmdb = NULL;
        }
        snprintf(geo_lookup_error, sizeof(geo_lookup_error), "%s",
                 city_error[0] ? city_error : country_error);
    }

    json_object_object_add(cap, "audit_urls", json_object_new_boolean(1));
    json_object_object_add(cap, "client_join", json_object_new_boolean(1));
    json_object_object_add(cap, "current_topology_flow", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_current_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_current_exact", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_historical_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_historical_observed_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_historical_full_capture_supported", json_object_new_boolean(0));
    json_object_object_add(cap, "historical_sample_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "historical_lifecycle_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "historical_lifecycle_sampled", json_object_new_boolean(1));
    json_object_object_add(cap, "five_tuple_historical_exact", json_object_new_boolean(0));
    json_object_object_add(cap, "historical_lifecycle_exact", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "flow_lifecycle_exact_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "conntrack_event_lifecycle_supported", json_object_new_boolean(event_lifecycle.supported));
    json_object_object_add(cap, "conntrack_event_lifecycle_enabled", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "conntrack_event_lifecycle_reason", json_object_new_string(event_lifecycle.reason));
    json_object_object_add(cap, "event_lifecycle_rest_mode_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_query_mode", json_object_new_string("mode=event_lifecycle"));
    json_object_object_add(cap, "event_lifecycle_bff_enrichment_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "event_lifecycle_client_overlay_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "event_lifecycle_geo_overlay_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "event_lifecycle_service_hint_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "event_lifecycle_policy_overlay_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "event_lifecycle_query_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_history_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_signature_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_app_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_host_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_geo_backfill_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "event_lifecycle_nat_tuple_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "dnat_local_termination_supported", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "nat_tuple_source", json_object_new_string("ctnetlink_original_reply_tuple"));
    json_object_object_add(cap, "flow_accounting_source", json_object_new_string(event_lifecycle.enabled ? "ctnetlink_destroy_available" : "nf_conntrack_polling_sample"));
    json_object_object_add(cap, "accounting_source", json_object_new_string(event_lifecycle.enabled ? "ctnetlink_destroy_available" : "nf_conntrack_polling_sample"));
    json_object_object_add(cap, "byte_accounting_source", json_object_new_string(event_lifecycle.enabled ? "ctnetlink_destroy_counters_available" : "sampled_conntrack_counters"));
    json_object_object_add(cap, "byte_accounting_exact", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "exact_window_bytes", json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "netfilter_allow_observed_supported",
                           json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "netfilter_allow_policy_accounting_supported",
                           json_object_new_boolean(0));
    json_object_object_add(cap, "verified_allow_lifecycle_supported",
                           json_object_new_boolean(event_lifecycle.enabled));
    json_object_object_add(cap, "verified_allow_policy_hit_supported",
                           json_object_new_boolean(0));
    json_object_object_add(cap, "lifecycle_semantics", json_object_new_string(event_lifecycle.enabled ?
        "default REST rows remain enriched/sampled; request mode=event_lifecycle for compressed ctnetlink DESTROY lifecycle rows" :
        "sampled conntrack polling lifecycle; ctnetlink DESTROY lifecycle source is not available"));
    webd_insights_add_event_lifecycle_status(cap, &event_lifecycle);
    json_object_object_add(cap, "filter_exclude_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "include_exclude_filters_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "filter_multi_select_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "filter_include_then_exclude", json_object_new_boolean(1));
    json_object_object_add(cap, "security_only_filter_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "security_event_dataset_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "test_event_filter_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "manual_ingest_filter_supported", json_object_new_boolean(1));
    {
        struct json_object *datasets = json_object_new_array();
        json_object_array_add(datasets, json_object_new_string("flows"));
        json_object_array_add(datasets, json_object_new_string("aegis_events"));
        json_object_array_add(datasets, json_object_new_string("security"));
        json_object_object_add(cap, "supported_datasets", datasets);
    }
    {
        int aegis_reputation_items = webd_insights_aegis_count_cached("aegis_reputation_items");
        int aegis_domain_categories = webd_insights_aegis_count_cached("aegis_domain_categories");
        int risk_supported = aegis_reputation_items > 0 || aegis_domain_categories > 0;
        int aegis_events_schema = 0;
        int aegis_events = webd_insights_aegis_events_count_cached(&aegis_events_schema);
        int policy_hit_supported = aegis_events_schema && aegis_events > 0;
        char policy_scope[64] = "unavailable";
        struct json_object *policy_type_breakdown = NULL;
        int dns_filter_events = 0;
        int reputation_ip_events = 0;
        int ids_ips_events = 0;
        int policy_route_events = 0;
        int other_policy_events = 0;

        webd_insights_aegis_policy_type_counts_cached(policy_scope, sizeof(policy_scope),
            &policy_type_breakdown, &dns_filter_events, &reputation_ip_events,
            &ids_ips_events, &policy_route_events, &other_policy_events);

        json_object_object_add(cap, "risk_supported", json_object_new_boolean(risk_supported));
        json_object_object_add(cap, "risk_source_available", json_object_new_boolean(risk_supported));
        json_object_object_add(cap, "risk_source", json_object_new_string(risk_supported ? "aegis_reputation" : "unavailable"));
        json_object_object_add(cap, "aegis_reputation_items", json_object_new_int(aegis_reputation_items));
        json_object_object_add(cap, "aegis_domain_categories", json_object_new_int(aegis_domain_categories));
        json_object_object_add(cap, "aegis_events_supported", json_object_new_boolean(aegis_events_schema));
        json_object_object_add(cap, "aegis_events", json_object_new_int(aegis_events));
        json_object_object_add(cap, "client_attribution_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "dns_filter_client_attribution_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "dns_filter_client_mac_lookup_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "dns_filter_client_interface_lookup_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "dns_filter_client_identity_source",
                               json_object_new_string("aegisxd.dnsmasq_query_source_ip+neighbor_cache"));
        json_object_object_add(cap, "policy_hit_supported", json_object_new_boolean(policy_hit_supported));
        json_object_object_add(cap, "dns_filter_policy_hit_supported", json_object_new_boolean(dns_filter_events > 0));
        json_object_object_add(cap, "reputation_ip_policy_hit_supported", json_object_new_boolean(reputation_ip_events > 0));
        json_object_object_add(cap, "reputation_ip_per_flow_hit_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "reputation_ip_per_flow_precision",
                               json_object_new_string("conntrack_flow_snapshot"));
        json_object_object_add(cap, "reputation_ip_drop_confirmed_supported", json_object_new_boolean(1));
        json_object_object_add(cap, "reputation_ip_drop_confirmed_source", json_object_new_string("nft_counter_delta"));
        json_object_object_add(cap, "ids_ips_policy_hit_supported", json_object_new_boolean(ids_ips_events > 0));
        json_object_object_add(cap, "policy_route_hit_supported", json_object_new_boolean(policy_route_events > 0));
        json_object_object_add(cap, "policy_supported", json_object_new_boolean(policy_hit_supported));
        json_object_object_add(cap, "policy_scope", json_object_new_string(policy_hit_supported ? policy_scope : "unavailable"));
        json_object_object_add(cap, "policy_type_breakdown", policy_type_breakdown ? policy_type_breakdown : json_object_new_object());
        json_object_object_add(cap, "full_policy_supported", json_object_new_boolean(0));
        json_object_object_add(cap, "dataplane_action_supported", json_object_new_boolean(policy_hit_supported));
        json_object_object_add(cap, "action_source", json_object_new_string(policy_hit_supported ? "aegis_events" : "audit_flow_sample_or_default_allow"));
    }
    json_object_object_add(cap, "geo_supported", json_object_new_boolean(geo_lookup_available));
    json_object_object_add(cap, "geoip_mmdb_present", json_object_new_boolean(
        geoip_country_mmdb_present || geoip_city_mmdb_present));
    json_object_object_add(cap, "geoip_country_mmdb_present", json_object_new_boolean(geoip_country_mmdb_present));
    json_object_object_add(cap, "geoip_city_mmdb_present", json_object_new_boolean(geoip_city_mmdb_present));
    json_object_object_add(cap, "geo_lookup_available", json_object_new_boolean(geo_lookup_available));
    json_object_object_add(cap, "geo_city_lookup_available", json_object_new_boolean(geo_city_lookup_available));
    json_object_object_add(cap, "city_geo_supported", json_object_new_boolean(geo_city_lookup_available));
    json_object_object_add(cap, "geo_lookup_error", json_object_new_string(geo_lookup_error));
    json_object_object_add(cap, "historical_geo_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "bytes_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "historical_bytes_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "current_bytes_supported", json_object_new_boolean(1));
    json_object_object_add(cap, "source", json_object_new_string("audit_urls+clients+topology_flow+audit_flow_sample+audit_flow_lifecycle"));
    return cap;
}

static struct json_object *webd_insights_ubus_data_timeout(const char *method,
                                                           struct json_object *params,
                                                           int timeout_ms)
{
    struct json_object *upstream = app_ubus_invoke_timeout(method, params, timeout_ms);
    struct json_object *data = webd_data_or_self_from_jmx_response(upstream);

    if (upstream)
        json_object_put(upstream);
    return data;
}

static struct json_object *webd_insights_ubus_data(const char *method, struct json_object *params)
{
    return webd_insights_ubus_data_timeout(method, params, 1500);
}

static struct json_object *webd_insights_fetch_audit_urls(const struct webd_insights_query *q,
                                                          int limit)
{
    struct json_object *params = json_object_new_object();
    struct json_object *data;
    struct json_object *urls = NULL;

    if (limit <= 0)
        limit = 1000;
    if (limit > 1000)
        limit = 1000;
    json_object_object_add(params, "limit", json_object_new_int(limit));
    if (q) {
        json_object_object_add(params, "pageNumber", json_object_new_int(q->page_number));
        json_object_object_add(params, "pageSize", json_object_new_int(limit));
        if (q->search[0])
            json_object_object_add(params, "search_text", json_object_new_string(q->search));
        if (q->source_mac[0])
            json_object_object_add(params, "source_mac", json_object_new_string(q->source_mac));
        if (q->source_ip[0])
            json_object_object_add(params, "source_ip", json_object_new_string(q->source_ip));
        if (q->destination_host[0])
            json_object_object_add(params, "destination_host", json_object_new_string(q->destination_host));
        if (q->service[0])
            json_object_object_add(params, "service", json_object_new_string(q->service));
        if (q->action[0] && strcasecmp(q->action, "all") &&
            (strcasecmp(q->action, "allow") == 0 || strcasecmp(q->action, "allowed") == 0 ||
             strcasecmp(q->action, "block") == 0 || strcasecmp(q->action, "blocked") == 0))
            json_object_object_add(params, "action", json_object_new_string(q->action));
        webd_insights_params_add_filter_array(params, q, "app_id");
        webd_insights_params_add_filter_array(params, q, "appid");
        webd_insights_params_add_filter_array(params, q, "service");
        webd_insights_params_add_filter_array(params, q, "destination_host");
        webd_insights_params_add_filter_array(params, q, "source_mac");
        webd_insights_params_add_filter_array(params, q, "source_ip");
        webd_insights_params_add_filter_array(params, q, "action");
        webd_insights_params_add_filter_array(params, q, "destination_ip");
        webd_insights_params_add_filter_array(params, q, "source_region");
        webd_insights_params_add_filter_array(params, q, "destination_region");
        webd_insights_params_add_filter_array(params, q, "host");
        webd_insights_params_add_filter_array(params, q, "remote_ip");
        webd_insights_params_add_filter_array(params, q, "protocol");
        webd_insights_params_add_filter_array(params, q, "direction");
        webd_insights_params_add_filter_array(params, q, "source_port");
        webd_insights_params_add_filter_array(params, q, "destination_port");
        webd_insights_params_add_filter_array(params, q, "app");
        webd_insights_params_add_filter_array(params, q, "application");
        webd_insights_params_add_filter_array(params, q, "source_network_id");
        webd_insights_params_add_filter_array(params, q, "in_network_id");
        webd_insights_params_add_filter_array(params, q, "in_interface");
        webd_insights_params_add_filter_array(params, q, "destination_network_id");
        webd_insights_params_add_filter_array(params, q, "out_network_id");
        webd_insights_params_add_filter_array(params, q, "out_interface");
        webd_insights_params_add_filter_array(params, q, "wan_id");
        webd_insights_params_add_filter_array(params, q, "wan_ifname");
    }
    json_object_object_add(params, "ts_from", json_object_new_int64(q ? q->ts_from : 0));
    json_object_object_add(params, "ts_to", json_object_new_int64(q ? q->ts_to : now_s()));
    data = webd_insights_ubus_data("audit_urls", params);
    json_object_put(params);
    if (!data)
        return NULL;
    if (!json_object_object_get_ex(data, "urls", &urls) || !urls ||
        !json_object_is_type(urls, json_type_array)) {
        json_object_put(data);
        return NULL;
    }
    return data;
}

static struct json_object *webd_insights_fetch_clients(void)
{
    struct json_object *data = webd_insights_ubus_data("clients", NULL);
    struct json_object *clients = NULL;

    if (!data)
        return NULL;
    if (!json_object_object_get_ex(data, "clients", &clients) || !clients ||
        !json_object_is_type(clients, json_type_array)) {
        json_object_put(data);
        return NULL;
    }
    clients = json_object_get(clients);
    json_object_put(data);
    return clients;
}

