static struct json_object *webd_insights_fetch_history_flows_limit(const struct webd_insights_query *q,
                                                                   int limit)
{
    struct webd_insights_query tmp;

    memset(&tmp, 0, sizeof(tmp));
    if (q)
        tmp = *q;
    else {
        snprintf(tmp.period, sizeof(tmp.period), "hour");
        tmp.page_number = 1;
        tmp.ts_to = now_s();
        tmp.ts_from = tmp.ts_to - 3600;
    }
    if (limit <= 0)
        limit = 200;
    if (limit > 500)
        limit = 500;
    tmp.page_number = 1;
    tmp.page_size = limit;
    return webd_insights_fetch_history_flows(&tmp);
}

static struct json_object *webd_insights_find_client(struct json_object *clients,
                                                     const char *mac)
{
    int i, n;

    if (!clients || !mac || !mac[0] || !json_object_is_type(clients, json_type_array))
        return NULL;
    n = (int)json_object_array_length(clients);
    for (i = 0; i < n; i++) {
        struct json_object *c = json_object_array_get_idx(clients, i);
        const char *cmac = app_nc_json_str(c, "mac", "");

        if (cmac[0] && !strcasecmp(cmac, mac))
            return c;
    }
    return NULL;
}

static struct json_object *webd_insights_find_client_by_mac_or_ip(struct json_object *clients,
                                                                  const char *mac,
                                                                  const char *ip)
{
    int i, n;

    if (!clients || !json_object_is_type(clients, json_type_array))
        return NULL;
    if (mac && mac[0]) {
        struct json_object *c = webd_insights_find_client(clients, mac);

        if (c)
            return c;
    }
    if (!ip || !ip[0])
        return NULL;
    n = (int)json_object_array_length(clients);
    for (i = 0; i < n; i++) {
        struct json_object *c = json_object_array_get_idx(clients, i);
        const char *cip = app_nc_json_str(c, "ip", "");

        if (cip[0] && !strcmp(cip, ip))
            return c;
    }
    return NULL;
}

static void webd_insights_enrich_flow_top_clients(struct json_object *arr,
                                                  struct json_object *clients)
{
    int i, n;

    if (!arr || !clients || !json_object_is_type(arr, json_type_array))
        return;
    n = (int)json_object_array_length(arr);
    for (i = 0; i < n; i++) {
        struct json_object *o = json_object_array_get_idx(arr, i);
        const char *mac = app_nc_json_str(o, "mac", app_nc_json_str(o, "source_mac", ""));
        const char *ip = app_nc_json_str(o, "ip", app_nc_json_str(o, "source_ip", ""));
        struct json_object *client = webd_insights_find_client_by_mac_or_ip(clients, mac, ip);
        const char *name;

        if (!client)
            continue;
        name = webd_insights_client_name(client, mac);
        if (name && name[0]) {
            webd_obj_add_str(o, "name", name);
            webd_obj_add_str(o, "display_name", name);
            webd_obj_add_str(o, "client_name", name);
        }
        webd_obj_add_str(o, "hostname", app_nc_json_str(client, "hostname", ""));
        webd_obj_add_str(o, "vendor_name", webd_first_nonempty4(
            app_nc_json_str(client, "vendor_name", ""),
            app_nc_json_str(client, "vendor", ""),
            "", ""));
        webd_obj_add_str(o, "device_type", webd_first_nonempty4(
            app_nc_json_str(client, "device_type", ""),
            app_nc_json_str(client, "type", ""),
            "", ""));
        webd_obj_add_str(o, "model", app_nc_json_str(client, "model", ""));
        webd_obj_add_str(o, "model_source", app_nc_json_str(client, "model_source", ""));
        webd_obj_add_str(o, "fingerprint_source", app_nc_json_str(webd_obj_child(client, "fingerprint"), "source", ""));
        if (json_object_object_get(client, "image"))
            json_object_object_add(o, "icon", json_object_get(json_object_object_get(client, "image")));
        webd_obj_add_str(o, "identity_source", "clients_inventory");
    }
}

static void webd_insights_apply_risk_to_top_item(struct json_object *o,
                                                 const struct webd_insights_risk_annotation *ann,
                                                 int64_t count)
{
    struct json_object *risk = json_object_new_object();
    const char *r = ann && ann->risk[0] ? ann->risk : "unknown";
    int matched = ann && ann->matched;
    int64_t affected = matched ? count : 0;
    int64_t unknown = matched ? 0 : count;
    int64_t low = 0;
    int64_t suspicious = 0;
    int64_t concerning = 0;
    int64_t high = 0;

    if (!o)
        return;
    if (count <= 0)
        count = 1;
    if (matched) {
        if (!strcasecmp(r, "low"))
            low = count;
        else if (!strcasecmp(r, "suspicious"))
            suspicious = count;
        else if (!strcasecmp(r, "concerning"))
            concerning = count;
        else if (!strcasecmp(r, "high") || !strcasecmp(r, "critical"))
            high = count;
        else
            unknown = count;
    }
    json_object_object_add(o, "risk_supported", json_object_new_boolean(ann && ann->supported));
    json_object_object_add(o, "risk_matched", json_object_new_boolean(matched));
    json_object_object_add(o, "affected", json_object_new_boolean(matched));
    json_object_object_add(o, "affected_count", json_object_new_int64(affected));
    webd_obj_add_str(o, "risk", matched ? r : "unknown");
    webd_obj_add_str(o, "risk_level", matched && ann && ann->level[0] ? ann->level : "unknown");
    webd_obj_add_str(o, "risk_source", ann && ann->source[0] ? ann->source : "unavailable");
    webd_obj_add_str(o, "risk_category", ann && ann->category[0] ? ann->category : "");
    webd_obj_add_str(o, "risk_feed", ann && ann->feed[0] ? ann->feed : "");
    webd_obj_add_str(o, "risk_matched_domain", ann && ann->matched_domain[0] ? ann->matched_domain : "");
    webd_obj_add_str(o, "risk_reason", ann && ann->reason[0] ? ann->reason : "no_reputation_match");
    json_object_object_add(o, "risk_severity", json_object_new_int(ann ? ann->severity : 0));
    json_object_object_add(o, "risk_confidence", json_object_new_int(ann ? ann->confidence : 0));
    webd_obj_add_str(o, "risk_annotation_source", ann && ann->supported ? "webd.aegis_reputation_overlay" : "unavailable");
    webd_obj_add_str(o, "risk_scope", "cybersecure_reputation_if_matched");
    json_object_object_add(risk, "unknown", json_object_new_int64(unknown));
    json_object_object_add(risk, "low", json_object_new_int64(low));
    json_object_object_add(risk, "suspicious", json_object_new_int64(suspicious));
    json_object_object_add(risk, "concerning", json_object_new_int64(concerning));
    json_object_object_add(risk, "high", json_object_new_int64(high));
    json_object_object_add(o, "risk_breakdown", risk);
}

static int webd_insights_string_has_alpha(const char *s)
{
    if (!s)
        return 0;
    for (; *s; s++) {
        if (isalpha((unsigned char)*s))
            return 1;
    }
    return 0;
}

static void webd_insights_enrich_flow_top_destinations(struct json_object *arr,
                                                       struct webd_insights_risk_ctx *risk_ctx)
{
    int i, n;

    if (!arr || !json_object_is_type(arr, json_type_array))
        return;
    n = (int)json_object_array_length(arr);
    for (i = 0; i < n; i++) {
        struct json_object *o = json_object_array_get_idx(arr, i);
        struct webd_insights_risk_annotation ann;
        const char *candidate;
        const char *key;
        int64_t count;

        if (!o || !json_object_is_type(o, json_type_object))
            continue;
        candidate = webd_first_nonempty4(app_nc_json_str(o, "destination_host", ""),
                                         app_nc_json_str(o, "host", ""),
                                         "", "");
        key = webd_first_nonempty4(app_nc_json_str(o, "key", ""),
                                   app_nc_json_str(o, "id", ""),
                                   app_nc_json_str(o, "name", ""),
                                   "");
        if (!candidate[0] && webd_insights_string_has_alpha(key))
            candidate = key;
        count = app_nc_json_int64(o, "count",
                app_nc_json_int64(o, "flow_count",
                app_nc_json_int64(o, "hit_count",
                app_nc_json_int64(o, "sample_count", 1))));
        webd_insights_risk_lookup(risk_ctx, candidate, &ann);
        webd_insights_apply_risk_to_top_item(o, &ann, count);
    }
}

static int webd_insights_mac_valid(const char *mac)
{
    char norm[32];

    return webd_normalize_mac_text(mac, norm, sizeof(norm)) == 0;
}

static int webd_insights_ip_is_loopback_or_unspecified(const char *ip)
{
    struct in_addr a4;
    struct in6_addr a6;
    unsigned int v;

    if (!ip || !ip[0])
        return 0;
    if (inet_pton(AF_INET, ip, &a4) == 1) {
        v = ntohl(a4.s_addr);
        return (v >> 24) == 127 || v == 0;
    }
    if (inet_pton(AF_INET6, ip, &a6) == 1)
        return IN6_IS_ADDR_LOOPBACK(&a6) || IN6_IS_ADDR_UNSPECIFIED(&a6);
    return 0;
}

static int webd_insights_security_client_attributable(const char *source_ip,
                                                      const char *source_mac)
{
    if (webd_insights_mac_valid(source_mac))
        return 1;
    if (!source_ip || !source_ip[0])
        return 0;
    return !webd_insights_ip_is_loopback_or_unspecified(source_ip);
}

static void webd_insights_add_client_attribution(struct json_object *obj,
                                                 const char *source_ip,
                                                 const char *source_mac)
{
    int attributable = webd_insights_security_client_attributable(source_ip, source_mac);
    const char *reason = "";

    if (!attributable) {
        if (source_ip && source_ip[0] &&
            webd_insights_ip_is_loopback_or_unspecified(source_ip))
            reason = "local_resolver_source";
        else if (!source_ip || !source_ip[0])
            reason = "source_ip_missing";
        else
            reason = "client_identity_missing";
    }
    json_object_object_add(obj, "client_attribution", json_object_new_boolean(attributable));
    json_object_object_add(obj, "client_attribution_supported", json_object_new_boolean(1));
    webd_obj_add_str(obj, "client_attribution_reason", reason);
}

static struct json_object *webd_insights_find_flow_for_mac(struct json_object *topology_flow,
                                                           const char *mac)
{
    struct json_object *flows = webd_obj_child_array(topology_flow, "flows");
    int i, n;

    if (!flows || !mac || !mac[0])
        return NULL;
    n = (int)json_object_array_length(flows);
    for (i = 0; i < n; i++) {
        struct json_object *f = json_object_array_get_idx(flows, i);
        const char *fmac = app_nc_json_str(f, "client_mac", "");

        if (fmac[0] && !strcasecmp(fmac, mac))
            return f;
    }
    return NULL;
}

static struct json_object *webd_insights_current_flow_samples(struct json_object *current_flows,
                                                              const char *mac,
                                                              int limit)
{
    struct json_object *samples = json_object_new_array();
    struct json_object *items = webd_obj_child_array(current_flows, "items");
    int i, n, emitted = 0;

    if (!items || !mac || !mac[0] || limit <= 0)
        return samples;
    n = (int)json_object_array_length(items);
    for (i = 0; i < n && emitted < limit; i++) {
        struct json_object *f = json_object_array_get_idx(items, i);
        const char *fmac = webd_first_nonempty4(
            app_nc_json_str(f, "client_mac", ""),
            app_nc_json_str(f, "source_mac", ""),
            "", "");

        if (fmac[0] && strcasecmp(fmac, mac))
            continue;
        json_object_array_add(samples, json_object_get(f));
        emitted++;
    }
    return samples;
}

static int webd_insights_sample_pick_first(struct json_object *samples,
                                           struct json_object **out)
{
    if (out)
        *out = NULL;
    if (!samples || !json_object_is_type(samples, json_type_array) ||
        json_object_array_length(samples) <= 0)
        return 0;
    if (out)
        *out = json_object_array_get_idx(samples, 0);
    return 1;
}

static const char *webd_insights_client_name(struct json_object *client, const char *mac)
{
    return webd_first_nonempty4(
        app_nc_json_str(client, "name", ""),
        app_nc_json_str(client, "display_name", ""),
        app_nc_json_str(client, "hostname", ""),
        mac ? mac : "");
}

static void webd_insights_add_source_client(struct json_object *item,
                                            struct json_object *client,
                                            const char *mac)
{
    struct json_object *src = json_object_new_object();
    const char *name = webd_insights_client_name(client, mac);
    const char *ip = app_nc_json_str(client, "ip", "");
    int mac_valid = webd_insights_mac_valid(mac);

    webd_obj_add_str(src, "mac", mac_valid ? mac : "");
    webd_obj_add_str(src, "name", mac_valid ? name : "");
    webd_obj_add_str(src, "ip", ip);
    webd_obj_add_str(src, "hostname", app_nc_json_str(client, "hostname", ""));
    webd_obj_add_str(src, "vendor_name", webd_first_nonempty4(
        app_nc_json_str(client, "vendor_name", ""),
        app_nc_json_str(client, "vendor", ""),
        "", ""));
    webd_obj_add_str(src, "device_type", webd_first_nonempty4(
        app_nc_json_str(client, "device_type", ""),
        app_nc_json_str(client, "type", ""),
        "", ""));
    if (client && json_object_object_get(client, "image"))
        json_object_object_add(src, "icon", json_object_get(json_object_object_get(client, "image")));
    json_object_object_add(src, "identity_valid", json_object_new_boolean(mac_valid));
    if (!mac_valid)
        json_object_object_add(src, "reason", json_object_new_string("invalid_mac_in_audit_url_event"));
    json_object_object_add(item, "source_client", src);
}

static int webd_insights_url_matches(const struct webd_insights_query *q,
                                     struct json_object *url,
                                     struct json_object *client,
                                     struct json_object *flow)
{
    const char *mac = app_nc_json_str(url, "mac", "");
    const char *host = webd_first_nonempty4(
        app_nc_json_str(url, "host", ""),
        app_nc_json_str(url, "sni", ""),
        app_nc_json_str(url, "uri", ""),
        "");
    const char *ip = app_nc_json_str(client, "ip", "");
    const char *url_ip = app_nc_json_str(url, "ip", "");
    const char *url_action = app_nc_json_str(url, "action", "allow");
    const char *name = webd_insights_client_name(client, mac);
    const char *client_network = app_nc_json_str(client, "network", "");
    const char *client_interface = app_nc_json_str(client, "interface", "");
    const char *wan_id = app_nc_json_str(flow, "wan_id", "");
    const char *wan_ifname = app_nc_json_str(flow, "wan_ifname", "");
    const char *flow_direction = app_nc_json_str(flow, "direction", "unknown");
    const char *flow_protocol = app_nc_json_str(flow, "protocol",
        app_nc_json_str(flow, "proto", "unknown"));
    const char *flow_service = app_nc_json_str(flow, "service", "");
    const char *flow_dst_ip = webd_first_nonempty4(
        app_nc_json_str(flow, "destination_ip", ""),
        app_nc_json_str(flow, "remote_ip", ""),
        app_nc_json_str(flow, "dst", ""),
        "");
    char app_id_buf[32];
    char source_port_buf[32];
    char destination_port_buf[32];
    char haystack[1024];
    int64_t ts = app_nc_json_int64(url, "ts", 0);

    if (!q)
        return 1;
    snprintf(app_id_buf, sizeof(app_id_buf), "%d",
             app_nc_json_int(url, "appid", app_nc_json_int(url, "app_id", 0)));
    snprintf(source_port_buf, sizeof(source_port_buf), "%d",
             app_nc_json_int(flow, "source_port", 0));
    snprintf(destination_port_buf, sizeof(destination_port_buf), "%d",
             app_nc_json_int(flow, "destination_port", 0));
    if (ts > 0 && (ts < q->ts_from || ts > q->ts_to))
        return 0;
    if (q->search[0]) {
        snprintf(haystack, sizeof(haystack), "%s %s %s %s %s %s %d",
                 mac, ip, url_ip, name, host, app_nc_json_str(url, "app_name", ""),
                 app_nc_json_int(url, "appid", 0));
        if (!webd_str_contains_i(haystack, q->search))
            return 0;
    }
    {
        const char *source_values[] = { name, mac, ip, url_ip };
        const char *source_ip_values[] = { ip, url_ip };
        const char *host_values[] = { host };
        const char *dest_ip_values[] = { flow_dst_ip };
        const char *service_values[] = { host, flow_service, app_nc_json_str(url, "app_name", "") };
        const char *app_values[] = { app_id_buf, app_nc_json_str(url, "app_name", ""), flow_service, host };
        const char *network_values[] = { client_network };
        const char *out_values[] = { wan_id, wan_ifname };
        const char *interface_values[] = { client_interface };
        const char *action_values[] = { url_action };
        const char *direction_values[] = { flow_direction[0] ? flow_direction : "unknown" };
        const char *protocol_values[] = { flow_protocol[0] ? flow_protocol : "unknown" };
        const char *source_port_values[] = { source_port_buf };
        const char *destination_port_values[] = { destination_port_buf };
        const char *app_id_values[] = { app_id_buf };
        const char *empty_values[] = { "" };

        if (!webd_insights_filter_apply_field(q, "source_host", source_values, 4, 1))
            return 0;
        if (!webd_insights_filter_apply_field(q, "source_mac", source_values, 4, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "source_ip", source_ip_values, 2, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "destination_host", host_values, 1, 1))
            return 0;
        if (!webd_insights_filter_apply_field(q, "destination_ip", dest_ip_values, 1, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "service", service_values, 3, 1))
            return 0;
        if (!webd_insights_filter_apply_field(q, "app", app_values, 4, 1) ||
            !webd_insights_filter_apply_field(q, "application", app_values, 4, 1) ||
            !webd_insights_filter_apply_field(q, "app_id", app_id_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "appid", app_id_values, 1, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "action", action_values, 1, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "direction", direction_values, 1, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "protocol", protocol_values, 1, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "source_network_id", network_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "in_network_id", network_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "destination_network_id", out_values, 2, 0) ||
            !webd_insights_filter_apply_field(q, "out_network_id", out_values, 2, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "in_interface", interface_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "out_interface", out_values, 2, 0) ||
            !webd_insights_filter_apply_field(q, "wan_id", out_values, 2, 0) ||
            !webd_insights_filter_apply_field(q, "wan_ifname", out_values, 2, 0))
            return 0;
        if (!webd_insights_filter_apply_field(q, "source_port", source_port_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "destination_port", destination_port_values, 1, 0))
            return 0;
        if (!webd_insights_geo_region_filter_matches(q, "source_region", ip[0] ? ip : url_ip) ||
            !webd_insights_geo_region_filter_matches(q, "destination_region", flow_dst_ip) ||
            !webd_insights_filter_apply_field(q, "destination_mac", empty_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "policy", empty_values, 1, 0) ||
            !webd_insights_filter_apply_field(q, "policy_type", empty_values, 1, 0))
            return 0;
    }
    return 1;
}

static struct json_object *webd_insights_flow_item(struct json_object *url,
                                                   struct json_object *client,
                                                   struct json_object *flow,
                                                   struct json_object *current_flow_samples,
                                                   const struct webd_insights_risk_annotation *risk,
                                                   struct webd_insights_policy_ctx *policy_ctx)
{
    const char *mac = app_nc_json_str(url, "mac", "");
    const char *host = webd_first_nonempty4(
        app_nc_json_str(url, "host", ""),
        app_nc_json_str(url, "sni", ""),
        app_nc_json_str(url, "uri", ""),
        "");
    const char *client_ip = webd_first_nonempty4(
        app_nc_json_str(client, "ip", ""),
        app_nc_json_str(url, "ip", ""),
        app_nc_json_str(flow, "client_ip", ""),
        "");
    int appid = app_nc_json_int(url, "appid", app_nc_json_int(url, "app_id", 0));
    int64_t ts = app_nc_json_int64(url, "ts", 0);
    int hit_count = app_nc_json_int(url, "hit_count", 1);
    int64_t up_bytes = app_nc_json_int64(url, "up_bytes", 0);
    int64_t down_bytes = app_nc_json_int64(url, "down_bytes", 0);
    const char *app_name = app_nc_json_str(url, "app_name", "");
    const char *app_name_source = app_nc_json_str(url, "app_name_source", "");
    const char *action = app_nc_json_str(url, "action", "allow");
    struct json_object *sample = NULL;
    int has_sample = webd_insights_sample_pick_first(current_flow_samples, &sample);
    char sig_app_name[128] = "";
    char sig_app_category[96] = "";
    char sig_app_family[64] = "";
    int canonical_appid = appid;
    int sig_app_found = 0;
    int app_name_unresolved = (!app_name || !app_name[0]) ||
                              !strcasecmp(app_name_source, "unresolved_app_id") ||
                              !strcasecmp(app_name_source, "app_id_only");
    struct webd_insights_policy_hit policy_hit;
    char id[512];
    struct json_object *item = json_object_new_object();

    if (appid > 0)
        sig_app_found = webd_insights_app_lookup(appid, sig_app_name, sizeof(sig_app_name),
                                                 sig_app_category, sizeof(sig_app_category),
                                                 sig_app_family, sizeof(sig_app_family),
                                                 &canonical_appid);
    snprintf(id, sizeof(id), "audit-url:%lld:%s:%d:%s:%s",
             (long long)ts, mac, appid, host, app_nc_json_str(url, "path", ""));
    webd_obj_add_str(item, "id", id);
    json_object_object_add(item, "ts", json_object_new_int64(ts));
    json_object_object_add(item, "timestamp", json_object_new_int64(ts));
    webd_obj_add_str(item, "source", "audit_urls");
    webd_obj_add_str(item, "risk", risk && risk->risk[0] ? risk->risk : "unknown");
    webd_obj_add_str(item, "risk_level", risk && risk->level[0] ? risk->level : "unknown");
    json_object_object_add(item, "risk_supported", json_object_new_boolean(risk && risk->supported));
    json_object_object_add(item, "risk_matched", json_object_new_boolean(risk && risk->matched));
    webd_obj_add_str(item, "risk_source", risk && risk->source[0] ? risk->source : "unavailable");
    webd_obj_add_str(item, "risk_category", risk && risk->category[0] ? risk->category : "");
    webd_obj_add_str(item, "risk_feed", risk && risk->feed[0] ? risk->feed : "");
    webd_obj_add_str(item, "risk_matched_domain", risk && risk->matched_domain[0] ? risk->matched_domain : "");
    webd_obj_add_str(item, "risk_reason", risk && risk->reason[0] ? risk->reason : "no_reputation_match");
    json_object_object_add(item, "risk_severity", json_object_new_int(risk ? risk->severity : 0));
    json_object_object_add(item, "risk_confidence", json_object_new_int(risk ? risk->confidence : 0));
    json_object_object_add(item, "risk_overlay_supported", json_object_new_boolean(risk && risk->supported));
    json_object_object_add(item, "risk_overlay_matched", json_object_new_boolean(risk && risk->matched));
    webd_obj_add_str(item, "risk_annotation_source",
                     risk && risk->supported ? "webd.aegis_reputation_overlay" : "unavailable");
    webd_obj_add_str(item, "action", action && action[0] ? action : "allow");
    webd_obj_add_str(item, "action_source", "no_block_policy_source");
    webd_obj_add_str(item, "direction", has_sample ? app_nc_json_str(sample, "direction", "unknown") : "unknown");
    webd_obj_add_str(item, "protocol", has_sample ? app_nc_json_str(sample, "protocol", "unknown") : "unknown");
    webd_obj_add_str(item, "service", host[0] ? host : (has_sample ? app_nc_json_str(sample, "service", "") : ""));
    json_object_object_add(item, "app_id", json_object_new_int(appid));
    json_object_object_add(item, "appid", json_object_new_int(appid));
    json_object_object_add(item, "canonical_app_id", json_object_new_int(canonical_appid));
    webd_obj_add_str(item, "app_name", (!app_name_unresolved && app_name && app_name[0]) ? app_name : sig_app_name);
    webd_obj_add_str(item, "app_name_source", (!app_name_unresolved && app_name_source[0]) ? app_name_source : (sig_app_found ? "signature_db" : (appid > 0 ? "app_id_only" : "unavailable")));
    webd_obj_add_str(item, "app_category", sig_app_category);
    webd_obj_add_str(item, "app_family", sig_app_family);
    webd_obj_add_str(item, "source_mac", mac);
    webd_obj_add_str(item, "source_ip", client_ip);
    webd_obj_add_str(item, "source_host", webd_insights_client_name(client, mac));
    webd_obj_add_str(item, "destination_host", host);
    webd_obj_add_str(item, "destination_ip", has_sample ? app_nc_json_str(sample, "destination_ip", "") : "");
    json_object_object_add(item, "destination_port", json_object_new_int(has_sample ? app_nc_json_int(sample, "destination_port", 0) : 0));
    json_object_object_add(item, "source_port", json_object_new_int(has_sample ? app_nc_json_int(sample, "source_port", 0) : 0));
    webd_obj_add_str(item, "destination_region", "");
    webd_obj_add_str(item, "source_region", "");
    webd_obj_add_str(item, "in_network_id", webd_first_nonempty4(
        app_nc_json_str(flow, "in_network_id", ""),
        app_nc_json_str(flow, "source_network_id", ""),
        app_nc_json_str(client, "network", ""), ""));
    webd_obj_add_str(item, "out_network_id", webd_first_nonempty4(
        app_nc_json_str(flow, "out_network_id", ""),
        app_nc_json_str(flow, "destination_network_id", ""),
        app_nc_json_str(flow, "wan_id", ""), ""));
    webd_obj_add_str(item, "in_interface", webd_first_nonempty4(
        app_nc_json_str(flow, "in_interface", ""),
        app_nc_json_str(flow, "interface", ""),
        app_nc_json_str(client, "interface", ""), ""));
    webd_obj_add_str(item, "out_interface", webd_first_nonempty4(
        app_nc_json_str(flow, "out_interface", ""),
        app_nc_json_str(flow, "wan_ifname", ""), "", ""));
    webd_obj_add_str(item, "policy", "");
    webd_obj_add_str(item, "policy_type", "");
    json_object_object_add(item, "policy_supported", json_object_new_boolean(0));
    json_object_object_add(item, "policy_hit_supported", json_object_new_boolean(0));
    json_object_object_add(item, "dataplane_action_supported", json_object_new_boolean(0));
    webd_insights_policy_lookup(policy_ctx, ts, "",
                                client_ip, mac,
                                has_sample ? app_nc_json_int(sample, "source_port", 0) : 0,
                                has_sample ? app_nc_json_str(sample, "destination_ip", "") : "",
                                host,
                                has_sample ? app_nc_json_int(sample, "destination_port", 0) : 0,
                                has_sample ? app_nc_json_str(sample, "protocol",
                                    app_nc_json_str(sample, "proto", "")) : "",
                                &policy_hit);
    webd_insights_apply_policy_hit_overlay(item, policy_ctx, &policy_hit);
    json_object_object_add(item, "rx_bytes", json_object_new_int64(down_bytes > 0 ? down_bytes : (has_sample ? app_nc_json_int64(sample, "rx_bytes", 0) : 0)));
    json_object_object_add(item, "tx_bytes", json_object_new_int64(up_bytes > 0 ? up_bytes : (has_sample ? app_nc_json_int64(sample, "tx_bytes", 0) : 0)));
    json_object_object_add(item, "up_bytes", json_object_new_int64(up_bytes > 0 ? up_bytes : (has_sample ? app_nc_json_int64(sample, "tx_bytes", 0) : 0)));
    json_object_object_add(item, "down_bytes", json_object_new_int64(down_bytes > 0 ? down_bytes : (has_sample ? app_nc_json_int64(sample, "rx_bytes", 0) : 0)));
    json_object_object_add(item, "up_rate", json_object_new_int64(app_nc_json_int64(flow, "up_rate", 0)));
    json_object_object_add(item, "down_rate", json_object_new_int64(app_nc_json_int64(flow, "down_rate", 0)));
    json_object_object_add(item, "connections", json_object_new_int(app_nc_json_int(flow, "connections", 0)));
    json_object_object_add(item, "hit_count", json_object_new_int(hit_count > 0 ? hit_count : 1));
    json_object_object_add(item, "bytes_supported", json_object_new_boolean(up_bytes > 0 || down_bytes > 0 || has_sample));
    webd_insights_enrich_geo_fields(item,
                                    has_sample ? app_nc_json_str(sample, "destination_ip", "") : "",
                                    client_ip,
                                    NULL, NULL);
    webd_insights_add_flow_lifecycle(item, has_sample ? sample : flow, 0);
    json_object_object_add(item, "five_tuple_supported", json_object_new_boolean(has_sample));
    json_object_object_add(item, "five_tuple_exact", json_object_new_boolean(0));
    json_object_object_add(item, "five_tuple_join", json_object_new_string(has_sample ? "same_client_current_sample" : "unavailable"));
    json_object_object_add(item, "historical_join_supported", json_object_new_boolean(0));
    if (current_flow_samples)
        json_object_object_add(item, "current_connection_samples", json_object_get(current_flow_samples));
    webd_insights_add_source_client(item, client, mac);
    webd_insights_add_trust_contract(item);
    return item;
}


static int webd_insights_lookup_pbr_rule_by_priority(int priority,
                                                     char *rule_id, size_t rule_id_len,
                                                     char *rule_name, size_t rule_name_len,
                                                     char *action, size_t action_len,
                                                     char *target, size_t target_len,
                                                     int *enabled)
{
    sqlite3 *db = NULL;
    sqlite3_stmt *st = NULL;
    int found = 0;

    if (rule_id && rule_id_len) rule_id[0] = '\0';
    if (rule_name && rule_name_len) rule_name[0] = '\0';
    if (action && action_len) action[0] = '\0';
    if (target && target_len) target[0] = '\0';
    if (enabled) *enabled = 0;
    if (priority <= 0)
        return 0;
    if (sqlite3_open_v2(APP_CONFIG_DB_PATH, &db, SQLITE_OPEN_READONLY, NULL) != SQLITE_OK || !db) {
        if (db)
            sqlite3_close(db);
        return 0;
    }
    sqlite3_busy_timeout(db, 120);
    if (sqlite3_prepare_v2(db,
        "SELECT id,name,enabled,action,target,route_table "
        "FROM policy_route_rule WHERE priority=?1 "
        "ORDER BY enabled DESC,updated_at DESC,id LIMIT 1",
        -1, &st, NULL) == SQLITE_OK) {
        sqlite3_bind_int(st, 1, priority);
        if (sqlite3_step(st) == SQLITE_ROW) {
            const char *id = (const char *)sqlite3_column_text(st, 0);
            const char *name = (const char *)sqlite3_column_text(st, 1);
            const char *act = (const char *)sqlite3_column_text(st, 3);
            const char *tgt = (const char *)sqlite3_column_text(st, 5);

            if (!tgt || !tgt[0])
                tgt = (const char *)sqlite3_column_text(st, 4);
            if (rule_id && rule_id_len)
                snprintf(rule_id, rule_id_len, "%s", id ? id : "");
            if (rule_name && rule_name_len)
                snprintf(rule_name, rule_name_len, "%s", (name && name[0]) ? name : (id ? id : ""));
            if (action && action_len)
                snprintf(action, action_len, "%s", act ? act : "");
            if (target && target_len)
                snprintf(target, target_len, "%s", tgt ? tgt : "");
            if (enabled)
                *enabled = sqlite3_column_int(st, 2) != 0;
            found = 1;
        }
    }
    if (st)
        sqlite3_finalize(st);
    sqlite3_close(db);
    return found;
}

static int webd_insights_apply_flow_policy_attribution(struct json_object *item,
                                                       struct json_object *flow)
{
    const char *policy_id;
    const char *policy_name;
    const char *policy_type;
    const char *policy_action;
    const char *policy_source;
    const char *route_wan;
    char mapped_policy_id[128] = "";
    char mapped_policy_name[160] = "";
    char mapped_policy_action[64] = "";
    char mapped_route_wan[96] = "";
    int mapped_enabled = 0;
    int mapped = 0;
    int route_rule_prio;
    int route_wan_id;
    int policy_hit;

    if (!item || !flow || !json_object_is_type(item, json_type_object) ||
        !json_object_is_type(flow, json_type_object))
        return 0;

    policy_hit = app_nc_json_bool(flow, "policy_hit", 0);
    route_rule_prio = app_nc_json_int(flow, "route_rule_prio", 0);
    route_wan_id = app_nc_json_int(flow, "route_wan_id", 0);
    if (!policy_hit && route_rule_prio <= 0 && route_wan_id <= 0 &&
        app_nc_json_int64(flow, "policy_mark", 0) == 0)
        return 0;

    policy_id = app_nc_json_str(flow, "policy_id", "");
    policy_name = app_nc_json_str(flow, "policy_name", policy_id);
    policy_type = app_nc_json_str(flow, "policy_type", "pbr");
    policy_action = app_nc_json_str(flow, "policy_action",
        app_nc_json_str(flow, "action", "route"));
    policy_source = app_nc_json_str(flow, "policy_source", "ctnetlink_conntrack_mark");
    route_wan = app_nc_json_str(flow, "route_wan", "");
    mapped = webd_insights_lookup_pbr_rule_by_priority(route_rule_prio,
                                                       mapped_policy_id, sizeof(mapped_policy_id),
                                                       mapped_policy_name, sizeof(mapped_policy_name),
                                                       mapped_policy_action, sizeof(mapped_policy_action),
                                                       mapped_route_wan, sizeof(mapped_route_wan),
                                                       &mapped_enabled);
    if (mapped) {
        if (mapped_policy_id[0])
            policy_id = mapped_policy_id;
        if (mapped_policy_name[0])
            policy_name = mapped_policy_name;
        if (mapped_policy_action[0])
            policy_action = mapped_policy_action;
        if (mapped_route_wan[0])
            route_wan = mapped_route_wan;
    }

    json_object_object_add(item, "policy_supported", json_object_new_boolean(1));
    json_object_object_add(item, "policy_hit", json_object_new_boolean(policy_hit || route_rule_prio > 0));
    json_object_object_add(item, "policy_hit_supported", json_object_new_boolean(1));
    json_object_object_add(item, "policy_route_per_flow_attribution_supported", json_object_new_boolean(1));
    json_object_object_add(item, "policy_event_matched", json_object_new_boolean(1));
    json_object_object_add(item, "policy_match_exact", json_object_new_boolean(1));
    json_object_object_add(item, "policy_engine_supported", json_object_new_boolean(1));
    json_object_object_add(item, "policy_dataplane_accounting_supported", json_object_new_boolean(1));
    json_object_object_add(item, "policy_runtime_apply_supported", json_object_new_boolean(1));
    webd_obj_add_str(item, "policy_scope", "policy_route");
    webd_obj_add_str(item, "policy_match_precision", "ctnetlink_conntrack_mark");
    webd_obj_add_str(item, "policy_source", policy_source[0] ? policy_source : "ctnetlink_conntrack_mark");
    webd_obj_add_str(item, "policy_reason", "matched_conntrack_policy_route_mark");
    webd_obj_add_str(item, "policy_attribution_source", "ctnetlink_conntrack_mark");
    json_object_object_add(item, "policy_config_overlay", json_object_new_boolean(mapped));
    webd_obj_add_str(item, "policy_config_overlay_source", mapped ? "config.db:policy_route_rule" : "not_found");
    json_object_object_add(item, "policy_config_overlay_enabled", json_object_new_boolean(mapped && mapped_enabled));
    json_object_object_add(item, "policy_current_config_priority_match", json_object_new_boolean(mapped));
    json_object_object_add(item, "policy_config_overlay_stale_possible", json_object_new_boolean(1));
    if (!mapped && route_rule_prio > 0)
        webd_obj_add_str(item, "policy_config_overlay_reason", "priority_not_found_current_config_or_rule_deleted");
    webd_obj_add_str(item, "policy", policy_name && policy_name[0] ? policy_name : policy_id);
    webd_obj_add_str(item, "policy_id", policy_id);
    webd_obj_add_str(item, "policy_name", policy_name && policy_name[0] ? policy_name : policy_id);
    webd_obj_add_str(item, "policy_type", policy_type && policy_type[0] ? policy_type : "pbr");
    webd_obj_add_str(item, "policy_action", policy_action && policy_action[0] ? policy_action : "route");
    webd_obj_add_str(item, "action", policy_action && policy_action[0] ? policy_action : "route");
    webd_obj_add_str(item, "action_source", app_nc_json_str(flow, "action_source", "ctnetlink_conntrack_mark"));
    webd_obj_add_str(item, "action_semantic",
                     app_nc_json_str(flow, "action_semantic", "verified_policy_route_hit"));
    json_object_object_add(item, "policy_action_verified", json_object_new_boolean(1));
    json_object_object_add(item, "dataplane_action_supported", json_object_new_boolean(1));
    json_object_object_add(item, "netfilter_allow_observed", json_object_new_boolean(1));
    json_object_object_add(item, "netfilter_allow_policy_accounting", json_object_new_boolean(1));
    webd_obj_add_str(item, "netfilter_allow_accounting_source", "ctnetlink_conntrack_mark");
    webd_obj_add_str(item, "netfilter_allow_accounting_semantics",
                     "completed conntrack lifecycle carries verified policy-route rule mark");
    json_object_object_add(item, "policy_mark",
                           json_object_new_int64(app_nc_json_int64(flow, "policy_mark", 0)));
    json_object_object_add(item, "route_rule_prio", json_object_new_int(route_rule_prio));
    json_object_object_add(item, "route_wan_id", json_object_new_int(route_wan_id));
    webd_obj_add_str(item, "route_wan", route_wan);
    return 1;
}

static struct json_object *webd_insights_history_flow_item(struct json_object *flow,
                                                           struct json_object *clients,
                                                           struct webd_insights_risk_ctx *risk_ctx,
                                                           struct webd_insights_policy_ctx *policy_ctx)
{
    const char *mac = webd_first_nonempty4(
        app_nc_json_str(flow, "client_mac", ""),
        app_nc_json_str(flow, "source_mac", ""),
        "", "");
    const char *client_ip = webd_first_nonempty4(
        app_nc_json_str(flow, "client_ip", ""),
        app_nc_json_str(flow, "source_ip", ""),
        app_nc_json_str(flow, "src", ""),
        "");
    const char *dst_ip = webd_first_nonempty4(
        app_nc_json_str(flow, "destination_ip", ""),
        app_nc_json_str(flow, "remote_ip", ""),
        app_nc_json_str(flow, "dst", ""),
        "");
    const char *host = webd_first_nonempty4(
        app_nc_json_str(flow, "destination_host", ""),
        app_nc_json_str(flow, "host", ""),
        "", "");
    const char *action = app_nc_json_str(flow, "action", "allow");
    const char *protocol = app_nc_json_str(flow, "protocol",
        app_nc_json_str(flow, "proto", "unknown"));
    const char *service = app_nc_json_str(flow, "service", "");
    const char *flow_id = app_nc_json_str(flow, "flow_id", "");
    const char *record_source = app_nc_json_str(flow, "source", "audit_flow_sample");
    const char *flow_source = app_nc_json_str(flow, "lifecycle_source", record_source);
    const char *history_hint_source = app_nc_json_str(flow, "event_lifecycle_history_hint_source", "");
    const char *host_source = app_nc_json_str(flow, "host_source", "");
    int is_event_lifecycle = app_nc_json_bool(flow, "conntrack_event_lifecycle_enabled", 0) ||
        app_nc_json_bool(flow, "flow_lifecycle_exact", 0) ||
        app_nc_json_bool(flow, "exact_lifecycle", 0) ||
        !strcasecmp(record_source, "ctnetlink_destroy") ||
        !strcasecmp(flow_source, "audit_flow_event_lifecycle");
    int64_t ts = app_nc_json_int64(flow, "ts", app_nc_json_int64(flow, "last_seen", 0));
    int64_t rx = app_nc_json_int64(flow, "rx_bytes", app_nc_json_int64(flow, "down_bytes", 0));
    int64_t tx = app_nc_json_int64(flow, "tx_bytes", app_nc_json_int64(flow, "up_bytes", 0));
    int64_t orig_bytes = app_nc_json_int64(flow, "orig_bytes", app_nc_json_int64(flow, "bytes_orig", 0));
    int64_t repl_bytes = app_nc_json_int64(flow, "repl_bytes", app_nc_json_int64(flow, "bytes_reply", 0));
    int64_t orig_packets = app_nc_json_int64(flow, "orig_packets", 0);
    int64_t repl_packets = app_nc_json_int64(flow, "repl_packets", 0);
    int byte_counter_valid_field = app_nc_json_bool(flow, "byte_counter_valid",
        app_nc_json_bool(flow, "byte_accounting_exact", app_nc_json_bool(flow, "exact_window_bytes", 0)));
    const char *byte_counter_reason = app_nc_json_str(flow, "byte_counter_reason", "");
    int byte_counters_observed = byte_counter_valid_field ||
        (orig_bytes > 0 || repl_bytes > 0 || rx > 0 || tx > 0 ||
         orig_packets > 0 || repl_packets > 0);
    int appid = app_nc_json_int(flow, "destination_app_id", app_nc_json_int(flow, "app_id", 0));
    const char *app_name = app_nc_json_str(flow, "destination_app_name",
        app_nc_json_str(flow, "app_name", ""));
    struct json_object *client = webd_insights_find_client_by_mac_or_ip(clients, mac, client_ip);
    const char *client_mac = client ? app_nc_json_str(client, "mac", "") : "";
    const char *effective_mac = webd_insights_mac_valid(mac) ? mac :
        (webd_insights_mac_valid(client_mac) ? client_mac : mac);
    const char *client_name = webd_first_nonempty4(
        client ? webd_insights_client_name(client, effective_mac) : "",
        app_nc_json_str(flow, "client_name", ""),
        client_ip,
        effective_mac);
    const char *client_attribution_source = client ?
        (webd_insights_mac_valid(mac) ? "clients_inventory_by_mac" : "clients_inventory_by_ip") :
        (webd_insights_mac_valid(mac) ? "flow_row_mac" : "unavailable");
    const char *client_attribution_confidence = client ?
        (webd_insights_mac_valid(mac) ? "exact_mac" : "current_ip_inventory") :
        (webd_insights_mac_valid(mac) ? "flow_row" : "unavailable");
    int dst_port = app_nc_json_int(flow, "destination_port", app_nc_json_int(flow, "dport", 0));
    int service_p2p = 0;
    const char *service_label = service && service[0] ? webd_connection_service_field_label(service) : "";
    const char *service_source = service && service[0] ? "flow_row" : "unavailable";
    struct webd_insights_risk_annotation risk_ann;
    struct webd_insights_policy_hit policy_hit;
    char sig_app_name[128] = "";
    char sig_app_category[96] = "";
    char sig_app_family[64] = "";
    int canonical_appid = appid;
    int sig_app_found = 0;
    char id[512];
    struct json_object *item = json_object_new_object();
    struct json_object *src = json_object_new_object();

    if (is_event_lifecycle) {
        int64_t collector_started_at = app_nc_json_int64(flow, "collector_started_at", 0);
        int64_t observed_since = app_nc_json_int64(flow, "observed_since", collector_started_at);
        int full_capture = app_nc_json_bool(flow, "full_capture_since_boot", 0);

        json_object_object_add(item, "collector_started_at", json_object_new_int64(collector_started_at));
        json_object_object_add(item, "observed_since", json_object_new_int64(observed_since));
        json_object_object_add(item, "full_capture_since_boot", json_object_new_boolean(full_capture));
        json_object_object_add(item, "collector_window_partial", json_object_new_boolean(
            app_nc_json_bool(flow, "collector_window_partial", 1)));
        json_object_object_add(item, "preexisting_flow_gap_possible", json_object_new_boolean(
            app_nc_json_bool(flow, "preexisting_flow_gap_possible", 1)));
        webd_obj_add_str(item, "event_lifecycle_scope",
                         app_nc_json_str(flow, "event_lifecycle_scope",
                                         "collector_observed_completed_destroy_flows"));
        webd_obj_add_str(item, "event_lifecycle_capture_scope",
                         app_nc_json_str(flow, "event_lifecycle_capture_scope",
                                         "collector_started_at_to_now_only"));
        webd_obj_add_str(item, "event_lifecycle_capture_reason",
                         app_nc_json_str(flow, "event_lifecycle_capture_reason",
                                         "ctnetlink collector does not reconstruct flows created before collector start"));
    }

    if ((!service_label || !service_label[0]) && (!service || !service[0])) {
        service_label = webd_connection_service_label(protocol, dst_port, &service_p2p);
        if (service_label && service_label[0])
            service_source = "port_fallback";
    }

    if (appid > 0)
        sig_app_found = webd_insights_app_lookup(appid, sig_app_name, sizeof(sig_app_name),
                                                 sig_app_category, sizeof(sig_app_category),
                                                 sig_app_family, sizeof(sig_app_family),
                                                 &canonical_appid);
    webd_insights_risk_lookup(risk_ctx, host[0] ? host : dst_ip, &risk_ann);
    snprintf(id, sizeof(id), "audit-flow:%s:%lld:%s:%s:%d",
             flow_id[0] ? flow_id : "row",
             (long long)ts,
             mac,
             dst_ip,
             app_nc_json_int(flow, "destination_port", app_nc_json_int(flow, "dport", 0)));

    webd_obj_add_str(item, "id", id);
    json_object_object_add(item, "ts", json_object_new_int64(ts));
    json_object_object_add(item, "timestamp", json_object_new_int64(ts));
    webd_obj_add_str(item, "source", is_event_lifecycle ? "audit_flow_event_lifecycle" : "audit_flow_history");
    webd_obj_add_str(item, "record_source", record_source);
    webd_obj_add_str(item, "source_table",
                     is_event_lifecycle ? "audit_flow_event_lifecycle" :
                     (app_nc_json_bool(flow, "historical_lifecycle", 0) ? "audit_flow_lifecycle" : "audit_flow_sample"));
    webd_obj_add_str(item, "flow_id", flow_id);
    webd_obj_add_str(item, "risk", risk_ann.risk[0] ? risk_ann.risk : "unknown");
    webd_obj_add_str(item, "risk_level", risk_ann.level[0] ? risk_ann.level : "unknown");
    json_object_object_add(item, "risk_supported", json_object_new_boolean(risk_ann.supported));
    json_object_object_add(item, "risk_matched", json_object_new_boolean(risk_ann.matched));
    webd_obj_add_str(item, "risk_source", risk_ann.source[0] ? risk_ann.source : "unavailable");
    webd_obj_add_str(item, "risk_category", risk_ann.category);
    webd_obj_add_str(item, "risk_feed", risk_ann.feed);
    webd_obj_add_str(item, "risk_matched_domain", risk_ann.matched_domain);
    webd_obj_add_str(item, "risk_reason", risk_ann.reason[0] ? risk_ann.reason : "no_reputation_match");
    json_object_object_add(item, "risk_severity", json_object_new_int(risk_ann.severity));
    json_object_object_add(item, "risk_confidence", json_object_new_int(risk_ann.confidence));
    json_object_object_add(item, "risk_overlay_supported", json_object_new_boolean(risk_ann.supported));
    json_object_object_add(item, "risk_overlay_matched", json_object_new_boolean(risk_ann.matched));
    webd_obj_add_str(item, "risk_annotation_source",
                     risk_ann.supported ? "webd.aegis_reputation_overlay" : "unavailable");
    webd_obj_add_str(item, "action", action && action[0] ? action : "allow");
    webd_obj_add_str(item, "action_source", is_event_lifecycle ? "ctnetlink_destroy_default_allow" : "audit_flow_sample");
    webd_obj_add_str(item, "direction", app_nc_json_str(flow, "direction", "unknown"));
    webd_obj_add_str(item, "protocol", protocol && protocol[0] ? protocol : "unknown");
    webd_obj_add_str(item, "service", service && service[0] ? service : (service_label ? service_label : ""));
    webd_obj_add_str(item, "service_label", service_label ? service_label : "");
    webd_obj_add_str(item, "service_source", service_source);
    webd_obj_add_str(item, "service_attribution_source", service_source);
    json_object_object_add(item, "service_port_fallback", json_object_new_boolean(!strcmp(service_source, "port_fallback")));
    json_object_object_add(item, "service_p2p_heuristic", json_object_new_boolean(service_p2p));
    json_object_object_add(item, "app_id", json_object_new_int(appid));
    json_object_object_add(item, "appid", json_object_new_int(appid));
    json_object_object_add(item, "canonical_app_id", json_object_new_int(canonical_appid));
    webd_obj_add_str(item, "app_name", app_name && app_name[0] ? app_name : sig_app_name);
    webd_obj_add_str(item, "app_name_source", app_name && app_name[0] ?
                     (is_event_lifecycle ?
                      (history_hint_source[0] ? history_hint_source :
                       (host_source[0] ? host_source : "audit_flow_event_lifecycle_backfill")) :
                      "audit_flow_sample") :
                     (sig_app_found ? "signature_db" : "unavailable"));
    webd_obj_add_str(item, "app_attribution_source", app_name && app_name[0] ?
                     (is_event_lifecycle ?
                      (history_hint_source[0] ? history_hint_source :
                       (host_source[0] ? host_source : "audit_flow_event_lifecycle_backfill")) :
                      "audit_flow_sample") :
                     (sig_app_found ? "signature_db" :
                      (!strcmp(service_source, "port_fallback") ? "port_hint_only_not_application" : "unavailable")));
    webd_obj_add_str(item, "app_attribution_reason", app_name && app_name[0] ?
                     (is_event_lifecycle ? "event_lifecycle_query_backfill_or_flow_row_app" : "flow_row_app") :
                     (sig_app_found ? "app_id_signature_lookup" :
                      (!strcmp(service_source, "port_fallback") ? "no_host_or_app_signature_using_service_label_only" : "no_app_or_host_evidence")));
    webd_obj_add_str(item, "host_attribution_source", host_source[0] ? host_source :
                     (history_hint_source[0] ? history_hint_source : "unavailable"));
    webd_obj_add_str(item, "app_category", sig_app_category);
    webd_obj_add_str(item, "app_family", sig_app_family);
    webd_obj_add_str(item, "source_mac", webd_insights_mac_valid(effective_mac) ? effective_mac : "");
    webd_obj_add_str(item, "client_mac", webd_insights_mac_valid(effective_mac) ? effective_mac : "");
    webd_obj_add_str(item, "source_ip", client_ip);
    webd_obj_add_str(item, "client_ip", client_ip);
    webd_obj_add_str(item, "source_host", client_name);
    webd_obj_add_str(item, "client_name", client_name);
    webd_obj_add_str(item, "client_attribution_source", client_attribution_source);
    webd_obj_add_str(item, "client_attribution_confidence", client_attribution_confidence);
    json_object_object_add(item, "client_inventory_overlay", json_object_new_boolean(client != NULL));
    json_object_object_add(item, "source_port", json_object_new_int(
        app_nc_json_int(flow, "source_port", app_nc_json_int(flow, "sport", 0))));
    webd_obj_add_str(item, "destination_mac", "");
    webd_obj_add_str(item, "destination_host", host);
    webd_obj_add_str(item, "host", host);
    webd_obj_add_str(item, "destination_ip", dst_ip);
    webd_obj_add_str(item, "remote_ip", app_nc_json_str(flow, "remote_ip", dst_ip));
    json_object_object_add(item, "destination_port", json_object_new_int(dst_port));
    webd_obj_add_str(item, "destination_region", "");
    webd_obj_add_str(item, "source_region", "");
    webd_obj_add_str(item, "in_network_id", webd_first_nonempty4(
        app_nc_json_str(flow, "in_network_id", ""),
        app_nc_json_str(flow, "source_network_id", ""),
        app_nc_json_str(client, "network", ""), ""));
    webd_obj_add_str(item, "out_network_id", webd_first_nonempty4(
        app_nc_json_str(flow, "out_network_id", ""),
        app_nc_json_str(flow, "destination_network_id", ""),
        app_nc_json_str(flow, "wan_id", ""), ""));
    webd_obj_add_str(item, "in_interface", webd_first_nonempty4(
        app_nc_json_str(flow, "in_interface", ""),
        app_nc_json_str(flow, "interface", ""),
        app_nc_json_str(client, "interface", ""), ""));
    webd_obj_add_str(item, "out_interface", webd_first_nonempty4(
        app_nc_json_str(flow, "out_interface", ""),
        app_nc_json_str(flow, "wan_ifname", ""), "", ""));
    webd_obj_add_str(item, "wan_id", app_nc_json_str(flow, "wan_id", ""));
    webd_obj_add_str(item, "wan_ifname", app_nc_json_str(flow, "wan_ifname", ""));
    if (is_event_lifecycle) {
        const char *snat_ip = app_nc_json_str(flow, "snat_ip", "");
        const char *dnat_ip = app_nc_json_str(flow, "dnat_ip", "");
        int snat_port = app_nc_json_int(flow, "snat_port", 0);
        int dnat_port = app_nc_json_int(flow, "dnat_port", 0);
        int dnat_local = dnat_ip[0] && webd_insights_ip_is_router_address(dnat_ip);

        webd_obj_add_str(item, "initiator", app_nc_json_str(flow, "initiator", "unknown"));
        webd_obj_add_str(item, "direction_source", app_nc_json_str(flow, "direction_source", ""));
        webd_obj_add_str(item, "reply_source_ip", app_nc_json_str(flow, "reply_source_ip", ""));
        webd_obj_add_str(item, "reply_destination_ip", app_nc_json_str(flow, "reply_destination_ip", ""));
        json_object_object_add(item, "reply_source_port", json_object_new_int(
            app_nc_json_int(flow, "reply_source_port", 0)));
        json_object_object_add(item, "reply_destination_port", json_object_new_int(
            app_nc_json_int(flow, "reply_destination_port", 0)));
        webd_obj_add_str(item, "snat_ip", snat_ip);
        webd_obj_add_str(item, "dnat_ip", dnat_ip);
        json_object_object_add(item, "snat_port", json_object_new_int(snat_port));
        json_object_object_add(item, "dnat_port", json_object_new_int(dnat_port));
        json_object_object_add(item, "nat_tuple_supported", json_object_new_boolean(1));
        json_object_object_add(item, "snat_observed", json_object_new_boolean(
            app_nc_json_bool(flow, "snat_observed", snat_ip[0] || snat_port > 0)));
        json_object_object_add(item, "dnat_observed", json_object_new_boolean(
            app_nc_json_bool(flow, "dnat_observed", dnat_ip[0] || dnat_port > 0)));
        json_object_object_add(item, "dnat_local_termination", json_object_new_boolean(dnat_local));
        webd_obj_add_str(item, "nat_tuple_source", "ctnetlink_original_reply_tuple");
    }
    webd_obj_add_str(item, "policy", "");
    webd_obj_add_str(item, "policy_type", "");
    json_object_object_add(item, "policy_supported", json_object_new_boolean(0));
    json_object_object_add(item, "policy_hit_supported", json_object_new_boolean(0));
    json_object_object_add(item, "dataplane_action_supported", json_object_new_boolean(0));
    webd_insights_policy_lookup(policy_ctx, ts, flow_id, client_ip, effective_mac,
                                app_nc_json_int(flow, "source_port", app_nc_json_int(flow, "sport", 0)),
                                dst_ip, host,
                                dst_port,
                                protocol, &policy_hit);
    webd_insights_apply_policy_hit_overlay(item, policy_ctx, &policy_hit);
    (void)webd_insights_apply_flow_policy_attribution(item, flow);
    json_object_object_add(item, "rx_bytes", json_object_new_int64(rx));
    json_object_object_add(item, "tx_bytes", json_object_new_int64(tx));
    json_object_object_add(item, "down_bytes", json_object_new_int64(rx));
    json_object_object_add(item, "up_bytes", json_object_new_int64(tx));
    json_object_object_add(item, "bytes", json_object_new_int64(rx + tx));
    json_object_object_add(item, "up_rate", json_object_new_int64(app_nc_json_int64(flow, "up_rate", 0)));
    json_object_object_add(item, "down_rate", json_object_new_int64(app_nc_json_int64(flow, "down_rate", 0)));
    json_object_object_add(item, "connections", json_object_new_int(1));
    json_object_object_add(item, "hit_count", json_object_new_int(1));
    json_object_object_add(item, "flow_count", json_object_new_int(1));
    json_object_object_add(item, "sample_count", json_object_new_int(app_nc_json_int(flow, "sample_count", 1)));
    json_object_object_add(item, "bytes_supported", json_object_new_boolean(1));
    json_object_object_add(item, "byte_counters_observed", json_object_new_boolean(byte_counters_observed));
    json_object_object_add(item, "byte_accounting_observed", json_object_new_boolean(byte_counters_observed));
    json_object_object_add(item, "byte_counter_valid", json_object_new_boolean(byte_counters_observed));
    webd_obj_add_str(item, "byte_counter_reason", byte_counter_reason && byte_counter_reason[0] ?
                     byte_counter_reason :
                     (byte_counters_observed ? "counter_attrs_present" :
                      (is_event_lifecycle ? "ctnetlink_destroy_counter_attrs_empty_or_zero" : "sample_counter_zero")));
    webd_obj_add_str(item, "byte_accounting_observation_reason",
                     byte_counters_observed ? "counter_attrs_present" :
                     (is_event_lifecycle ? "ctnetlink_destroy_counter_attrs_empty_or_zero" : "sample_counter_zero"));
    webd_insights_enrich_geo_fields(item, dst_ip, client_ip, NULL, NULL);
    webd_obj_add_str(item, "geo_attribution_source", app_nc_json_str(item, "destination_geo_source",
                     app_nc_json_str(item, "source_geo_source", "unavailable")));
    json_object_object_add(item, "five_tuple_supported", json_object_new_boolean(1));
    json_object_object_add(item, "five_tuple_exact", json_object_new_boolean(1));
    webd_obj_add_str(item, "five_tuple_join", is_event_lifecycle ? "ctnetlink_destroy_lifecycle" : "audit_flow_history");
    json_object_object_add(item, "historical_sample", json_object_new_boolean(1));
    json_object_object_add(item, "historical_lifecycle", json_object_new_boolean(app_nc_json_bool(flow, "historical_lifecycle", 0)));
    json_object_object_add(item, "historical_lifecycle_exact", json_object_new_boolean(0));
    webd_insights_add_flow_lifecycle(item, flow, app_nc_json_bool(flow, "historical_lifecycle", 0) || is_event_lifecycle);
    json_object_object_add(item, "event_lifecycle_enriched", json_object_new_boolean(is_event_lifecycle &&
        (client != NULL || risk_ann.supported || policy_hit.supported || strcmp(service_source, "unavailable"))));
    webd_obj_add_str(item, "event_lifecycle_enrichment_source", is_event_lifecycle ?
        (history_hint_source[0] ? "core.query_backfill+webd.clients+geoip+risk_policy_overlay" :
         "webd.clients+geoip+risk_policy_overlay+service_port_hint") : "not_event_lifecycle");
    webd_obj_add_str(item, "policy_attribution_source", app_nc_json_str(item, "policy_source", "unavailable"));
    webd_obj_add_str(item, "risk_attribution_source", app_nc_json_str(item, "risk_source", "unavailable"));
    json_object_object_add(src, "mac", json_object_new_string(webd_insights_mac_valid(effective_mac) ? effective_mac : ""));
    json_object_object_add(src, "ip", json_object_new_string(client_ip));
    json_object_object_add(src, "name", json_object_new_string(client_name));
    json_object_object_add(src, "hostname", json_object_new_string(app_nc_json_str(client, "hostname", "")));
    json_object_object_add(src, "vendor_name", json_object_new_string(webd_first_nonempty4(
        app_nc_json_str(client, "vendor_name", ""),
        app_nc_json_str(client, "vendor", ""),
        "", "")));
    json_object_object_add(src, "device_type", json_object_new_string(webd_first_nonempty4(
        app_nc_json_str(client, "device_type", ""),
        app_nc_json_str(client, "type", ""),
        "", "")));
    if (client && json_object_object_get(client, "image"))
        json_object_object_add(src, "icon", json_object_get(json_object_object_get(client, "image")));
    json_object_object_add(src, "identity_valid", json_object_new_boolean(webd_insights_mac_valid(effective_mac)));
    webd_obj_add_str(src, "attribution_source", client_attribution_source);
    webd_obj_add_str(src, "attribution_confidence", client_attribution_confidence);
    json_object_object_add(src, "inventory_overlay", json_object_new_boolean(client != NULL));
    json_object_object_add(item, "source_client", src);
    webd_insights_add_client_attribution(item, client_ip, effective_mac);
    webd_insights_add_trust_contract(item);
    return item;
}

static int webd_insights_group_cmp(const void *a, const void *b)
{
    const struct webd_insights_group *ga = (const struct webd_insights_group *)a;
    const struct webd_insights_group *gb = (const struct webd_insights_group *)b;

    if (ga->count != gb->count)
        return gb->count - ga->count;
    if (ga->last_ts < gb->last_ts)
        return 1;
    if (ga->last_ts > gb->last_ts)
        return -1;
    return strcmp(ga->key, gb->key);
}

static int webd_insights_group_bytes_cmp(const void *a, const void *b)
{
    const struct webd_insights_group *ga = (const struct webd_insights_group *)a;
    const struct webd_insights_group *gb = (const struct webd_insights_group *)b;
    int64_t ba = ga->rx_bytes + ga->tx_bytes;
    int64_t bb = gb->rx_bytes + gb->tx_bytes;

    if (ba < bb)
        return 1;
    if (ba > bb)
        return -1;
    if (ga->last_ts < gb->last_ts)
        return 1;
    if (ga->last_ts > gb->last_ts)
        return -1;
    return strcmp(ga->key, gb->key);
}

static void webd_insights_group_add_semantics(struct webd_insights_group *g,
                                              const struct webd_insights_risk_annotation *risk,
                                              const char *action,
                                              int inc)
{
    int n = inc > 0 ? inc : 1;
    const char *r = risk && risk->risk[0] ? risk->risk : "unknown";

    if (!g)
        return;
    if (risk && risk->supported)
        g->risk_supported = 1;
    if (risk && risk->matched)
        g->affected_count += n;
    if (!strcasecmp(r, "low"))
        g->risk_low += n;
    else if (!strcasecmp(r, "suspicious"))
        g->risk_suspicious += n;
    else if (!strcasecmp(r, "concerning"))
        g->risk_concerning += n;
    else if (!strcasecmp(r, "high") || !strcasecmp(r, "critical"))
        g->risk_high += n;
    else
        g->risk_unknown += n;
    if (action && (!strcasecmp(action, "block") || !strcasecmp(action, "blocked") ||
                   !strcasecmp(action, "drop") || !strcasecmp(action, "deny")))
        g->action_block += n;
    else if (action && action[0] && strcasecmp(action, "allow"))
        g->action_other += n;
    else
        g->action_allow += n;
}

static void webd_insights_group_add(struct webd_insights_group *groups, int *count,
                                    int max_groups, const char *key,
                                    const char *label, const char *mac,
                                    const char *ip, int app_id,
                                    int inc, int64_t ts,
                                    const struct webd_insights_risk_annotation *risk,
                                    const char *action)
{
    int i;

    if (!groups || !count || !key || !key[0] || max_groups <= 0)
        return;
    if (inc <= 0)
        inc = 1;
    for (i = 0; i < *count; i++) {
        if (!strcmp(groups[i].key, key)) {
            groups[i].count += inc;
            if (ts > groups[i].last_ts)
                groups[i].last_ts = ts;
            webd_insights_group_add_semantics(&groups[i], risk, action, inc);
            return;
        }
    }
    if (*count >= max_groups)
        return;
    snprintf(groups[*count].key, sizeof(groups[*count].key), "%s", key);
    snprintf(groups[*count].label, sizeof(groups[*count].label), "%s", label && label[0] ? label : key);
    snprintf(groups[*count].mac, sizeof(groups[*count].mac), "%s", mac ? mac : "");
    snprintf(groups[*count].ip, sizeof(groups[*count].ip), "%s", ip ? ip : "");
    groups[*count].app_id = app_id;
    groups[*count].canonical_app_id = app_id;
    groups[*count].count = inc;
    groups[*count].last_ts = ts;
    webd_insights_group_add_semantics(&groups[*count], risk, action, inc);
    (*count)++;
}

static void webd_insights_group_add_app(struct webd_insights_group *groups, int *count,
                                        int max_groups, const char *key,
                                        const char *label, int app_id,
                                        int canonical_app_id,
                                        const char *category,
                                        const char *family,
                                        const char *name_source,
                                        int inc, int64_t ts,
                                        const struct webd_insights_risk_annotation *risk,
                                        const char *action)
{
    int before = count ? *count : 0;

    webd_insights_group_add(groups, count, max_groups, key, label, "", "", app_id, inc, ts, risk, action);
    if (!groups || !count)
        return;
    if (*count > before && before < max_groups) {
        groups[before].canonical_app_id = canonical_app_id > 0 ? canonical_app_id : app_id;
        snprintf(groups[before].category, sizeof(groups[before].category), "%s", category ? category : "");
        snprintf(groups[before].family, sizeof(groups[before].family), "%s", family ? family : "");
        snprintf(groups[before].name_source, sizeof(groups[before].name_source), "%s", name_source ? name_source : "");
    }
}

static void webd_insights_flow_app_group_add(struct webd_insights_group *groups, int *count,
                                             int max_groups, const char *key,
                                             const char *label, const char *app_proto,
                                             const char *service, int64_t rx_bytes,
                                             int64_t tx_bytes, int64_t ts,
                                             const char *risk, const char *action)
{
    int i;
    int64_t bytes = rx_bytes + tx_bytes;

    if (!groups || !count || !key || !key[0] || max_groups <= 0)
        return;
    if (bytes <= 0)
        return;
    for (i = 0; i < *count; i++) {
        if (!strcmp(groups[i].key, key)) {
            groups[i].count++;
            groups[i].rx_bytes += rx_bytes;
            groups[i].tx_bytes += tx_bytes;
            if (ts > groups[i].last_ts)
                groups[i].last_ts = ts;
            if (risk && risk[0] && strcasecmp(risk, "unknown"))
                groups[i].affected_count++;
            if (action && (!strcasecmp(action, "block") || !strcasecmp(action, "blocked") ||
                           !strcasecmp(action, "drop") || !strcasecmp(action, "deny")))
                groups[i].action_block++;
            else
                groups[i].action_allow++;
            if (risk && !strcasecmp(risk, "low"))
                groups[i].risk_low++;
            else if (risk && !strcasecmp(risk, "suspicious"))
                groups[i].risk_suspicious++;
            else if (risk && !strcasecmp(risk, "concerning"))
                groups[i].risk_concerning++;
            else if (risk && (!strcasecmp(risk, "high") || !strcasecmp(risk, "critical")))
                groups[i].risk_high++;
            else
                groups[i].risk_unknown++;
            return;
        }
    }
    if (*count >= max_groups)
        return;
    snprintf(groups[*count].key, sizeof(groups[*count].key), "%s", key);
    snprintf(groups[*count].label, sizeof(groups[*count].label), "%s", label && label[0] ? label : key);
    snprintf(groups[*count].app_proto, sizeof(groups[*count].app_proto), "%s", app_proto ? app_proto : "");
    snprintf(groups[*count].service, sizeof(groups[*count].service), "%s", service ? service : "");
    groups[*count].count = 1;
    groups[*count].last_ts = ts;
    groups[*count].rx_bytes = rx_bytes;
    groups[*count].tx_bytes = tx_bytes;
    if (risk && risk[0] && strcasecmp(risk, "unknown"))
        groups[*count].affected_count = 1;
    if (action && (!strcasecmp(action, "block") || !strcasecmp(action, "blocked") ||
                   !strcasecmp(action, "drop") || !strcasecmp(action, "deny")))
        groups[*count].action_block = 1;
    else
        groups[*count].action_allow = 1;
    if (risk && !strcasecmp(risk, "low"))
        groups[*count].risk_low = 1;
    else if (risk && !strcasecmp(risk, "suspicious"))
        groups[*count].risk_suspicious = 1;
    else if (risk && !strcasecmp(risk, "concerning"))
        groups[*count].risk_concerning = 1;
    else if (risk && (!strcasecmp(risk, "high") || !strcasecmp(risk, "critical")))
        groups[*count].risk_high = 1;
    else
        groups[*count].risk_unknown = 1;
    (*count)++;
}

static struct json_object *webd_insights_groups_to_array(struct webd_insights_group *groups,
                                                         int count, int limit,
                                                         const char *kind)
{
    struct json_object *arr = json_object_new_array();
    int i;
    const char *metric_type = "hit_count";
    const char *semantic = (kind && !strcmp(kind, "app")) ?
        "top_applications_from_audit_hits_without_byte_ranking" :
        "top_count_from_audit_hits";
    const char *type = "destination";

    if (count > 1)
        qsort(groups, (size_t)count, sizeof(groups[0]), webd_insights_group_cmp);
    if (limit <= 0 || limit > count)
        limit = count;
    if (kind && !strcmp(kind, "client"))
        type = "client";
    else if (kind && !strcmp(kind, "app"))
        type = "application";
    for (i = 0; i < limit; i++) {
        struct json_object *o = json_object_new_object();
        struct json_object *risk = json_object_new_object();
        struct json_object *action = json_object_new_object();

        webd_obj_add_str(o, "id", groups[i].key);
        webd_obj_add_str(o, "key", groups[i].key);
        webd_obj_add_str(o, "name", groups[i].label);
        webd_obj_add_str(o, "display_name", groups[i].label);
        webd_obj_add_str(o, "type", type);
        webd_obj_add_str(o, "metric_type", metric_type);
        webd_obj_add_str(o, "ranking_basis", metric_type);
        webd_obj_add_str(o, "semantic", semantic);
        webd_obj_add_str(o, "risk_scope", "cybersecure_reputation_if_matched");
        json_object_object_add(o, "count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "flow_count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "hit_count", json_object_new_int(groups[i].count));
        json_object_object_add(o, "last_seen", json_object_new_int64(groups[i].last_ts));
        json_object_object_add(o, "rx_bytes", json_object_new_int64(0));
        json_object_object_add(o, "tx_bytes", json_object_new_int64(0));
        json_object_object_add(o, "bytes", json_object_new_int64(0));
        json_object_object_add(o, "bytes_supported", json_object_new_boolean(0));
        json_object_object_add(o, "risk_supported", json_object_new_boolean(groups[i].risk_supported));
        json_object_object_add(o, "risk_matched", json_object_new_boolean(groups[i].affected_count > 0));
        json_object_object_add(o, "affected", json_object_new_boolean(groups[i].affected_count > 0));
        json_object_object_add(o, "affected_count", json_object_new_int(groups[i].affected_count));
        webd_obj_add_str(o, "risk", groups[i].affected_count > 0 ? "matched" : "unknown");
        webd_obj_add_str(o, "risk_level", groups[i].affected_count > 0 ? "matched" : "unknown");
        json_object_object_add(risk, "unknown", json_object_new_int(groups[i].risk_unknown));
        json_object_object_add(risk, "low", json_object_new_int(groups[i].risk_low));
        json_object_object_add(risk, "suspicious", json_object_new_int(groups[i].risk_suspicious));
        json_object_object_add(risk, "concerning", json_object_new_int(groups[i].risk_concerning));
        json_object_object_add(risk, "high", json_object_new_int(groups[i].risk_high));
        json_object_object_add(o, "risk_breakdown", risk);
        json_object_object_add(action, "allow", json_object_new_int(groups[i].action_allow));
        json_object_object_add(action, "block", json_object_new_int(groups[i].action_block));
        json_object_object_add(action, "other", json_object_new_int(groups[i].action_other));
        json_object_object_add(o, "action_breakdown", action);
        webd_obj_add_str(o, "action", groups[i].action_block > 0 ? "block" : "allow");
        webd_obj_add_str(o, "source", "audit_urls");
        if (kind && !strcmp(kind, "client")) {
            webd_obj_add_str(o, "mac", groups[i].mac);
            webd_obj_add_str(o, "ip", groups[i].ip);
        } else if (kind && !strcmp(kind, "app")) {
            json_object_object_add(o, "app_id", json_object_new_int(groups[i].app_id));
            json_object_object_add(o, "appid", json_object_new_int(groups[i].app_id));
            json_object_object_add(o, "canonical_app_id", json_object_new_int(groups[i].canonical_app_id));
            webd_obj_add_str(o, "category", groups[i].category);
            webd_obj_add_str(o, "family", groups[i].family);
            webd_obj_add_str(o, "name_source", groups[i].name_source[0] ? groups[i].name_source : (groups[i].app_id > 0 ? "app_id_only" : "unavailable"));
            webd_obj_add_str(o, "icon", "");
        } else {
            webd_obj_add_str(o, "host", groups[i].key);
            webd_obj_add_str(o, "destination_type", strchr(groups[i].key, ':') ? "ip_or_ipv6" : (strchr(groups[i].key, '.') ? "domain" : "host"));
            webd_obj_add_str(o, "destination_host", groups[i].key);
        }
        json_object_array_add(arr, o);
    }
    return arr;
}

