static int webd_audit_flow_summary_has_items(struct json_object *summary)
{
    struct json_object *items = webd_obj_child_array(summary, "items");

    return items && json_object_array_length(items) > 0;
}

static const char *webd_audit_flow_summary_mode(const struct webd_audit_bff_query *q)
{
    const char *mode = q ? q->mode : "";

    if (mode && (!strcasecmp(mode, "sample") ||
                 !strcasecmp(mode, "lifecycle") ||
                 !strcasecmp(mode, "flow_lifecycle") ||
                 !strcasecmp(mode, "event_lifecycle") ||
                 !strcasecmp(mode, "flow_event_lifecycle") ||
                 !strcasecmp(mode, "ctnetlink_lifecycle") ||
                 !strcasecmp(mode, "exact_lifecycle")))
        return mode;

    /*
     * The standalone audit BFF backs the LuCI Advanced Audit compatible
     * Applications/Protocols tabs.  The runtime protocol snapshot can be empty
     * while audit_flow_event_lifecycle already has exact completed-flow rows, so
     * default these summaries to the ctnetlink DESTROY lifecycle ledger and only
     * fall back to the sampled summary when the exact ledger is unavailable.
     */
    return "event_lifecycle";
}

static struct json_object *webd_audit_flow_summary_rows(const struct webd_audit_bff_query *q,
                                                        int top)
{
    struct webd_insights_query iq;
    struct json_object *summary;
    const char *mode;

    memset(&iq, 0, sizeof(iq));
    snprintf(iq.period, sizeof(iq.period), "%s", "day");
    mode = webd_audit_flow_summary_mode(q);
    if (mode && mode[0])
        snprintf(iq.mode, sizeof(iq.mode), "%s", mode);
    if (q) {
        iq.ts_from = q->ts_from;
        iq.ts_to = q->ts_to;
        iq.page_number = 1;
        iq.page_size = top;
        iq.top = top;
        snprintf(iq.search, sizeof(iq.search), "%s", q->q);
    } else {
        iq.ts_to = now_s();
        iq.ts_from = iq.ts_to - 86400;
        iq.top = top;
        iq.page_size = top;
        iq.page_number = 1;
    }

    summary = webd_insights_fetch_flow_app_summary(&iq, top);
    if (summary && webd_audit_flow_summary_has_items(summary))
        return summary;

    if (summary && q && q->mode[0] && strcasecmp(q->mode, "records") &&
        strcasecmp(q->mode, "apps") && strcasecmp(q->mode, "protocols"))
        return summary;

    if (summary)
        json_object_put(summary);

    memset(iq.mode, 0, sizeof(iq.mode));
    summary = webd_insights_fetch_flow_app_summary(&iq, top);
    if (summary) {
        json_object_object_add(summary, "fallback_from", json_object_new_string(mode && mode[0] ? mode : "event_lifecycle"));
        json_object_object_add(summary, "fallback_reason", json_object_new_string("event_lifecycle_summary_empty_or_unavailable"));
    }
    return summary;
}

static struct json_object *webd_audit_protocols_response(const struct http_req *req,
                                                         struct json_object *body,
                                                         int *http_status)
{
    struct webd_audit_bff_query q;
    struct json_object *view;
    struct json_object *status;
    struct json_object *src;
    struct json_object *flow_summary = NULL;
    struct json_object *rows;
    struct json_object *data = json_object_new_object();
    struct json_object *proto_src = NULL;
    int total = 0;
    int flow_fallback = 0;
    int protocol_source_available = 0;

    if (http_status)
        *http_status = 200;
    webd_audit_read_query(req, body, &q);
    status = webd_audit_fetch_status();
    protocol_source_available =
        webd_audit_status_has_table(status, "audit_protocol_snapshot");
    view = webd_audit_fetch_view();
    src = webd_obj_child_array(view, "protocols");
    if (!src || json_object_array_length(src) == 0) {
        flow_summary = webd_audit_flow_summary_rows(&q, 500);
        src = webd_obj_child_array(flow_summary, "items");
        flow_fallback = src != NULL;
    }
    proto_src = json_object_new_array();
    if (src) {
        int i, n = (int)json_object_array_length(src);
        for (i = 0; i < n; i++) {
            struct json_object *row = json_object_array_get_idx(src, i);
            const char *name_source = app_nc_json_str(row, "name_source", "");
            int app_id = app_nc_json_int(row, "app_id", app_nc_json_int(row, "appid", 0));
            if (flow_fallback && app_id > 0 && !webd_str_contains_i(name_source, "service"))
                continue;
            webd_audit_entity_add_aliases(row);
            if (!app_nc_json_has(row, "name") && app_nc_json_str(row, "service", "")[0])
                webd_obj_add_str(row, "name", app_nc_json_str(row, "service", ""));
            if (!app_nc_json_has(row, "type"))
                webd_obj_add_str(row, "type", app_nc_json_str(row, "protocol", "protocol"));
            json_object_array_add(proto_src, json_object_get(row));
        }
    }
    rows = webd_audit_paginate_array(proto_src, &q, webd_audit_entity_match, 0, &total);
    json_object_object_add(data, "protocols", json_object_get(rows));
    json_object_object_add(data, "records", json_object_get(rows));
    json_object_object_add(data, "items", rows);
    webd_audit_add_page_meta(data, &q, total, (int)json_object_array_length(webd_obj_child_array(data, "protocols")),
                             flow_fallback ? "jmxd.audit_flow_app_summary.service_fallback" : "audit_view.protocols");
    json_object_object_add(data, "protocol_snapshot_supported",
                           json_object_new_boolean(protocol_source_available));
    json_object_object_add(data, "protocol_snapshot_records_present",
                           json_object_new_boolean(!flow_fallback && total > 0));
    json_object_object_add(data, "flow_summary_fallback", json_object_new_boolean(flow_fallback));
    if (flow_fallback) {
        json_object_object_add(data, "degraded", json_object_new_boolean(1));
        webd_obj_add_str(data, "reason", "audit_protocol_snapshot_empty_using_flow_service_summary");
    }
    webd_audit_add_caps(data, 0, protocol_source_available, flow_fallback,
                         0, 0, 0);
    json_object_put(proto_src);
    if (flow_summary) json_object_put(flow_summary);
    if (view) json_object_put(view);
    if (status) json_object_put(status);
    return webd_envelope(data, "webd.audit.protocols_bff");
}


static void webd_path_tail_token(const char *path, const char *prefix,
                                 char *out, size_t out_len)
{
    const char *p;
    size_t i, j = 0;

    if (!out || out_len == 0)
        return;
    out[0] = '\0';
    if (!path || !prefix)
        return;
    p = path;
    if (!strncmp(path, prefix, strlen(prefix)))
        p = path + strlen(prefix);
    while (*p == '/')
        p++;
    for (i = 0; p[i] && p[i] != '?' && p[i] != '/' && j + 1 < out_len; i++) {
        if (p[i] == '%' && isxdigit((unsigned char)p[i + 1]) && isxdigit((unsigned char)p[i + 2])) {
            char hex[3] = { p[i + 1], p[i + 2], 0 };
            out[j++] = (char)strtol(hex, NULL, 16);
            i += 2;
        } else if (p[i] == '+') {
            out[j++] = ' ';
        } else {
            out[j++] = p[i];
        }
    }
    out[j] = '\0';
}

static struct json_object *webd_audit_protocol_detail_response(const struct http_req *req,
                                                               struct json_object *body,
                                                               int *http_status)
{
    char id[160] = "";
    struct json_object *params = json_object_new_object();
    struct json_object *detail;
    struct json_object *data = json_object_new_object();

    if (http_status)
        *http_status = 200;
    webd_path_tail_token(req ? req->path : "", "/api/v1/audit/protocols/", id, sizeof(id));
    if ((!id[0] || !strcmp(id, "detail")) && body)
        snprintf(id, sizeof(id), "%s", app_nc_json_str(body, "id", app_nc_json_str(body, "protocol", "")));
    if (req && req->query[0]) {
        char qid[160] = "";
        if (webd_query_get(req->query, "id", qid, sizeof(qid)) || webd_query_get(req->query, "protocol", qid, sizeof(qid)))
            snprintf(id, sizeof(id), "%s", qid);
    }
    webd_obj_add_str(data, "id", id);
    webd_obj_add_str(data, "type", "protocol");
    if (!id[0]) {
        if (http_status) *http_status = 400;
        webd_obj_add_str(data, "error", "missing_protocol_id");
        return webd_envelope(data, "webd.audit.protocol_detail_bff");
    }
    json_object_object_add(params, "id", json_object_new_string(id));
    detail = webd_insights_ubus_data_timeout("audit_protocol_detail", params, 1800);
    json_object_put(params);
    if (detail) {
        webd_json_copy_key(data, "id", detail, "id");
        webd_json_copy_key(data, "name", detail, "name");
        webd_json_copy_key(data, "type", detail, "type");
        webd_json_copy_key(data, "category", detail, "type");
        webd_json_copy_key(data, "connections", detail, "connections");
        webd_json_copy_key(data, "up_rate", detail, "up_rate");
        webd_json_copy_key(data, "down_rate", detail, "down_rate");
        webd_json_copy_key(data, "bytes", detail, "bytes");
        webd_json_copy_key(data, "client_count", detail, "client_count");
        webd_json_copy_key(data, "evidence", detail, "evidence");
        if (webd_obj_child_array(detail, "clients"))
            json_object_object_add(data, "clients", json_object_get(webd_obj_child_array(detail, "clients")));
        else
            json_object_object_add(data, "clients", json_object_new_array());
        if (webd_obj_child_array(detail, "domains"))
            json_object_object_add(data, "domains", json_object_get(webd_obj_child_array(detail, "domains")));
        else
            json_object_object_add(data, "domains", json_object_new_array());
        if (webd_obj_child_array(detail, "time_series"))
            json_object_object_add(data, "time_series", json_object_get(webd_obj_child_array(detail, "time_series")));
        else
            json_object_object_add(data, "time_series", json_object_new_array());
        if (app_nc_json_str(detail, "error", "")[0]) {
            json_object_object_add(data, "degraded", json_object_new_boolean(1));
            webd_obj_add_str(data, "reason", app_nc_json_str(detail, "error", "audit_protocol_detail_degraded"));
        }
        json_object_put(detail);
    } else {
        json_object_object_add(data, "degraded", json_object_new_boolean(1));
        webd_obj_add_str(data, "reason", "audit_protocol_detail_unavailable");
        json_object_object_add(data, "clients", json_object_new_array());
        json_object_object_add(data, "domains", json_object_new_array());
        json_object_object_add(data, "time_series", json_object_new_array());
    }
    if (!app_nc_json_str(data, "name", "")[0] &&
        app_nc_json_int64(data, "bytes", 0) <= 0 &&
        app_nc_json_int64(data, "connections", app_nc_json_int64(data, "flow_count", 0)) <= 0) {
        struct webd_audit_bff_query q;
        struct json_object *flow_summary;
        struct json_object *items;
        struct json_object *matched = json_object_new_array();
        int i, n;

        memset(&q, 0, sizeof(q));
        q.ts_to = now_s();
        q.ts_from = q.ts_to - 86400;
        q.page = 0;
        q.page_number = 1;
        q.page_size = 500;
        snprintf(q.q, sizeof(q.q), "%s", id);
        flow_summary = webd_audit_flow_summary_rows(&q, 500);
        items = webd_obj_child_array(flow_summary, "items");
        n = items ? (int)json_object_array_length(items) : 0;
        for (i = 0; i < n; i++) {
            struct json_object *row = json_object_array_get_idx(items, i);
            const char *name = webd_first_nonempty4(app_nc_json_str(row, "service", ""),
                                                    app_nc_json_str(row, "name", ""),
                                                    app_nc_json_str(row, "app_name", ""),
                                                    app_nc_json_str(row, "protocol", ""));
            if (!strcasecmp(name, id) || webd_str_contains_i(name, id) ||
                webd_str_contains_i(app_nc_json_str(row, "protocol", ""), id)) {
                webd_audit_entity_add_aliases(row);
                json_object_array_add(matched, json_object_get(row));
            }
        }
        if (json_object_array_length(matched) > 0) {
            struct json_object *first = json_object_array_get_idx(matched, 0);
            webd_obj_add_str(data, "name", webd_first_nonempty4(app_nc_json_str(first, "service", ""),
                             app_nc_json_str(first, "name", ""), app_nc_json_str(first, "app_name", ""), id));
            webd_json_copy_key(data, "protocol", first, "protocol");
            webd_json_copy_key(data, "service", first, "service");
            webd_json_copy_key(data, "connections", first, "connections");
            webd_json_copy_key(data, "flow_count", first, "flow_count");
            webd_json_copy_key(data, "bytes", first, "bytes");
            webd_json_copy_key(data, "rx_bytes", first, "rx_bytes");
            webd_json_copy_key(data, "tx_bytes", first, "tx_bytes");
            json_object_object_add(data, "records", json_object_get(matched));
            json_object_object_add(data, "items", json_object_get(matched));
            json_object_object_add(data, "summary_fallback", json_object_new_boolean(1));
            json_object_object_add(data, "degraded", json_object_new_boolean(1));
            webd_obj_add_str(data, "reason", "audit_protocol_detail_empty_using_flow_service_summary");
            webd_obj_add_str(data, "source", "jmxd.audit_flow_app_summary.service_detail_fallback");
        }
        json_object_put(matched);
        if (flow_summary) json_object_put(flow_summary);
    }
    json_object_object_add(data, "detail_supported", json_object_new_boolean(1));
    json_object_object_add(data, "domains_supported", json_object_new_boolean(json_object_array_length(webd_obj_child_array(data, "domains")) > 0));
    json_object_object_add(data, "clients_supported", json_object_new_boolean(json_object_array_length(webd_obj_child_array(data, "clients")) > 0));
    if (!app_nc_json_str(data, "source", "")[0])
        webd_obj_add_str(data, "source", "jmxd.audit_protocol_detail");
    return webd_envelope(data, "webd.audit.protocol_detail_bff");
}

static struct json_object *webd_audit_apps_response(const struct http_req *req,
                                                    struct json_object *body,
                                                    int *http_status)
{
    struct webd_audit_bff_query q;
    struct json_object *flow_summary;
    struct json_object *src;
    struct json_object *app_src = json_object_new_array();
    struct json_object *rows;
    struct json_object *data = json_object_new_object();
    int total = 0;
    int i, n;
    int unresolved_fallback_count = 0;

    if (http_status)
        *http_status = 200;
    webd_audit_read_query(req, body, &q);
    flow_summary = webd_audit_flow_summary_rows(&q, 500);
    src = webd_obj_child_array(flow_summary, "items");
    n = src ? (int)json_object_array_length(src) : 0;
    for (i = 0; i < n; i++) {
        struct json_object *row = json_object_array_get_idx(src, i);
        int app_id = app_nc_json_int(row, "app_id", app_nc_json_int(row, "appid", 0));
        const char *entity = app_nc_json_str(row, "entity_type", "");
        const char *name_source = app_nc_json_str(row, "name_source", "");

        if (app_id <= 0 && !webd_str_contains_i(entity, "app") && !webd_str_contains_i(name_source, "app")) {
            const char *fallback_name = webd_first_nonempty4(app_nc_json_str(row, "app_name", ""),
                                                             app_nc_json_str(row, "name", ""),
                                                             app_nc_json_str(row, "service", ""),
                                                             app_nc_json_str(row, "protocol", ""));
            if (!fallback_name[0])
                continue;
            unresolved_fallback_count++;
            if (!app_nc_json_has(row, "app_unresolved"))
                json_object_object_add(row, "app_unresolved", json_object_new_boolean(1));
            if (!app_nc_json_has(row, "application_identity_precision"))
                webd_obj_add_str(row, "application_identity_precision", "service_or_protocol_fallback_not_app_id");
            if (!app_nc_json_has(row, "entity_type"))
                webd_obj_add_str(row, "entity_type", "service");
            if (!app_nc_json_has(row, "category"))
                webd_obj_add_str(row, "category", "network_service");
        }
        webd_audit_entity_add_aliases(row);
        if (!app_nc_json_has(row, "app") && app_nc_json_str(row, "app_name", "")[0])
            webd_obj_add_str(row, "app", app_nc_json_str(row, "app_name", ""));
        json_object_array_add(app_src, json_object_get(row));
    }
    rows = webd_audit_paginate_array(app_src, &q, webd_audit_entity_match, q.unknown_first, &total);
    json_object_object_add(data, "app_records", json_object_get(rows));
    json_object_object_add(data, "apps", json_object_get(rows));
    json_object_object_add(data, "records", json_object_get(rows));
    json_object_object_add(data, "items", rows);
    webd_audit_add_page_meta(data, &q, total, (int)json_object_array_length(webd_obj_child_array(data, "app_records")),
                             flow_summary ? "jmxd.audit_flow_app_summary" : "jmxd.audit_apps.empty");
    json_object_object_add(data, "unknown_first", json_object_new_boolean(q.unknown_first));
    json_object_object_add(data, "bytes_supported", json_object_new_boolean(flow_summary ? app_nc_json_bool(flow_summary, "bytes_supported", 1) : 0));
    json_object_object_add(data, "application_identity_partial", json_object_new_boolean(unresolved_fallback_count > 0));
    json_object_object_add(data, "service_or_protocol_fallback_count", json_object_new_int(unresolved_fallback_count));
    json_object_object_add(data, "flow_summary_fallback", json_object_new_boolean(1));
    json_object_object_add(data, "degraded", json_object_new_boolean(flow_summary ? 0 : 1));
    webd_obj_add_str(data, "reason", flow_summary ? "application_audit_from_flow_summary" : "audit_flow_app_summary_unavailable");
    webd_audit_add_caps(data, 0, 0, flow_summary != NULL, 0, 0, 0);
    json_object_put(app_src);
    if (flow_summary) json_object_put(flow_summary);
    return webd_envelope(data, "webd.audit.apps_bff");
}


static struct json_object *webd_audit_app_detail_response(const struct http_req *req,
                                                          struct json_object *body,
                                                          int *http_status)
{
    char id[160] = "";
    struct webd_audit_bff_query q;
    struct json_object *flow_summary;
    struct json_object *items;
    struct json_object *matched = json_object_new_array();
    struct json_object *data = json_object_new_object();
    int i, n;
    int app_id_filter = 0;

    if (http_status)
        *http_status = 200;
    webd_audit_read_query(req, body, &q);
    webd_path_tail_token(req ? req->path : "", "/api/v1/audit/apps/", id, sizeof(id));
    if ((!id[0] || !strcmp(id, "detail")) && body)
        snprintf(id, sizeof(id), "%s", app_nc_json_str(body, "id", app_nc_json_str(body, "app_id", app_nc_json_str(body, "app", ""))));
    if (req && req->query[0]) {
        char qid[160] = "";
        if (webd_query_get(req->query, "id", qid, sizeof(qid)) || webd_query_get(req->query, "app_id", qid, sizeof(qid)))
            snprintf(id, sizeof(id), "%s", qid);
    }
    if (!id[0]) {
        if (http_status) *http_status = 400;
        webd_obj_add_str(data, "error", "missing_app_id");
        json_object_put(matched);
        return webd_envelope(data, "webd.audit.app_detail_bff");
    }
    app_id_filter = atoi(id);
    snprintf(q.q, sizeof(q.q), "%s", id);
    flow_summary = webd_audit_flow_summary_rows(&q, 500);
    items = webd_obj_child_array(flow_summary, "items");
    n = items ? (int)json_object_array_length(items) : 0;
    for (i = 0; i < n; i++) {
        struct json_object *row = json_object_array_get_idx(items, i);
        int row_app_id = app_nc_json_int(row, "app_id", app_nc_json_int(row, "appid", app_nc_json_int(row, "canonical_app_id", 0)));
        const char *name = webd_first_nonempty4(app_nc_json_str(row, "app_name", ""),
                                                app_nc_json_str(row, "name", ""),
                                                app_nc_json_str(row, "application_name", ""),
                                                app_nc_json_str(row, "service", ""));
        if ((app_id_filter > 0 && row_app_id == app_id_filter) ||
            webd_str_contains_i(name, id) || webd_str_contains_i(app_nc_json_str(row, "service", ""), id)) {
            webd_audit_entity_add_aliases(row);
            json_object_array_add(matched, json_object_get(row));
        }
    }
    webd_obj_add_str(data, "id", id);
    webd_obj_add_str(data, "type", "app");
    json_object_object_add(data, "records", json_object_get(matched));
    json_object_object_add(data, "items", json_object_get(matched));
    if (json_object_array_length(matched) > 0) {
        struct json_object *first = json_object_array_get_idx(matched, 0);
        webd_json_copy_key(data, "app_id", first, "app_id");
        webd_json_copy_key(data, "appid", first, "appid");
        webd_obj_add_str(data, "name", webd_first_nonempty4(app_nc_json_str(first, "app_name", ""),
                         app_nc_json_str(first, "name", ""), app_nc_json_str(first, "application_name", ""), id));
        webd_json_copy_key(data, "category", first, "category");
        webd_json_copy_key(data, "connections", first, "connections");
        webd_json_copy_key(data, "bytes", first, "bytes");
        webd_json_copy_key(data, "total_bytes", first, "total_bytes");
        webd_json_copy_key(data, "clients", first, "clients");
        webd_json_copy_key(data, "evidence", first, "evidence");
    } else {
        json_object_object_add(data, "degraded", json_object_new_boolean(1));
        webd_obj_add_str(data, "reason", flow_summary ? "app_not_found_in_flow_summary_window" : "audit_flow_app_summary_unavailable");
    }
    json_object_object_add(data, "detail_supported", json_object_new_boolean(flow_summary != NULL));
    json_object_object_add(data, "domains", json_object_new_array());
    json_object_object_add(data, "time_series", json_object_new_array());
    json_object_object_add(data, "domains_supported", json_object_new_boolean(0));
    json_object_object_add(data, "time_series_supported", json_object_new_boolean(0));
    webd_obj_add_str(data, "source", "jmxd.audit_flow_app_summary");
    webd_obj_add_str(data, "note", "app detail is summary-backed; per-app domains/clients/time-series await dedicated audit ledger");
    json_object_put(matched);
    if (flow_summary) json_object_put(flow_summary);
    return webd_envelope(data, "webd.audit.app_detail_bff");
}

static struct json_object *webd_insights_cybersecure_status_response(int *http_status)
{
    struct json_object *aegis = app_ubus_invoke_object_timeout("dreamingwrt.aegis", "status", NULL, 1500);
    struct json_object *data = json_object_new_object();

    if (http_status)
        *http_status = 200;
    if (aegis) {
        json_object_object_add(data, "available", json_object_new_boolean(1));
        json_object_object_add(data, "enabled", json_object_new_boolean(app_nc_json_bool(aegis, "enabled", 0)));
        json_object_object_add(data, "provider", json_object_new_string("dreamingwrt-aegisxd"));
        json_object_object_add(data, "enhanced_available", json_object_new_boolean(app_nc_json_bool(webd_obj_child_obj(aegis, "enhanced"), "available", 0)));
        {
            int schema = 0;
            int total_events = webd_insights_aegis_events_count_cached(&schema);
            char policy_scope[64] = "unavailable";
            struct json_object *breakdown = NULL;
            int dns = 0, rep = 0, ids = 0, route = 0, other = 0;

            webd_insights_aegis_policy_type_counts_cached(policy_scope, sizeof(policy_scope),
                &breakdown, &dns, &rep, &ids, &route, &other);
            json_object_object_add(data, "aegis_events_supported", json_object_new_boolean(schema));
            json_object_object_add(data, "aegis_events", json_object_new_int(total_events));
            json_object_object_add(data, "policy_scope", json_object_new_string(total_events > 0 ? policy_scope : "unavailable"));
            json_object_object_add(data, "policy_type_breakdown", breakdown ? breakdown : json_object_new_object());
            json_object_object_add(data, "dns_filter_policy_hit_supported", json_object_new_boolean(dns > 0));
            json_object_object_add(data, "reputation_ip_policy_hit_supported", json_object_new_boolean(rep > 0));
            json_object_object_add(data, "reputation_ip_per_flow_hit_supported", json_object_new_boolean(1));
            json_object_object_add(data, "reputation_ip_per_flow_precision",
                                   json_object_new_string("conntrack_flow_snapshot"));
            json_object_object_add(data, "reputation_ip_drop_confirmed_supported", json_object_new_boolean(1));
            json_object_object_add(data, "reputation_ip_drop_confirmed_source", json_object_new_string("nft_counter_delta"));
            json_object_object_add(data, "ids_ips_policy_hit_supported", json_object_new_boolean(ids > 0));
            json_object_object_add(data, "policy_route_hit_supported", json_object_new_boolean(route > 0));
            json_object_object_add(data, "full_policy_supported", json_object_new_boolean(0));
        }
        json_object_object_add(data, "aegis", aegis);
    } else {
        json_object_object_add(data, "available", json_object_new_boolean(0));
        json_object_object_add(data, "enabled", json_object_new_boolean(0));
        json_object_object_add(data, "provider", json_object_new_string("dreamingwrt-aegisxd"));
        json_object_object_add(data, "enhanced_available", json_object_new_boolean(0));
        json_object_object_add(data, "reason", json_object_new_string("aegisxd_unavailable"));
    }
    json_object_object_add(data, "activation_action", json_object_new_string("open_aegis_settings"));
    json_object_object_add(data, "status_api", json_object_new_string("/api/v1/aegis/status"));
    return webd_envelope(data, "webd.insights_cybersecure");
}

static int webd_write_all(int fd, const void *buf, size_t len)
{
    const unsigned char *p = (const unsigned char *)buf;
    size_t off = 0;

    while (off < len) {
        ssize_t n = write(fd, p + off, len - off);

        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (n == 0)
            return -1;
        off += (size_t)n;
    }
    return 0;
}

static int webd_read_exact(int fd, void *buf, size_t len)
{
    unsigned char *p = (unsigned char *)buf;
    size_t off = 0;

    while (off < len) {
        ssize_t n = read(fd, p + off, len - off);

        if (n < 0) {
            if (errno == EINTR)
                continue;
            return -1;
        }
        if (n == 0)
            return -1;
        off += (size_t)n;
    }
    return 0;
}

static void webd_base64_encode(const unsigned char *in, size_t in_len,
                               char *out, size_t out_len)
{
    static const char tbl[] =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    size_t i = 0, j = 0;

    if (!out || out_len == 0)
        return;
    out[0] = '\0';
    while (i < in_len && j + 4 < out_len) {
        size_t rem = in_len - i;
        unsigned int a = in[i++];
        unsigned int b = rem > 1 ? in[i++] : 0;
        unsigned int c = rem > 2 ? in[i++] : 0;

        out[j++] = tbl[(a >> 2) & 0x3f];
        out[j++] = tbl[((a & 0x3) << 4) | ((b >> 4) & 0xf)];
        out[j++] = rem > 1 ? tbl[((b & 0xf) << 2) | ((c >> 6) & 0x3)] : '=';
        out[j++] = rem > 2 ? tbl[c & 0x3f] : '=';
    }
    out[j] = '\0';
}

static int webd_ws_accept_key(const char *client_key, char *out, size_t out_len)
{
    char src[256];
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len = 0;

    if (!client_key || !client_key[0] || !out || out_len == 0)
        return -1;
    if (snprintf(src, sizeof(src), "%s%s", client_key, WEBD_WS_GUID) >= (int)sizeof(src))
        return -1;
    if (!EVP_Digest(src, strlen(src), digest, &digest_len, EVP_sha1(), NULL))
        return -1;
    webd_base64_encode(digest, digest_len, out, out_len);
    return out[0] ? 0 : -1;
}

static int webd_ws_send_frame(int fd, int opcode, const char *payload)
{
    unsigned char hdr[10];
    size_t len = payload ? strlen(payload) : 0;
    int hlen = 0;

    hdr[hlen++] = (unsigned char)(0x80 | (opcode & 0x0f));
    if (len < 126) {
        hdr[hlen++] = (unsigned char)len;
    } else if (len <= 65535) {
        hdr[hlen++] = 126;
        hdr[hlen++] = (unsigned char)((len >> 8) & 0xff);
        hdr[hlen++] = (unsigned char)(len & 0xff);
    } else {
        int i;

        hdr[hlen++] = 127;
        for (i = 7; i >= 0; i--)
            hdr[hlen++] = (unsigned char)(((uint64_t)len >> (i * 8)) & 0xff);
    }
    if (webd_write_all(fd, hdr, (size_t)hlen) != 0)
        return -1;
    if (len > 0 && webd_write_all(fd, payload, len) != 0)
        return -1;
    return 0;
}

static int webd_ws_send_json(int fd, struct json_object *obj)
{
    const char *s = obj ? json_object_to_json_string_ext(obj, JSON_C_TO_STRING_PLAIN) : "{}";
    return webd_ws_send_frame(fd, 1, s ? s : "{}");
}

static int webd_ws_read_frame(int fd, char *out, size_t out_len, int *opcode)
{
    unsigned char hdr[2];
    unsigned char mask[4];
    unsigned char payload[WEBD_WS_MAX_PAYLOAD + 1];
    uint64_t len;
    size_t i;

    if (!out || out_len == 0 || !opcode)
        return -1;
    out[0] = '\0';
    if (webd_read_exact(fd, hdr, 2) != 0)
        return -1;
    *opcode = hdr[0] & 0x0f;
    len = hdr[1] & 0x7f;
    if (len == 126) {
        unsigned char ext[2];
        if (webd_read_exact(fd, ext, 2) != 0)
            return -1;
        len = ((uint64_t)ext[0] << 8) | ext[1];
    } else if (len == 127) {
        unsigned char ext[8];
        if (webd_read_exact(fd, ext, 8) != 0)
            return -1;
        len = 0;
        for (i = 0; i < 8; i++)
            len = (len << 8) | ext[i];
    }
    if (!(hdr[1] & 0x80) || len > WEBD_WS_MAX_PAYLOAD || len >= out_len)
        return -1;
    if (webd_read_exact(fd, mask, 4) != 0)
        return -1;
    if (len > 0 && webd_read_exact(fd, payload, (size_t)len) != 0)
        return -1;
    for (i = 0; i < (size_t)len; i++)
        out[i] = (char)(payload[i] ^ mask[i % 4]);
    out[len] = '\0';
    return (int)len;
}

typedef struct {
    int dashboard_metrics;
    int dashboard_throughput;
    int topology_flow;
    int wan_metrics;
    int route_status;
    int clients_metrics;
    int apps_metrics;
    int client_overview;
    int client_protocols;
    int client_connections;
    int client_conntrack;
    int notifications;
    int logs_events;
    int web_appearance;
    int insights_flows_summary;
    int insights_flows_geo;
    int insights_activity_rate;
    int insights_activity_traffic;
    int insights_status;
} webd_ws_topics_t;

static int webd_ws_topics_any(const webd_ws_topics_t *topics)
{
    return topics &&
           (topics->dashboard_metrics || topics->dashboard_throughput ||
            topics->topology_flow || topics->wan_metrics ||
            topics->route_status ||
            topics->clients_metrics || topics->apps_metrics ||
            topics->client_overview || topics->client_protocols ||
            topics->client_connections || topics->client_conntrack ||
            topics->notifications ||
            topics->logs_events ||
            topics->web_appearance ||
            topics->insights_flows_summary || topics->insights_flows_geo ||
            topics->insights_activity_rate || topics->insights_activity_traffic ||
            topics->insights_status);
}

static int webd_ws_topics_need_core_snapshot(const webd_ws_topics_t *topics)
{
    if (!topics)
        return 1;
    return topics->dashboard_metrics || topics->dashboard_throughput ||
           topics->topology_flow || topics->wan_metrics ||
           topics->clients_metrics || topics->apps_metrics || topics->insights_flows_summary ||
           topics->insights_flows_geo || topics->insights_activity_rate ||
           topics->insights_activity_traffic || topics->insights_status;
}

static int webd_ws_topics_only_throughput(const webd_ws_topics_t *topics)
{
    webd_ws_topics_t only;

    if (!topics || !topics->dashboard_throughput)
        return 0;
    memset(&only, 0, sizeof(only));
    only.dashboard_throughput = 1;
    return memcmp(topics, &only, sizeof(only)) == 0;
}

static int webd_ws_topics_have_fast_core(const webd_ws_topics_t *topics)
{
    return !topics || topics->dashboard_metrics || topics->topology_flow ||
           topics->wan_metrics || topics->clients_metrics ||
           topics->apps_metrics;
}

static webd_ws_topics_t webd_ws_all_fast_core_topics(void)
{
    webd_ws_topics_t topics;

    memset(&topics, 0, sizeof(topics));
    topics.dashboard_metrics = 1;
    topics.topology_flow = 1;
    topics.wan_metrics = 1;
    topics.clients_metrics = 1;
    topics.apps_metrics = 1;
    return topics;
}

static webd_ws_topics_t webd_ws_fast_topics(const webd_ws_topics_t *topics)
{
    webd_ws_topics_t out;

    memset(&out, 0, sizeof(out));
    if (!topics) {
        out.dashboard_metrics = 1;
        return out;
    }
    out.dashboard_metrics = topics->dashboard_metrics;
    out.dashboard_throughput = topics->dashboard_throughput;
    out.topology_flow = topics->topology_flow;
    out.wan_metrics = topics->wan_metrics;
    out.route_status = topics->route_status;
    out.clients_metrics = topics->clients_metrics;
    out.apps_metrics = topics->apps_metrics;
    out.client_overview = topics->client_overview;
    out.client_protocols = topics->client_protocols;
    out.client_connections = topics->client_connections;
    out.client_conntrack = topics->client_conntrack;
    out.notifications = topics->notifications;
    out.logs_events = topics->logs_events;
    out.web_appearance = topics->web_appearance;
    return out;
}

static webd_ws_topics_t webd_ws_insights_topics(const webd_ws_topics_t *topics)
{
    webd_ws_topics_t out;

    memset(&out, 0, sizeof(out));
    if (!topics)
        return out;
    out.insights_flows_summary = topics->insights_flows_summary;
    out.insights_flows_geo = topics->insights_flows_geo;
    out.insights_activity_rate = topics->insights_activity_rate;
    out.insights_activity_traffic = topics->insights_activity_traffic;
    out.insights_status = topics->insights_status;
    return out;
}

static void webd_ws_topics_set(webd_ws_topics_t *topics, const char *topic, int enabled)
{
    if (!topics || !topic)
        return;
    if (!strcmp(topic, "dashboard.metrics"))
        topics->dashboard_metrics = enabled;
    else if (!strcmp(topic, "dashboard.throughput"))
        topics->dashboard_throughput = enabled;
    else if (!strcmp(topic, "topology.flow"))
        topics->topology_flow = enabled;
    else if (!strcmp(topic, "wan.metrics"))
        topics->wan_metrics = enabled;
    else if (!strcmp(topic, "route.status"))
        topics->route_status = enabled;
    else if (!strcmp(topic, "clients.metrics"))
        topics->clients_metrics = enabled;
    else if (!strcmp(topic, "apps.metrics"))
        topics->apps_metrics = enabled;
    else if (!strcmp(topic, "client.overview"))
        topics->client_overview = enabled;
    else if (!strcmp(topic, "client.protocols") || !strcmp(topic, "client.protocol"))
        topics->client_protocols = enabled;
    else if (!strcmp(topic, "client.connections"))
        topics->client_connections = enabled;
    else if (!strcmp(topic, "client.conntrack"))
        topics->client_conntrack = enabled;
    else if (!strcmp(topic, "notifications") || !strcmp(topic, "notify.events"))
        topics->notifications = enabled;
    else if (!strcmp(topic, "logs.events") || !strcmp(topic, "logs.realtime") ||
             !strcmp(topic, "log.events") || !strcmp(topic, "system.logs"))
        topics->logs_events = enabled;
    else if (!strcmp(topic, "web.appearance"))
        topics->web_appearance = enabled;
    else if (!strcmp(topic, "insights.flows.summary"))
        topics->insights_flows_summary = enabled;
    else if (!strcmp(topic, "insights.flows.geo"))
        topics->insights_flows_geo = enabled;
    else if (!strcmp(topic, "insights.activity.rate"))
        topics->insights_activity_rate = enabled;
    else if (!strcmp(topic, "insights.activity.traffic"))
        topics->insights_activity_traffic = enabled;
    else if (!strcmp(topic, "insights.status"))
        topics->insights_status = enabled;
}

static void webd_ws_params_del_filter_keys(struct json_object *params)
{
    int i;

    if (!params)
        return;
    for (i = 0; i < (int)(sizeof(webd_insights_filter_fields) / sizeof(webd_insights_filter_fields[0])); i++) {
        const char *field = webd_insights_filter_fields[i];
        char exclude_key[96];

        json_object_object_del(params, field);
        snprintf(exclude_key, sizeof(exclude_key), "exclude_%s", field);
        json_object_object_del(params, exclude_key);
    }
    json_object_object_del(params, "exclude");
}

static void webd_ws_params_set_ref(struct json_object *params,
                                   const char *key,
                                   struct json_object *value)
{
    if (!params || !key || !key[0] || !value)
        return;
    json_object_object_add(params, key, json_object_get(value));
}

static void webd_ws_params_copy_known_scalars(struct json_object *params,
                                              struct json_object *src)
{
    static const char *keys[] = {
        "period", "top", "pageNumber", "page_number", "pageSize", "page_size",
        "timestampFrom", "timestampTo", "ts_from", "ts_to", "start", "end",
        "mac", "client_mac",
        "search_text", "searchText", "query", "q", "mode", "anchor", "matrix_limit", "includeUnidentified",
        "cursor_seq", "since_seq", "after_seq", "last_seq",
        "cursor_rowid", "since_rowid", "after_rowid", "last_rowid",
        "cursor_ts", "since_ts", "after_ts", "last_ts",
        "cursor_id", "since_id", "after_id", "last_id",
        "incremental", "delta"
    };
    int i;

    if (!params || !src || !json_object_is_type(src, json_type_object))
        return;
    for (i = 0; i < (int)(sizeof(keys) / sizeof(keys[0])); i++) {
        struct json_object *v = NULL;

        if (json_object_object_get_ex(src, keys[i], &v) && v)
            webd_ws_params_set_ref(params, keys[i], v);
    }
    {
        static const char *array_keys[] = {
            "categories", "events", "deviceMacs", "clientDeviceMacs",
            "adminIds", "severities", "programs"
        };

        for (i = 0; i < (int)(sizeof(array_keys) / sizeof(array_keys[0])); i++) {
            struct json_object *v = NULL;

            if (json_object_object_get_ex(src, array_keys[i], &v) && v &&
                json_object_is_type(v, json_type_array))
                webd_ws_params_set_ref(params, array_keys[i], v);
        }
    }
}

static void webd_ws_params_apply_filter_obj(struct json_object *params,
                                            struct json_object *src,
                                            int replace_filters)
{
    struct json_object *include = NULL;
    struct json_object *exclude = NULL;
    struct json_object *exclude_out = NULL;
    int i;

    if (!params || !src || !json_object_is_type(src, json_type_object))
        return;
    if (replace_filters)
        webd_ws_params_del_filter_keys(params);

    json_object_object_get_ex(src, "include", &include);
    json_object_object_get_ex(src, "exclude", &exclude);
    if (exclude && json_object_is_type(exclude, json_type_object))
        exclude_out = json_object_new_object();

    for (i = 0; i < (int)(sizeof(webd_insights_filter_fields) / sizeof(webd_insights_filter_fields[0])); i++) {
        const char *field = webd_insights_filter_fields[i];
        struct json_object *v = NULL;
        char exclude_key[96];

        if (include && json_object_is_type(include, json_type_object) &&
            json_object_object_get_ex(include, field, &v) && v)
            webd_ws_params_set_ref(params, field, v);
        else if (json_object_object_get_ex(src, field, &v) && v)
            webd_ws_params_set_ref(params, field, v);

        snprintf(exclude_key, sizeof(exclude_key), "exclude_%s", field);
        v = NULL;
        if (exclude && json_object_is_type(exclude, json_type_object) &&
            json_object_object_get_ex(exclude, field, &v) && v) {
            webd_ws_params_set_ref(params, exclude_key, v);
            if (exclude_out)
                webd_ws_params_set_ref(exclude_out, field, v);
        } else if (json_object_object_get_ex(src, exclude_key, &v) && v) {
            webd_ws_params_set_ref(params, exclude_key, v);
        }
    }
    if (exclude_out)
        json_object_object_add(params, "exclude", exclude_out);
}

static int webd_ws_params_object_has_filters(struct json_object *src)
{
    struct json_object *dummy = NULL;
    int i;

    if (!src || !json_object_is_type(src, json_type_object))
        return 0;
    if (json_object_object_get_ex(src, "include", &dummy) ||
        json_object_object_get_ex(src, "exclude", &dummy))
        return 1;
    for (i = 0; i < (int)(sizeof(webd_insights_filter_fields) / sizeof(webd_insights_filter_fields[0])); i++) {
        const char *field = webd_insights_filter_fields[i];
        char exclude_key[96];

        if (json_object_object_get_ex(src, field, &dummy))
            return 1;
        snprintf(exclude_key, sizeof(exclude_key), "exclude_%s", field);
        if (json_object_object_get_ex(src, exclude_key, &dummy))
            return 1;
    }
    return 0;
}

static void webd_ws_params_apply_object(struct json_object **params_ref,
                                        struct json_object *src,
                                        int replace_filters)
{
    struct json_object *filters = NULL;

    if (!params_ref || !src || !json_object_is_type(src, json_type_object))
        return;
    if (!*params_ref)
        *params_ref = json_object_new_object();
    webd_ws_params_copy_known_scalars(*params_ref, src);
    if (webd_ws_params_object_has_filters(src))
        webd_ws_params_apply_filter_obj(*params_ref, src, replace_filters);
    if (json_object_object_get_ex(src, "filters", &filters) && filters)
        webd_ws_params_apply_filter_obj(*params_ref, filters, replace_filters);
}

static void webd_ws_apply_client_msg(webd_ws_topics_t *topics,
                                     struct json_object **params_ref,
                                     const char *payload)
{
    struct json_object *msg = payload ? json_tokener_parse(payload) : NULL;
    struct json_object *arr = NULL;
    struct json_object *params = NULL;
    const char *type;
    int enabled;
    int i;

    if (!msg)
        return;
    type = app_nc_json_str(msg, "type", "");
    enabled = strcmp(type, "unsubscribe") != 0;
    if ((!strcmp(type, "subscribe") || !strcmp(type, "unsubscribe") || !strcmp(type, "update")) &&
        json_object_object_get_ex(msg, "topics", &arr) && arr &&
        json_object_is_type(arr, json_type_array)) {
        for (i = 0; i < (int)json_object_array_length(arr); i++)
            webd_ws_topics_set(topics, json_object_get_string(json_object_array_get_idx(arr, i)), enabled);
    }
    if (!strcmp(type, "subscribe") || !strcmp(type, "update")) {
        webd_ws_params_apply_object(params_ref, msg, 1);
        if (json_object_object_get_ex(msg, "params", &params) && params)
            webd_ws_params_apply_object(params_ref, params, 1);
    } else if (!strcmp(type, "ack")) {
        webd_ws_params_apply_object(params_ref, msg, 0);
        if (json_object_object_get_ex(msg, "params", &params) && params)
            webd_ws_params_apply_object(params_ref, params, 0);
    }
    json_object_put(msg);
}

static struct json_object *webd_ws_event(const char *kind, const char *topic, struct json_object *data)
{
    static uint64_t sequence;
    struct json_object *root = json_object_new_object();

    json_object_object_add(root, "type", json_object_new_string(kind ? kind : "event"));
    if (topic && topic[0])
        json_object_object_add(root, "topic", json_object_new_string(topic));
    json_object_object_add(root, "seq",
                           json_object_new_int64((int64_t)__sync_add_and_fetch(&sequence, 1)));
    json_object_object_add(root, "ts", json_object_new_int64(now_s()));
    if (data)
        json_object_object_add(root, "data", data);
    else
        json_object_object_add(root, "data", json_object_new_object());
    return root;
}

static struct json_object *webd_ws_error_msg(const char *code, const char *message)
{
    struct json_object *root = json_object_new_object();

    json_object_object_add(root, "type", json_object_new_string("error"));
    json_object_object_add(root, "code", json_object_new_string(code ? code : "error"));
    json_object_object_add(root, "message", json_object_new_string(message ? message : ""));
    json_object_object_add(root, "ts", json_object_new_int64(now_s()));
    return root;
}

static struct json_object *webd_ws_topics_request(const webd_ws_topics_t *topics)
{
    struct json_object *req = json_object_new_object();
    struct json_object *arr = json_object_new_array();

    if (!req || !arr) {
        if (req)
            json_object_put(req);
        if (arr)
            json_object_put(arr);
        return NULL;
    }
    if (!topics || topics->dashboard_metrics) {
        json_object_array_add(arr, json_object_new_string("dashboard.metrics"));
        json_object_object_add(req, "dashboard_metrics", json_object_new_boolean(1));
    }
    if (topics && topics->dashboard_throughput) {
        json_object_array_add(arr, json_object_new_string("dashboard.throughput"));
        json_object_object_add(req, "dashboard_throughput", json_object_new_boolean(1));
        json_object_object_add(req, "throughput_interval_ms",
                               json_object_new_int(WEBD_WS_THROUGHPUT_INTERVAL_MS));
    }
    if (topics && topics->topology_flow) {
        json_object_array_add(arr, json_object_new_string("topology.flow"));
        json_object_object_add(req, "topology_flow", json_object_new_boolean(1));
    }
    if (topics && topics->wan_metrics) {
        json_object_array_add(arr, json_object_new_string("wan.metrics"));
        json_object_object_add(req, "wan_metrics", json_object_new_boolean(1));
    }
    if (topics && topics->clients_metrics) {
        json_object_array_add(arr, json_object_new_string("clients.metrics"));
        json_object_object_add(req, "clients_metrics", json_object_new_boolean(1));
    }
    if (topics && topics->apps_metrics) {
        json_object_array_add(arr, json_object_new_string("apps.metrics"));
        json_object_object_add(req, "apps_metrics", json_object_new_boolean(1));
    }
    if (topics && topics->insights_flows_summary) {
        json_object_array_add(arr, json_object_new_string("insights.flows.summary"));
        json_object_object_add(req, "insights_flows_summary", json_object_new_boolean(1));
    }
    if (topics && topics->insights_flows_geo) {
        json_object_array_add(arr, json_object_new_string("insights.flows.geo"));
        json_object_object_add(req, "insights_flows_geo", json_object_new_boolean(1));
    }
    if (topics && topics->insights_activity_rate) {
        json_object_array_add(arr, json_object_new_string("insights.activity.rate"));
        json_object_object_add(req, "insights_activity_rate", json_object_new_boolean(1));
    }
    if (topics && topics->insights_activity_traffic) {
        json_object_array_add(arr, json_object_new_string("insights.activity.traffic"));
        json_object_object_add(req, "insights_activity_traffic", json_object_new_boolean(1));
    }
    if (topics && topics->insights_status) {
        json_object_array_add(arr, json_object_new_string("insights.status"));
        json_object_object_add(req, "insights_status", json_object_new_boolean(1));
    }
    json_object_object_add(req, "topics", arr);
    return req;
}

