static struct json_object *app_authentication_write(const char *method,
                                                    struct json_object *payload,
                                                    const char *resource_id,
                                                    int inject_id,
                                                    const char *device_id,
                                                    int *http_status)
{
    struct json_object *params = payload;
    struct json_object *owned_params = NULL;
    struct json_object *response;
    const char *audit_id = resource_id ? resource_id : "";

    if (inject_id) {
        owned_params = app_json_id_payload(resource_id, payload);
        json_object_object_add(owned_params, "_update", json_object_new_boolean(1));
        params = owned_params;
    }
    response = app_ubus_object_or_error("dreamingwrt.authd", method, params);
    if (http_status)
        *http_status = app_response_status(response, *http_status);
    if (!audit_id[0] && payload && json_object_is_type(payload, json_type_object)) {
        const char *body_id = app_nc_json_str(payload, "id", "");
        const char *batch_id = app_nc_json_str(payload, "batch_id", "");

        if (body_id[0] && webd_safe_token(body_id) && !strstr(body_id, ".."))
            audit_id = body_id;
        else if (batch_id[0] && webd_safe_token(batch_id) && !strstr(batch_id, ".."))
            audit_id = batch_id;
    }
    if (!audit_id[0] && response) {
        struct json_object *data = webd_obj_child_obj(response, "data");
        const char *response_id = app_nc_json_str(data, "id", "");
        const char *response_batch_id = app_nc_json_str(data, "batch_id", "");

        if (response_id[0] && webd_safe_token(response_id) &&
            strcmp(response_id, ".") && !strstr(response_id, ".."))
            audit_id = response_id;
        else if (response_batch_id[0] && webd_safe_token(response_batch_id) &&
                 strcmp(response_batch_id, ".") && !strstr(response_batch_id, ".."))
            audit_id = response_batch_id;
    }
    jmx_app_audit_log(device_id && device_id[0] ? device_id : "http",
                      device_id ? device_id : "", method, "medium", audit_id, "", "");
    if (owned_params)
        json_object_put(owned_params);
    return response;
}

