        json_object_object_add(data, "realtime_websocket", json_object_new_boolean(1));
        json_object_object_add(data, "signature_update_browser_upload", json_object_new_boolean(1));
        json_object_object_add(data, "signature_update_validate", json_object_new_boolean(1));
        json_object_object_add(data, "signature_update_apply", json_object_new_boolean(1));
