        json_object_object_add(data, "flash_operation_status", json_object_new_boolean(otad_available));
        json_object_object_add(data, "flash_sysupgrade", json_object_new_boolean(ab_available));
        json_object_object_add(data, "flash_ab_update", json_object_new_boolean(ab_available));
        json_object_object_add(data, "realtime_topics", json_object_new_string("dashboard.metrics,dashboard.throughput,topology.flow,wan.metrics,route.status,clients.metrics,apps.metrics,client.overview,client.protocols,client.connections,client.conntrack,notifications,logs.events,insights.flows.summary,insights.flows.geo,insights.activity.rate,insights.activity.traffic,insights.status"));
