        resp = json_object_new_object();
        json_object_object_add(resp, "devices", arr);
        json_object_object_add(resp, "ok", json_object_new_boolean(1));
        json_object_object_add(cap, "role_write", json_object_new_boolean(1));
        json_object_object_add(cap, "enabled_write", json_object_new_boolean(1));
        json_object_object_add(cap, "delete", json_object_new_boolean(1));
        json_object_object_add(cap, "last_owner_protection", json_object_new_boolean(1));
