        char mac_buf[32] = {0};
        const char *slash = strchr(mac_part, '/');
        if (slash) { size_t len = slash - mac_part; if (len < sizeof(mac_buf)) strncpy(mac_buf, mac_part, len); }
        struct json_object *params = json_object_new_object();
